create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q55316917', 'Dinosaure (Dinosaur) est un jeu vidéo d''aventure développé par Ubisoft Montréal et édité par Ubisoft, sorti en 2000 sur Windows, Dreamcast, PlayStation, PlayStation 2 et Game Boy Color.

Il est adapté du long-métrage d''animation du même nom.', 'https://fr.wikipedia.org/wiki/Dinosaure_(jeu_vid%C3%A9o)'),
  ('Q737821', 'Lego Racers 2 est un jeu vidéo de course développé par Attention to Detail et édité par Lego Software, sorti en 2001 sur Windows, PlayStation 2 et Game Boy Advance.

Il fait suite à Lego Racers.', 'https://fr.wikipedia.org/wiki/Lego_Racers_2'),
  ('Q736528', 'Enter the Matrix est un jeu vidéo en vue à la troisième personne sorti simultanément sur PlayStation 2, Xbox, GameCube et PC en 2003. Il est fondé sur la trilogie des films Matrix (notamment sur Matrix Reloaded).

Il a été développé par Shiny Entertainment et édité par Infogrames sous la marque Atari.', 'https://fr.wikipedia.org/wiki/Enter_the_Matrix'),
  ('Q733488', 'The King of Fighter XI est un jeu de combat en 2D de la série des The King of Fighters. Il est sorti durant l''année 2005.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_XI'),
  ('Q74630', 'Lego Indiana Jones: La Trilogie originale (Lego Indiana Jones: The Original Adventures) est un jeu vidéo d''action-aventure, sorti en 2008, développé par Traveller''s Tales et édité par LucasArts.

Basé sur la saga Indiana Jones et la gamme de jouets éponyme, il adapte avec humour les trois premiers films de la série: Les Aventuriers de l''arche perdue (1981), Le Temple maudit (1984) et La Dernière Croisade (1989). Les personnages et les décors y étant représentés sous la forme de briques Lego, le jeu se joue seul ou en mode coopératif à deux joueurs et combine des éléments du jeu de plateforme, d''énigmes et de combats. Il propose 83 personnages jouables dotés de capacités spécifiques. Au fil des niveaux, le joueur collecte des pièces, évite des pièges, construit des structures en Lego et affronte des ennemis. Certaines mécaniques, comme l''escalade, le balancement et l''utilisation d''objets comme armes, constituent des ajouts par rapport aux précédents jeux Lego développés par Traveller''s Tales.', 'https://fr.wikipedia.org/wiki/Lego_Indiana_Jones_:_La_Trilogie_originale'),
  ('Q74545', 'Lego Batman, le jeu vidéo est un jeu vidéo d''action-aventure développé par Traveller''s Tales et édité par Warner Bros. Games en 2008. Il est basé sur l''univers de Batman, mais avec des personnages et décors en Lego.

C''est la troisième licence à rejoindre les jeux vidéo Lego, après Lego Star Wars et Lego Indiana Jones. Contrairement à ses prédécesseurs, le jeu ne reprend pas exactement la trame de films en particulier, mais reprend de nombreux personnages et lieux de son univers. Ce jeu, dans lequel l''humour est omniprésent, se veut être un mélange d''hommage et de parodie du héros de Gotham City.', 'https://fr.wikipedia.org/wiki/Lego_Batman,_le_jeu_vid%C3%A9o'),
  ('Q82050', 'Tales of the Abyss est un jeu vidéo de rôle développé par Namco Tales Studio et édité par Namco. Il sort sur PlayStation 2 en décembre 2005 au Japon puis en octobre 2006 en Amérique du Nord.

Une version 3DS est également sortie le 30 juin 2011 au Japon, le 25 novembre 2011 en Europe et le 14 février 2012 aux États-Unis.', 'https://fr.wikipedia.org/wiki/Tales_of_the_Abyss'),
  ('Q533304', 'Tom Clancy''s Splinter Cell: Chaos Theory est un jeu vidéo d''infiltration, développé par Ubisoft Montréal, sorti sur PC, PlayStation 2, Xbox, GameCube, Nintendo DS et N-Gage en 2005. Il constitue le troisième opus de la série de jeux video Splinter Cell. Il s''agit du premier titre de la série à ne pas inclure de niveau bonus pour la PS2 (une centrale nucléaire dans le premier et une jungle dans Pandora Tomorrow).

Le jeu fut censuré en Corée du Sud jusqu''à fin 2006, car il relate une guerre entre les deux Corées. Un remake, titré Tom Clancy''s Splinter Cell 3D, est sorti le 25 mars 2011 sur Nintendo 3DS.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Splinter_Cell:_Chaos_Theory'),
  ('Q538015', 'NBA Street est un jeu vidéo de streetball (basket-ball de rue) édité par EA Sports BIG et développé par EA Canada. Il est sorti en 2001 sur PlayStation 2 et en 2002 sur GameCube. Il s''agit du premier opus de la série des NBA Street, suivi de NBA Street Vol.2.', 'https://fr.wikipedia.org/wiki/NBA_Street'),
  ('Q568951', 'Tales of Rebirth, est un jeu vidéo développé par Namco Tales Studio et édité par Namco. Il s’agit d’un jeu de rôle publié sur PlayStation 2 en décembre 2004 au Japon et réédité sur PSP en 2008. Il fait partie de la série des Tales of.', 'https://fr.wikipedia.org/wiki/Tales_of_Rebirth'),
  ('Q568609', 'Persona 4, initialement commercialisé en interne sous le nom Shin Megami Tensei: Persona 4 est un jeu de rôle développé et édité par Atlus (publié en France par Square Enix Europe, en Australie par Ubisoft et au Japon comme en Amérique du Nord par Atlus). C''est le sixième jeu de la série Persona. Le jeu est sorti au Japon en premier le 10 juillet 2008, puis en Corée le 31 octobre 2008, aux États-Unis le 9 décembre 2008, et enfin en Europe le 13 mars 2009.

Le jeu a été très bien accueilli par la critique, bien qu''il soit sorti sur une PlayStation 2 en fin de vie.

Un portage remasterisé et titré Persona 4 Golden est sorti sur PlayStation Vita le 14 juin 2012 au Japon, le 20 novembre 2012 en Amérique du Nord et le 22 février 2013 en Europe. Cette version apporte des graphismes retravaillés, de nouvelles cinématiques, un nouveau personnage portant le nom de Marie, deux nouveaux Liens Sociaux, deux Personae ainsi que des fonctionnalités en ligne permettant d''aider ou de demander de l''aide aux autres joueurs parcourant le même donjon.', 'https://fr.wikipedia.org/wiki/Persona_4'),
  ('Q578147', 'Burnout Dominator est un jeu vidéo de course développé par Criterion Games et édité par Electronic Arts sorti en 2007 sur PlayStation 2 et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Burnout_Dominator'),
  ('Q577381', 'Freedom Fighters est un jeu vidéo d''action, développé par IO Interactive, sorti sur PC, GameCube, PlayStation 2 et Xbox, en 2003.', 'https://fr.wikipedia.org/wiki/Freedom_Fighters'),
  ('Q577532', 'WWE SmackDown! vs. RAW 2006 (sous-titré Exciting Pro Wrestling 7 au Japon), est un jeu vidéo de catch adapté sur console PlayStation 2 et console portable PlayStation Portable commercialisé par THQ et développé par Yuke''s Media Creation. Le jeu fait partie de la série des jeux vidéo de WWE SmackDown vs. Raw basée sur la promotion de la fédération de catch World Wrestling Entertainment (WWE). Il est précédé du jeu vidéo WWE SmackDown! vs. RAW (2004) et est suivi par WWE SmackDown vs. Raw 2007 (2006).

Le principal but du jeu est d''amener la réalité et l''authenticité des séries dans un nouveau jeu vidéo, surpassant la jouabilité similaire aux jeux d''arcade des précédents jeux vidéo SmackDown!. Également certains nouveaux styles de match sont inclus. Le jeu vidéo a également marqué la première fois qu''un jeu des séries SmackDown! est commercialisé sur console portable (PlayStation Portable).', 'https://fr.wikipedia.org/wiki/WWE_SmackDown!_vs._Raw_2006'),
  ('Q583601', 'Devil May Cry 2 est un jeu vidéo d''action développé par Capcom Production Studio 1 et édité par Capcom en 2003 sur PlayStation 2. Une collection HD regroupant les trois premiers épisodes est sortie sur PC, PlayStation 3, Xbox 360, PlayStation 4 et Xbox One. Le jeu est ensuite porté sur Nintendo Switch.', 'https://fr.wikipedia.org/wiki/Devil_May_Cry_2'),
  ('Q587752', 'Dragon Ball Z: Budokai est un jeu vidéo de combat développé par Dimps sur l''univers de Dragon Ball Z. Le jeu est disponible depuis 2002 sur PlayStation 2 et depuis 2003 sur GameCube.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Budokai'),
  ('Q1139696', 'Le Parrain est un jeu vidéo GTA-like développé par EA Redwood Shores et édité par Electronic Arts, sorti en 2006 sur PlayStation 2, Windows, Xbox, Xbox 360 et PlayStation Portable. Il s''agit d''une adaptation vidéoludique du roman de Mario Puzo et du film de 1972, le Parrain, de Francis Ford Coppola.

Deux nouvelles éditions sont sorties en mars 2007 sur PlayStation 3 et Wii, respectivement sous-titrées Édition du Don et Pouvoir et Manipulation. Sa suite, Le Parrain 2, est sortie en 2009.', 'https://fr.wikipedia.org/wiki/Le_Parrain_(jeu_vid%C3%A9o)'),
  ('Q1140411', 'Shadow the Hedgehog est un jeu vidéo sorti en novembre 2005 sur GameCube, PlayStation 2 et Xbox, développé par Sega Studio USA, l’ancienne division de la Sonic Team, appartenant à Sega. Le joueur y incarne Shadow, issu de la série Sonic The Hedgehog, apparu pour la première fois dans le jeu Sonic Adventure 2 en 2001.

Il fait office de suite de Sonic Heroes qui était la suite de Sonic Adventure 2 et de Sonic Adventure.

Le jeu a connu un succès commercial, se vendant à 2,07 millions d''exemplaires en mars 2007.', 'https://fr.wikipedia.org/wiki/Shadow_the_Hedgehog'),
  ('Q1139501', 'Scarface: The World Is Yours est un jeu vidéo GTA-like, où le joueur incarne Tony Montana le protagoniste cubain du film Scarface.', 'https://fr.wikipedia.org/wiki/Scarface:_The_World_Is_Yours'),
  ('Q936011', 'DoDonPachi Daiōjō est un jeu vidéo développé par Cave et édité par AMI. Il s’agit d’un shoot ''em up à défilement vertical de type manic shooter. Il est paru en 2002 sur borne d''arcade, puis porté sur PlayStation 2 en 2003. C''est le troisième épisode de la série DonPachi développé par Cave, et le quatrième opus en comptant DoDonPachi II développé par la société taïwanaise IGS.

Il a été porté sur iOS sous le titre DoDonPachi Blissful Death.', 'https://fr.wikipedia.org/wiki/DoDonPachi_Dai%C5%8Dj%C5%8D'),
  ('Q940320', 'La Pucelle: Tactics est un jeu vidéo de tactical RPG sorti en 2002 sur PlayStation 2 au Japon, en 2004 aux États-Unis et 2005 en France. C''est un jeu de stratégie au tour par tour, en 3D isométrique.', 'https://fr.wikipedia.org/wiki/La_Pucelle_:_Tactics'),
  ('Q936968', 'No One Lives Forever (NOLF) est un jeu vidéo de tir à la première personne développé par Monolith Productions sorti en 2000 sur PC. Dans des décors très années 1960, le jeu parodie les aventures de James Bond, le joueur incarnant une agent des services secrets britanniques. Le jeu connaît une suite en 2002: No One Lives Forever 2: Le CRIME est éternel.

Les tentatives de re-masterisation du jeu sont bloquées par le statut compliqué des droits d''auteurs le concernant, les sociétés concernées ayant elles-mêmes reconnu ignorer laquelle d''entre elles les possède, tout en bloquant les tentatives de Nightdive Studios. Cette situation a amené des fans du jeu et de sa suite à mettre en ligne des versions remastérisées en libre accès, afin de forcer une clarification de la situation juridique tout en permettant l''accès aux joueurs nostalgiques.', 'https://fr.wikipedia.org/wiki/No_One_Lives_Forever'),
  ('Q943073', 'Tribes: Aerial Assault est un jeu vidéo de tir à la première personne développé par Inevitable Entertainment et édité par Sierra Entertainment, sorti en 2002 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Tribes:_Aerial_Assault'),
  ('Q518560', 'Monster Hunter 2 est un jeu vidéo de type action-RPG développé et édité par Capcom, sorti en 2006 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Monster_Hunter_2'),
  ('Q526700', 'Jak II: Hors-la-loi (Jak II) est un jeu vidéo d''action-aventure développé par Naughty Dog et édité par Sony Computer Entertainment, sorti en 2003 sur PlayStation 2. Il s''agit de la suite de Jak and Daxter: The Precursor Legacy, et est le second opus de la série Jak and Daxter en général.

En 2012, le jeu est remastérisé en haute définition et porté dans une compilation, disponible sur PlayStation 3 et également sur PlayStation Vita en 2013, nommé The Jak and Daxter Trilogy.

C''est le premier jeu du studio à avoir une suite en dehors de la saga Crash Bandicoot.', 'https://fr.wikipedia.org/wiki/Jak_II_:_Hors-la-loi'),
  ('Q943377', 'Spyro: Enter the Dragonfly est un jeu vidéo de plates-formes développé par les studios californiens Equinoxe Digital Entertainment et Check Six Studios, et édité par Universal Interactive Studios. Il est sorti sur PlayStation 2 et GameCube en novembre 2002. Il s''agit du quatrième opus de la série principale Spyro the Dragon, qui fait suite à Spyro: Year of the Dragon, sorti en 2000 sur PlayStation.

Le scénario met en scène Spyro, un dragon violet, dans sa quête pour retrouver les libellules destinées à devenir les compagnons des jeunes dragons, que Ripto a éparpillées dans les Royaumes des Dragons. Le joueur traverse neuf niveaux afin de les récupérer. Ceux-ci comportent des mini-jeux, dans lesquels Spyro pilote un planeur, un vaisseau spatial, un char ou encore, chevauche une raie manta.', 'https://fr.wikipedia.org/wiki/Spyro:_Enter_the_Dragonfly'),
  ('Q943546', 'Spyro: A Hero''s Tail est un jeu vidéo de plates-formes développé par le studio britannique Eurocom et édité par Vivendi Universal Games. Il est sorti sur PlayStation 2, Xbox et GameCube en novembre 2004. Il s''agit du cinquième opus de la série principale Spyro the Dragon, qui fait suite à Spyro: Enter the Dragonfly, sorti en 2002 sur PlayStation 2 et GameCube.

Le scénario met en scène Spyro, un dragon violet, dans sa quête pour détruire les gemmes sombres disséminées par Red dans les Royaumes des Dragons afin de drainer toute forme de vie et l''alimenter en énergie. Dans les différents niveaux traversés, le joueur accède à des mini-jeux, dans lesquels Spyro utilise un canon à tourelle pour éliminer des ennemis, mais il peut également contrôler d''autres personnages pour réaliser des missions particulières comme Chasseur, Sparx la libellule dans l''exploration de cavités sombres et Blinky la taupe dans des lieux souterrains.', 'https://fr.wikipedia.org/wiki/Spyro:_A_Hero%27s_Tail'),
  ('Q1142527', 'Tekken Tag Tournament 鉄拳タッグトーナメント est un jeu vidéo de combat développé et édité par Namco en 1999 sur borne d''arcade et porté l''année suivante sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Tekken_Tag_Tournament'),
  ('Q1143512', 'Gradius V est un jeu vidéo développé par Treasure et édité par Konami, sorti en 2004 sur PlayStation 2. Il s''agit d''un shoot them up à défilement horizontal. Les studios de G.rev et de Konami Computer Entertainment Tokyo ont également participé à son développement.

À l''instar des précédentes productions du studio japonais Treasure, comme Radiant Silvergun et Ikaruga, Gradius V allie des qualités de réalisation et d''inventivité. La difficulté du jeu est importante et exige un réel apprentissage pour espérer progresser. Au fur et à mesure de sa progression, le joueur découvre un gameplay parfaitement maîtrisé.', 'https://fr.wikipedia.org/wiki/Gradius_V'),
  ('Q1143473', 'Yoake Mae Yori Ruri Iro Na est un eroge de type aventure (au sens nippon du terme) de l''éditeur August. Le titre fut initialement publié sur PC (2005), puis porté sur PlayStation 2 par le studio ARIA (prévu en 2006). Les deux jeux ont pour sous-titre -Brighter than dawning blue- et la version console se voit adjoindre deux scénarios supplémentaires dont l''un pour un personnage secondaire.

Une adaptation animée télévisée, produite par le studio DAUME, est diffusée au Japon entre octobre et décembre 2006 et s''intitule Yoake Mae Yori Ruri Iro Na -Crescent　Love-. Cette diffusion fait suite à la série Tsuki wa Higashi ni Hi wa Nishi ni ~Operation Sanctuary~, une autre adaptation d''un jeu publié par August.', 'https://fr.wikipedia.org/wiki/Yoake_mae_yori_ruri_iro_na'),
  ('Q1144140', 'Onimusha: Warlords est un jeu vidéo de type hack ''n'' slash développé par Capcom Production Studio 2 et édité par Capcom en 2001 sur PlayStation 2. Une adaptation a été réalisée en 2002 sur Xbox, intitulée Genma Onimusha, et une autre sous Windows en 2003, mais uniquement commercialisée en Asie. Une version remasterisée développé par le studio taïwanais Néobards Entertaiment est prévue uniquement en dématérialisé pour le 15 janvier 2019 sur Nintendo Switch, Playstation 4, Xbox One et Steam.

Onimusha a marqué le renouveau du jeu de combat à progression et a été récompensé d''un succès critique et commercial. L''histoire du jeu, bien que fictive, a la particularité de se dérouler dans le contexte historique japonais de l''époque Sengoku, à la fin du XVIe siècle.', 'https://fr.wikipedia.org/wiki/Onimusha:_Warlords'),
  ('Q946557', 'Richard Burns Rally est un jeu vidéo de course développé par Warthog Games et édité par SCi en 2004 sur PlayStation 2, Xbox et Windows. Il a été porté en 2005 sur Gizmondo. Développé en collaboration avec le pilote anglais Richard Burns, le titre est considéré à sa sortie comme une référence de la simulation de rallye automobile.', 'https://fr.wikipedia.org/wiki/Richard_Burns_Rally'),
  ('Q945822', 'Aliens vs. Predator: Extinction est un jeu vidéo sorti en 2003 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Aliens_vs._Predator:_Extinction'),
  ('Q134208', 'X-Men Legends II: L''Avènement d''Apocalypse, ou X-Men Legends II: Rise of Apocalypse en Amérique du Nord, est un jeu vidéo d''action-rôle développé par Raven Software et édité par Activision sur GameCube, Windows, PlayStation 2, et Xbox en 2005. Parallèlement, une version exclusive sur PlayStation Portable, du fait de son format portable, a été développée par Vicarious Visions.', 'https://fr.wikipedia.org/wiki/X-Men_Legends_II_:_L%27Av%C3%A8nement_d%27Apocalypse'),
  ('Q137924', 'FIFA 12 (FIFA Soccer 12 en Amérique du Nord) est un jeu vidéo de football développé par EA Canada et édité par Electronic Arts, commercialisé en 2011 sur Microsoft Windows, PlayStation 3, Xbox 360, Nintendo 3DS, PlayStation Portable, PlayStation Vita, PlayStation 2 et Wii. C''est le dix-huitième jeu de la franchise FIFA Football et la suite de FIFA 11. La version PlayStation Vita s''intitule simplement FIFA Football.

Une Ultimate Edition était disponible au lancement du jeu. Elle donnait la possibilité d''obtenir 24 packs Gold Ultimate Team (4 par mois pendant six mois) dans la mode de jeu Ultimate Team.', 'https://fr.wikipedia.org/wiki/FIFA_12'),
  ('Q137977', 'FIFA 13 (FIFA Soccer 13 en Amérique du Nord) est un jeu vidéo de football développé par EA Canada et édité par Electronic Arts. Il est sorti les 25 et 27 septembre 2012 sur PC, PlayStation 3, Xbox 360, Nintendo 3DS, PlayStation Portable, PlayStation Vita, PlayStation 2, Wii et Wii U. C''est le dix-neuvième jeu de la franchise FIFA Football et par la même occasion la suite de FIFA 12.', 'https://fr.wikipedia.org/wiki/FIFA_13'),
  ('Q133992', 'X-Men 2: La Vengeance de Wolverine, ou X2: Wolverine''s Revenge en Amérique du Nord, est un jeu vidéo de type beat them all développé par GenePool Software et édité par Activision sur GameCube, Windows, PlayStation 2, et Xbox en avril 2003. Parallèlement, une version exclusive sur Game Boy Advance, du fait de son format portable, a été développée par Vicarious Visions.', 'https://fr.wikipedia.org/wiki/X-Men_2_:_La_Vengeance_de_Wolverine'),
  ('Q588754', 'Nanatsuiro Drops est un jeu vidéo de type visual novel sorti en 2006 sur PC. Il a été adapté en roman, manga (2 versions) et série animée japonaise comportant 12 épisodes.', 'https://fr.wikipedia.org/wiki/Nanatsuiro_Drops'),
  ('Q1168322', 'F1 2001 est un jeu vidéo de course développé par EA Bright Light et édité par EA Sports, sorti en 2001 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/F1_2001_(jeu_vid%C3%A9o)'),
  ('Q1166163', 'Dark Chronicle est un jeu vidéo de type action-RPG développé par Level-5 et édité par Sony Computer Entertainment. Il est sorti fin 2002 sur PlayStation 2. Depuis Janvier 2016, le jeu est disponible sur le Store US et EU du Playstation Network en version remastérisée pour Playstation 4.', 'https://fr.wikipedia.org/wiki/Dark_Chronicle'),
  ('Q1166169', 'Dark Cloud est un jeu vidéo d''action-RPG développé par Level-5 et édité par Sony Computer Entertainment sur PlayStation 2. Il est sorti au Japon le 14 décembre 2000, puis le 29 mai 2001 en Amérique du Nord et le 21 septembre de la même année en Europe. Il est ensuite réédité en 2002 aux États-Unis dans la gamme Greatest Hits, et au Japon dans les gammes The Best et PS2 Classics en 2002 et en 2012, et enfin en téléchargement sur le PlayStation Store, pour la PlayStation 4, depuis décembre 2015.

Le jeu met en scène un jeune garçon de l''Ouest, Toan, qui voit son village être détruit par une entité maléfique, le Génie des Ténèbres, créé 400 ans plus tôt par le roi de l''Est pendant la guerre avec l''Ouest, et réveillé par Flag Gilgister, un militaire de l''Est. Toan est chargé par le Roi Magicien, un esprit de la nature, de reconstruire les parties du monde détruites par le Génie et de le vaincre. En chemin, il est rejoint par cinq alliés afin de l''aider dans sa quête.', 'https://fr.wikipedia.org/wiki/Dark_Cloud'),
  ('Q933535', 'Wild Arms 5, connu sous le nom de Wild Arms: The Fifth Vanguard au Japon, est un jeu vidéo de rôle développé par Media.Vision et édité par Sony Computer Entertainment en 2006 sur PlayStation 2. Le jeu est sorti pour fêter les 10 ans de la série. Il prend toujours place dans le monde de Filgaia, une fois de plus en péril. Le personnage principal est un jeune homme de 16 ans se nommant Dean Stark.', 'https://fr.wikipedia.org/wiki/Wild_Arms_5'),
  ('Q934720', 'WWE SmackDown! vs. Raw (souvent abrégé et écourté en WWE SvR et connu sous le titre Exciting Pro Wrestling 6: SmackDown! vs. RAW au Japon) est un jeu vidéo de lutte professionnelle commercialisé sur console PlayStation 2 par THQ et développé par Yuke''s. Le jeu vidéo fait partie de la série des WWE SmackDown vs. Raw (le premier jeu intitulé SmackDown vs. Raw) et est basé sur la promotion World Wrestling Entertainment (WWE). Ce jeu est la suite de WWE SmackDown! Here Comes the Pain (2003) et est suivi de WWE SmackDown! vs. Raw 2006 (2005). C''est également le tout premier jeu de la WWE sur PlayStation 2 qui est relié en ligne. Cependant, les joueurs peuvent uniquement choisir en un match en solo ou en mode Bra and Panties.', 'https://fr.wikipedia.org/wiki/WWE_SmackDown!_vs._Raw'),
  ('Q539018', 'Blood Omen 2: Legacy of Kain est un jeu vidéo d''action-aventure de la série Legacy of Kain, développé par Crystal Dynamics, sorti sur GameCube, PlayStation 2, Windows, Xbox en 2002.', 'https://fr.wikipedia.org/wiki/Blood_Omen_2:_Legacy_of_Kain'),
  ('Q539431', 'Pro Evolution Soccer Management (ou PES Management) est un jeu vidéo de management sportif dans le domaine du football édité et développé par Konami en 2006 sur PlayStation 2.

Ce jeu fait partie de la série des Pro Evolution Soccer.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_Management'),
  ('Q568115', 'Castlevania: Lament of Innocence, sorti simplement sous le nom Castlevania en Europe et au Japon, est un jeu vidéo créé par Konami sur PlayStation 2. Le jeu se déroule en 1094, ce qui en fait le premier épisode chronologique de la série Castlevania, remplaçant Castlevania Legends qui est exclu de la chronologie officielle.', 'https://fr.wikipedia.org/wiki/Castlevania:_Lament_of_Innocence'),
  ('Q747370', 'Serious Sam: Next Encounter est un jeu vidéo de tir subjectif édité par Global Star Software et développé par Climax Group. Il est sorti sur GameCube et sur PlayStation 2 en 2004. Le joueur y incarne Sam Stone, dit ''Serious'', un tueur d''extra-terrestres, et doit parcourir des univers à la recherche de Mental, le roi des extra-terrestres.', 'https://fr.wikipedia.org/wiki/Serious_Sam:_Next_Encounter'),
  ('Q748754', 'Fallout: Brotherhood of Steel est un jeu vidéo de type action-RPG situé dans l''univers de Fallout, édité sur PlayStation 2 et Xbox par Interplay en 2004.', 'https://fr.wikipedia.org/wiki/Fallout:_Brotherhood_of_Steel'),
  ('Q747882', 'Astérix et Obélix XXL, ou Asterix & Obelix: Kick Buttix aux États-Unis, est un jeu vidéo d’action-aventure développé par le studio français Étranges Libellules et édité par Atari Inc. Il est publié en Europe en novembre 2003 sur PlayStation 2, puis en juin 2004 en Amérique du Nord, simultanément à des versions pour Nintendo GameCube et Game Boy Advance.

Il s’agit du premier jeu Astérix développé en trois dimensions et de la vingt-et-unième adaptation vidéoludique de la bande dessinée créée par Albert Uderzo et René Goscinny. Le jeu met en scène Astérix, Obélix et leur chien Idéfix dans une aventure se déroulant en 50 av. J.-C., à travers plusieurs provinces de l’Empire romain.', 'https://fr.wikipedia.org/wiki/Ast%C3%A9rix_et_Ob%C3%A9lix_XXL'),
  ('Q153547', 'The Incredible Hulk est un jeu vidéo d''action-aventure développé par Edge of Reality et édité par Sega sur Wii, PlayStation 2, PlayStation 3, Xbox 360 et Windows en juin 2008. Parallèlement, une version exclusive sur Nintendo DS, du fait de son format portable, a été développée par Amaze Entertainment.', 'https://fr.wikipedia.org/wiki/The_Incredible_Hulk_(jeu_vid%C3%A9o,_2008)'),
  ('Q161202', '007: Quitte ou double (007: Everything or Nothing) est un jeu vidéo de tir en vue à la troisième personne comprenant des séquences de jeu de course, sorti en 2004. Il est co-développé par THX et EA Redwood Shores et édité par Electronic Arts.

Il met en vedette l''agent secret d''Ian Fleming, James Bond, également connu sous son nom de code, 007.

Comme dans les jeux vidéos précédents (007: Espion pour cible et 007: Nightfire), le célèbre agent anglais est représenté, pour la dernière fois, sous les traits de Pierce Brosnan.

C''est également le dernier jeu de la série James Bond à posséder un titre et une histoire originale jusqu''à la sortie de Blood Stone 007 en 2010.', 'https://fr.wikipedia.org/wiki/007_:_Quitte_ou_double'),
  ('Q170003', 'Ratchet and Clank (Ratchet & Clank) est un jeu vidéo de plates-formes, de tir en vue à la troisième personne et d''action développé par Insomniac Games et édité par Sony Computer Entertainment en 2002 sur PlayStation 2. Le jeu est réédité pour la gamme The Best le 3 juillet 2003, pour la gamme Platinum le 22 août 2003 et pour la gamme Greatest Hits le 4 novembre 2003. C''est le premier épisode de la série Ratchet and Clank.

L''histoire du jeu suit Ratchet, un lombax, et Clank, un robot, qui se sont rencontrés sur Veldin, la planète où a grandi Ratchet (mais sa planète natale est Fastoon). Clank découvre que Drek, le président de la race des blargs envisage de créer une nouvelle planète pour sauver son espèce, entraînant la destruction des autres planètes de la galaxie. Le robot persuade Ratchet de l''aider dans sa quête et de trouver de l''aide auprès du capitaine Qwark, mais ils découvrent rapidement qu''ils doivent sauver la galaxie par leurs propres moyens.', 'https://fr.wikipedia.org/wiki/Ratchet_and_Clank_(jeu_vid%C3%A9o,_2002)'),
  ('Q161188', '007: Nightfire est un jeu vidéo de tir à la première personne fondé sur l''univers de James Bond. Édité par Electronic Arts, le titre est sorti en novembre 2002 sur PC, PlayStation 2, GameCube et Xbox et en mars 2003 sur Game Boy Advance.

Le personnage est conçu d’après l''acteur Pierce Brosnan alors titulaire du rôle. On y retrouve des éléments incontournables de Bond tels que la montre laser, le PP7 (Walther PPK) silencieux, mais aussi les James Bond girls.', 'https://fr.wikipedia.org/wiki/007:_Nightfire'),
  ('Q1150685', 'Sonic Riders: Zero Gravity, connu sous le nom de Sonic Riders Shooting Star Story au Japon, est un jeu vidéo de course développé et édité par Sega. Il est sorti en janvier 2008 sur Wii et PlayStation 2.', 'https://fr.wikipedia.org/wiki/Sonic_Riders:_Zero_Gravity'),
  ('Q1150627', 'Metal Slug Anthology (Metal Slug Complete au Japon) est un jeu vidéo de run and gun développé par SNK Playmore et édité par Atari Inc., disponible sur Wii, PSP et PlayStation 2. Le jeu est une compilation de la série Metal Slug, il contient donc les jeux Metal Slug, Metal Slug 2, Metal Slug X, Metal Slug 3, Metal Slug 4, Metal Slug 5 et Metal Slug 6.', 'https://fr.wikipedia.org/wiki/Metal_Slug_Anthology'),
  ('Q1150928', 'Sonic Unleashed: La Malédiction du Hérisson, connu au Japon sous le titre Sonic World Adventure, est un jeu vidéo de plates-formes développé par Dimps, Sonic Team et édité par Sega sorti en novembre 2008 sur Wii, Xbox 360, PlayStation 2 et PlayStation 3.', 'https://fr.wikipedia.org/wiki/Sonic_Unleashed_:_La_Mal%C3%A9diction_du_H%C3%A9risson'),
  ('Q1150209', 'Naruto: Ultimate Ninja 2 est la suite du jeu Naruto: Ultimate Ninja. Cet opus est déjà sorti au Japon en 2004 sous le nom Naruto: Narutimate Hero 2. Il est sorti en Europe le 19 octobre 2007.', 'https://fr.wikipedia.org/wiki/Naruto:_Ultimate_Ninja_2'),
  ('Q1148043', 'FlatOut est un jeu vidéo de course automobile créé par le développeur finlandais Bugbear Entertainment et sorti en novembre 2004.', 'https://fr.wikipedia.org/wiki/FlatOut'),
  ('Q749023', 'Harry Potter et le Prisonnier d''Azkaban est un jeu vidéo d''action-aventure publié par Electronic Arts inspiré du roman Harry Potter et le Prisonnier d''Azkaban de J.K. Rowling, et du film homonyme. Il est publié en 2004 sur PC ainsi que sur consoles PlayStation 2, Xbox, GameCube et Game Boy Advance.

Sur PC, le jeu a été développé avec l''Unreal Engine. Sur consoles de salon, il l''a été avec RenderWare.', 'https://fr.wikipedia.org/wiki/Harry_Potter_et_le_Prisonnier_d%27Azkaban_(jeu_vid%C3%A9o)'),
  ('Q1139272', 'Crazy Taxi est un jeu vidéo développé par Hitmaker et édité par Sega, sorti en arcade sur Naomi en 1999 et sur Dreamcast le 24 janvier 2000, puis par la suite édité sur PC, PlayStation 2 et GameCube. Le jeu a reçu le label Sega All Stars sur Dreamcast.', 'https://fr.wikipedia.org/wiki/Crazy_Taxi_(jeu_vid%C3%A9o)'),
  ('Q1138744', 'Coupe du monde FIFA 2006 (FIFA World Cup: Germany 2006) est un jeu vidéo de football développé par Electronic Arts et sorti en 2006.

C''est le jeu officiel de la Coupe du monde de football 2006 qui a eu lieu en Allemagne.

Il existe plusieurs modes de jeu: Match Amical, Séance de tirs au but, Entraînement, Coupe du monde ou Défi Mondial.

On peut retrouver 126 sélections nationales dans ce jeu.

L''intégralité des phases qualificatives de tous les continents sont jouables. Ainsi durant une même partie, vous pourrez jouer les phases qualificatives et la coupe du monde avec la même sélection.

Le jeu offre la possibilité de disputer des matchs importants de la Coupe du Monde via le mode "Défi Mondial" où votre objectif sera d''inverser le cours de l''histoire, pour faire soulever le graal mondial à l''équipe qui, lors de la vraie coupe du monde, avait été vaincue (vous incarnez par exemple la Suède lors du match Suède-Brésil de la Coupe du Monde 1958 ou encore les Pays-Bas lors de la finale RFA - Pays-Bas de la Coupe du Monde 1974). L''une des singularités de ce mode consiste à jouer ce type d''affiche du passé avec les effectifs actuels des sélections concernées.', 'https://fr.wikipedia.org/wiki/Coupe_du_monde_FIFA_2006_(jeu_vid%C3%A9o)'),
  ('Q1139044', 'Les Simpson, le jeu (The Simpsons Game) est un jeu vidéo d''action et de plates-formes développé, édité et distribué par Electronic Arts sur PlayStation 2, PlayStation 3, PlayStation Portable, Xbox 360, Nintendo DS et Wii. Basé sur l''univers de la série télévisée d''animation Les Simpson, ainsi que sur le film du même nom, le jeu est commercialisé en Amérique du Nord en octobre 2007 et dans le reste du monde le mois suivant. Le jeu présente une histoire inédite rédigée par trois des scénaristes de la série: Tim Long, Matt Selman et Matt Warburton. Dans cette histoire, la famille Simpson découvre sa participation à un nouveau jeu vidéo des Simpson. Le jeu, comme la série, parodie des éléments de la culture populaire, des autres jeux vidéo, ainsi que son éditeur, Electronic Arts.', 'https://fr.wikipedia.org/wiki/Les_Simpson,_le_jeu'),
  ('Q739125', 'Pro Evolution Soccer 6 (Winning Eleven 10, abrégé PES 6) est un jeu vidéo de football qui est sorti en 2006 sur les consoles PlayStation 2, Nintendo DS, Xbox 360, PSP ainsi que sur PC.

Il fait partie de la série Pro Evolution Soccer adaptée de Winning Eleven (Version japonaise du jeu).', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_6'),
  ('Q743155', 'Prince of Persia: L''Âme du guerrier (Prince of Persia: Warrior Within en version originale) est un jeu vidéo développé par Ubisoft et édité en décembre 2004 pour la Xbox, la PlayStation 2, le GameCube et Microsoft Windows. Il est le deuxième volet de la trilogie des Sables du Temps (voir la série de jeux vidéo Prince of Persia).

L''intrigue du jeu reprend 7 ans après Prince of Persia: Les Sables du Temps, avec de nombreuses nouveautés, notamment au niveau des phases de combat. Le Prince (qui n''a toujours pas de nom), a désormais la capacité de manier deux armes en même temps, de dérober celle de ses ennemis et de les lancer. L''Âme du Guerrier a une ambiance bien plus sombre et brutale que son prédécesseur, et sa difficulté a été revue à la hausse.', 'https://fr.wikipedia.org/wiki/Prince_of_Persia_:_L%27%C3%82me_du_guerrier'),
  ('Q742834', 'Heroes of the Pacific est un simulateur de vol de combat se déroulant pendant la Seconde Guerre mondiale, dans l''Océan Pacifique, et opposant les Américains aux Japonais. Le jeu permet de revivre toutes les batailles du Pacifique menées contre les forces japonaises, de Pearl Harbor à Iwo Jima en passant par l''île de Wake, les îles Marshall, la mer de Corail, Midway, Guadalcanal, les îles Gilbert, les îles Mariannes et le Philippines. Quatre niveaux de difficulté sont proposés: Bleu, Pilote, Vétéran, As. Le jeu s''est vendu à plus de 600 000 exemplaires et son successeur Heroes Over Europe est sorti sur PlayStation 3, PC et Xbox 360 le 26 septembre 2009.', 'https://fr.wikipedia.org/wiki/Heroes_of_the_Pacific'),
  ('Q804850', 'Baldur''s Gate: Dark Alliance II est un jeu vidéo sorti sur PlayStation 2 et Xbox en 2004. Il s''agit de la suite de Baldur''s Gate: Dark Alliance développé par Snowblind Studios.', 'https://fr.wikipedia.org/wiki/Baldur%27s_Gate:_Dark_Alliance_II'),
  ('Q796916', 'Brothers in Arms: Road to Hill 30 est un jeu vidéo de tir à la première personne, développé par Gearbox Software, sorti sur PC, PlayStation 2, Xbox et Wii.

Ce jeu utilise comme trame scénaristique la Seconde Guerre mondiale, et plus précisément la bataille de Normandie. Il est avant tout un jeu de tir à la première personne mais donne une place importante à la tactique, via la gestion d''une équipe de combat, l''éloignant en cela des séries telles Medal of Honor ou encore Call of Duty.', 'https://fr.wikipedia.org/wiki/Brothers_in_Arms:_Road_to_Hill_30'),
  ('Q804851', 'Baldur''s Gate: Dark Alliance est un jeu vidéo édité par Interplay Entertainment et développé par Snowblind Studios, il est plutôt axé sur l''action et l''aventure que sur le côté jeu de rôle de ses prédécesseurs.

Le jeu sort le 14 décembre 2001 sur PlayStation 2 dans une version française intégrale, se jouant en solitaire, ou à deux. Les versions Xbox et GameCube sortent en 2003, et la version Game Boy Advance sort en 2004, elle est réalisée par le studio français Magic Pockets.', 'https://fr.wikipedia.org/wiki/Baldur%27s_Gate:_Dark_Alliance'),
  ('Q138130', 'Gungrave est un jeu vidéo de tir à la troisième personne sorti en 2002 sur PlayStation 2. Il a été développé par Red Entertainment et édité par Sega. Il a été conçu par Yasuhiro Nightow.

Une adaptation en un anime portant le même titre est parue en 2003. En 2004, Gungrave a par ailleurs connu une suite du nom de Gungrave: Overdose.', 'https://fr.wikipedia.org/wiki/Gungrave_(jeu_vid%C3%A9o)'),
  ('Q153423', 'The Incredible Hulk: Ultimate Destruction est un jeu vidéo d''action développé par Radical Entertainment et édité par Vivendi Universal Games sur GameCube, PlayStation 2, et Xbox en 2005.', 'https://fr.wikipedia.org/wiki/The_Incredible_Hulk:_Ultimate_Destruction'),
  ('Q149106', 'Grand Theft Auto III (souvent en abrégé GTA III ou GTA 3) est un jeu vidéo d''action-aventure en monde ouvert réalisé par Rockstar Games et développé par le studio DMA Design. Il est le troisième volet majeur ainsi que le cinquième jeu de la série Grand Theft Auto et se démarque des premiers épisodes par l''apparition d''un moteur 3D. Il est commercialisé en octobre 2001 sur PlayStation 2, en mai 2002 sur PC, en novembre 2003 sur Xbox, en 2010 sur OS X, en 2011 sur mobiles iOS et Android, puis en 2012 sur PlayStation 3 (PlayStation Network).

Le jeu simule la vie d''un criminel se déplaçant librement dans la ville de Liberty City. Le joueur a la possibilité de choisir entre plusieurs missions, ou peut se contenter de se promener dans la ville. L''histoire en elle-même ne représente qu''une partie du jeu, qui ne se termine jamais réellement. Les premiers épisodes de la série, qui proposaient une vue de dessus, n''ont pas eu le même impact que GTA III, qui a été un succès dès sa sortie, devenant l''un des jeux les plus vendus de 2001. La violence et la sexualité présentes dans le jeu ont été sources de polémiques et ont mené à des problèmes judiciaires.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto_III'),
  ('Q217241', '24 Heures chrono, le jeu est un jeu vidéo de tir à la troisième personne sur PlayStation 2 adapté de la série télévisée américaine 24 Heures chrono créée par la Fox. Le jeu est développé par SCE Studio Cambridge et édité en Europe par Sony Computer Entertainment, et en Amérique du Nord par 2K Games. Il est annoncé le 30 mars 2005, et sort en Amérique du Nord le 27 février 2006, puis en Europe le 15 mars 2006.

24 heures chrono, le jeu se décompose en plusieurs missions, dans lesquelles le joueur dirige des personnages issus de la série télévisée, et qui contiennent différents types de gameplay, tels que le tir à la troisième personne, la course et le puzzle game. La musique est composée par Sean Callery, le compositeur de la série, le scénario est écrit par Duppy Demetrius et l''équipe de production de la série, et les voix et l''apparence des acteurs sont reprises et intégrées au jeu. Le casting et l''interprétation de la version originale sont organisés par Blindlight.', 'https://fr.wikipedia.org/wiki/24_Heures_chrono,_le_jeu'),
  ('Q217638', 'Project: Snowblind est un jeu vidéo développé par Crystal Dynamics et édité par Eidos Interactive. Il s’agit d’un jeu de tir à la première personne, sorti sur PlayStation 2, Xbox et Windows en mars 2005.', 'https://fr.wikipedia.org/wiki/Project_Snowblind'),
  ('Q593822', 'NBA Live 06 est un jeu vidéo de basket-ball sorti en 2005 et fonctionne sur PlayStation 2, PlayStation Portable, Xbox, Xbox 360, Gamecube et téléphone mobile. Le jeu a été développé par EA Canada puis édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/NBA_Live_06'),
  ('Q592758', 'FIFA Street 2 est un jeu vidéo de football développé par EA Sports BIG et édité par Electronic Arts.

Le jeu est sorti le 2 mars 2006 sur PlayStation 2, PSP, PC, Nintendo Game Cube, Nintendo DS et Xbox.

Il fait partie de la série FIFA Street dont il est le deuxième épisode.', 'https://fr.wikipedia.org/wiki/FIFA_Street_2'),
  ('Q598150', 'Shrek 2 est un jeu vidéo d''action édité par Activision, et sorti sur GameCube, Playstation 2, Xbox et PC. Le jeu est basé sur le film d''animation éponyme: Shrek 2.', 'https://fr.wikipedia.org/wiki/Shrek_2_(jeu_vid%C3%A9o)'),
  ('Q600707', 'Hitman: Contracts est un jeu vidéo d''infiltration, développé par IO Interactive et édité par Eidos Interactive, sorti en 2004 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Hitman:_Contracts'),
  ('Q593897', 'Rocky est un jeu vidéo de boxe développé par Rage Software et édité par Ubisoft. Ce jeu est adapté de la série de films Rocky. Ce jeu est sorti sur Game Boy Advance, PlayStation 2, Gamecube et Xbox en 2002.', 'https://fr.wikipedia.org/wiki/Rocky_(jeu_vid%C3%A9o,_2002)'),
  ('Q1153197', 'Devil Kings, ou Sengoku Basara au Japon, est un jeu vidéo de type beat them all développé par Capcom Production Studio 4, et distribué en 2005 sur PlayStation 2. La trame principale se passe dans un Japon imaginaire, dans la période des guerres de royaume.

Le joueur choisit son guerrier parmi de nombreux personnages différents (daimyo, ninja, samourai, etc) qui représentent chacun un clan japonais. Chaque personnage possède des armes et des coups spéciaux particuliers. Ces coups sont appelés « Basara Waza ».', 'https://fr.wikipedia.org/wiki/Devil_Kings'),
  ('Q1150974', 'Neon Genesis Evangelion 2 est un jeu vidéo de type RPG sorti le 20 novembre 2003 sur PlayStation 2 puis ré-édité sur PlayStation Portable le 27 avril 2006. Il s''agît de la suite du jeu Neon Genesis Evangelion adapté de la série d''animation du même nom. Le jeu a été développé par Alfa System et édité par Bandai. Il n''a pas été commercialisé hors du Japon.

Ce jeu possède une place particulière parmi les œuvres dérivées de la franchise Evangelion. Le scénario de la série de Hideaki Anno comporte volontairement de nombreuses zones d''ombre et beaucoup de points restent inexpliqués à l''issue de son film conclusif. Or, Neon Genesis Evangelion 2 contient des « Classified Informations », des informations sur la toile de fond de l''univers d''Evangelion que le joueur peut découvrir. Cependant, si le studio Gainax a été impliqué dans le développement du jeu, il est impossible de savoir si ces informations proviennent directement d''Anno et si, donc, elles sont canoniques. Les fans considèrent généralement ces informations comme authentiques tant qu''elles ne sont pas contredites par la série ou les films.', 'https://fr.wikipedia.org/wiki/Neon_Genesis_Evangelion_2'),
  ('Q116578', 'Guitar Hero est un jeu de rythme sorti en 2005 aux États-Unis sur PlayStation 2. Il fait partie de la série Guitar Hero.

Le joueur dirige un guitariste et doit parvenir à jouer des chansons de rock avec le moins de fausses notes possible. Il est possible de jouer avec une guitare destinée au jeu, ou à la manette.', 'https://fr.wikipedia.org/wiki/Guitar_Hero'),
  ('Q110607', 'Clannad est un visual novel créé par la compagnie japonaise Key, auteur de Kanon et de Air, deux autres titres à succès. D''abord annoncé en 2001 pour une sortie en 2002, le développement a subi de nombreux retards. L''édition limitée pour PC est sortie le 28 mai 2004, l''édition normale le 8 août 2004. Le jeu a ensuite été porté sur PlayStation 2, PSP, Xbox 360 et PlayStation 3. Dans Clannad, l''histoire est linéaire et offre plusieurs scénarios prédéterminés selon les interactions entre le protagoniste et les différentes situations rencontrées. Le jeu se concentre sur 5 héroïnes différentes.

Contrairement à Kanon et à Air qui sont d''abord sortis en tant que jeu pour adultes puis republiés dans une version censurée pour être « tout public », Clannad est directement sorti en version tout public et ne contient ni scène érotique, ni même de fan service. Cependant le 25 novembre 2005, Key a réalisé un spin-off sous forme d''un jeu destiné aux adultes, Tomoyo After: It''s a Wonderful Life, qui prolonge le scénario de l''une des héroïnes Tomoyo Sakagami.', 'https://fr.wikipedia.org/wiki/Clannad_(visual_novel)'),
  ('Q219795', 'Need For Speed: Carbon est un jeu vidéo de course développé par EA Black Box et édité par Electronic Arts sorti en 2006 sur PlayStation 2, Wii, Windows, GameCube, PlayStation 3, Xbox, Xbox 360. La version sur consoles portables (GBA, Nintendo DS et PSP) est sous titrée Own The City et est différente de celle sur console de salon', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_Carbon'),
  ('Q752835', 'Silent Hill 2 est un jeu vidéo d''action-aventure de type survival horror développé par Konami CE Tokyo et sorti en 2001 sur PlayStation 2. Le jeu a été porté sur Xbox dans une version sous-titrée Inner Fears et a été réédité dans une version director''s cut sur PlayStation 2 et Windows en 2002. Le jeu fait partie de la série Silent Hill. Christophe Gans en a réalisé l''adaptation cinématographique en 2026, 20 ans après la sortie de l''adaptation du premier jeu de la série.

Il est disponible depuis mars 2012 dans une édition HD avec Silent Hill 3, sur PlayStation 3 et Xbox 360. Cette édition inclut également le scénario de Maria, Né de l''imaginaire, de Silent Hill 2.', 'https://fr.wikipedia.org/wiki/Silent_Hill_2'),
  ('Q997548', '12Riven: The Psi-Climinal of Integral, stylisé 12Riven: The Ψcliminal of Integral, est un jeu vidéo de type visual novel développé par KID et édité par Cyberfront, sorti en 2008 sur Windows, PlayStation 2 et PlayStation Portable. 12Riven est l''unique jeu de la série Integral, série qui reprend l''univers de la série Infinity. Le jeu peut-être considéré comme étant et de la série Integral et de la série Infinity puisque les développeurs l''on inclut dans le paquetage promotionnel Infinity Plus.', 'https://fr.wikipedia.org/wiki/12Riven:_The_Psi-Climinal_of_Integral'),
  ('Q775889', 'Dynasty Warriors 4, connu au Japon sous le titre Shin Sangokumusou 3, est un jeu vidéo de type hack ''n'' slash développé par Koei et sorti en 2003 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Dynasty_Warriors_4'),
  ('Q776587', 'Shin Megami Tensei: Digital Devil Saga 2 est un jeu vidéo de rôle, développé par Atlus en 2004. Il s''agit de la suite et de la fin de l''épopée de l''Embryon initiée par Digital Devil Saga.

Le jeu est sorti sur PlayStation 2 au Japon et aux États-Unis en 2005, et en Europe en 2007, sept mois après la sortie du premier opus. Il a été édité par Ghostlight en Europe.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei:_Digital_Devil_Saga_2'),
  ('Q780225', 'Battle Stadium D.O.N est un jeu vidéo de combat, développé par Eighting et Q Entertainment puis édité par Namco Bandai Games, sorti sur GameCube et PlayStation 2 le 20 juillet 2006 au Japon.', 'https://fr.wikipedia.org/wiki/Battle_Stadium_D.O.N'),
  ('Q775543', 'Mortal Kombat: Deadly Alliance (communément abrégé MK:DA) est un jeu vidéo de combat, qui représente chronologiquement le cinquième titre de la série Mortal Kombat. Il a été développé et produit par Midway, et il est sorti en France le 14 février 2003 sur GameCube, PlayStation 2, Xbox, Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat:_Deadly_Alliance'),
  ('Q951415', 'Les Sims: Permis de sortir (The Sims Bustin'' Out, littéralement: « Les Sims jaillissant dehors ») est le second titre de la série The Sims en version console vidéo. Bustin'' Out est sorti pour la PlayStation 2, la Xbox, la GameCube, la Game Boy Advance et la N-Gage au cours du quatrième trimestre de 2003 et permet au joueur de sortir de sa maison pour la premiere fois des sims.

Il se démarque par sa jouabilité davantage basée sur la gestion d''un seul Sim et aussi comportant des véhicules permettant de se déplacer d''une maison à une autre.', 'https://fr.wikipedia.org/wiki/Les_Sims_:_Permis_de_sortir'),
  ('Q946795', 'Max Payne 2: The Fall of Max Payne est un jeu vidéo de tir à la troisième personne développé par Remedy Entertainment et édite par Take 2 Interactive sur Windows en 2003. Rockstar Vienna s''est occupé du portage sur Xbox et PlayStation 2.

Dans Max Payne 2, le joueur contrôle Max Payne, un détective du New York City Police Department (NYPD) et fugitif désormais recherché pour meurtre dans New York commis à la fin du jeu Max Payne. Deux ans après les événements du premier opus, Max devient détective de la NYPD.

Le jeu vidéo a dans son ensemble été bien accueilli par les critiques. Cependant, le jeu ne s''est pas particulièrement bien vendu. Max Payne 2 a reçu de nombreuses récompenses et nominations de la part des sites références GamePro, IGN et GameSpy.', 'https://fr.wikipedia.org/wiki/Max_Payne_2:_The_Fall_of_Max_Payne'),
  ('Q953541', 'WWE SmackDown vs. Raw 2011 (aussi connu sous le diminutif de SVR 2011) est un jeu vidéo de catch édité par THQ et développé par Yuke''s Media Creation sur consoles PlayStation 2 (PS2), PlayStation 3 (PS3), PlayStation Portable (PSP), Wii et Xbox 360. C''est le tout dernier jeu de la série paru sous le titre officiel de WWE SmackDown vs. Raw.

WWE SmackDown vs. Raw 2011 est initialement commercialisé vers le 26 et 29 octobre 2010. Le jeu est basé sur les branches professionnelles de la fédération World Wrestling Entertainment (WWE), Raw et SmackDown. L''édition 2012 du jeu ne sort pas sous le titre classique, WWE Smackdown vs. Raw, mais sous le titre de WWE ''12.', 'https://fr.wikipedia.org/wiki/WWE_SmackDown_vs._Raw_2011'),
  ('Q954766', 'Ever 17: The Out of Infinity, souvent abrégé Ever 17 ou E17, est un jeu vidéo de type visual novel développé et édité par KID, sorti initialement en 2002 sur Dreamcast et PlayStation 2 puis sur Windows, Xbox 360, PlayStation Portable, iOS et Android. Il est la deuxième entrée de la série Infinity; il est précédé par Never 7: The End of Infinity — précédemment titré Infinity (PS1) et Infinity Cure (Neo-Geo Pocket). —et suivi par Remember 11: The Age of Infinity, 12Riven: The Psi-Climinal of Integral de la série dérivée Integral, et Code_18, jeu redémarrant la série. Le portage Windows a été traduit en anglais par l''entreprise Hirameki, commercialisé en 2005 en Amérique du Nord anglophone.', 'https://fr.wikipedia.org/wiki/Ever_17:_The_Out_of_Infinity'),
  ('Q953855', 'Def Jam Vendetta est un jeu vidéo de combat de rue sorti en 2003 sur PlayStation 2 et GameCube (édité par Electronic Arts) principalement entre rappeurs du label Def Jam comme DMX, Ludacris, Method Man, Redman ou encore Joe Budden. Le but du jeu est d''essayer d''enchaîner des combos très violents en réalisant des prises de catch. Chaque personnage a son propre style de combat et ses propres styles de combos. La bande sonore du jeu est essentiellement de la musique rap interprétée par chaque combattant du jeu. Ce premier volet ayant eu du succès, un second épisode a vu le jour en 2004 intitulé Def Jam: Fight For NY. Il fait son grand retour fin 2019', 'https://fr.wikipedia.org/wiki/Def_Jam_Vendetta'),
  ('Q949730', 'Worms 3D est un jeu vidéo de stratégie au tour par tour et d''artillerie édité par Sega et développé par Team17. Sorti en 2003 en Europe et en 2004 en Amérique du Nord sur GameCube, PlayStation 2, Xbox, PC et OS X, le jeu fait partie de la série Worms. Il s''agit du premier opus à afficher des graphismes en trois dimensions.', 'https://fr.wikipedia.org/wiki/Worms_3D'),
  ('Q950510', 'International Superstar Soccer 3 est un jeu vidéo de football sorti en 2003 sur GameCube, PlayStation 2 et Windows.', 'https://fr.wikipedia.org/wiki/International_Superstar_Soccer_3'),
  ('Q579477', 'Rise to Honour est un jeu vidéo de type beat them all et tir à la troisième personne développé et édité par SCEA, sorti en 2004 sur PlayStation 2.

Le jeu met en scène Jet Li dans le rôle Kit Yun, un officier de la police de Hong Kong sous couverture. Corey Yuen a travaillé sur les chorégraphies d''arts martiaux du jeu.', 'https://fr.wikipedia.org/wiki/Rise_to_Honour'),
  ('Q579105', 'The Suffering est un jeu vidéo créé par Surreal Software et édité par la société Midway Games basée aux États-Unis. Le jeu a pour contexte l''univers carcéral. Comme son nom l''indique, l''ambiance glauque vous plonge dans la perception de la souffrance et de vos peurs les plus inconsidérées.

The Suffering est un survival horror axé surtout sur l''action à l''image de Resident Evil, très loin de la conception d''un Silent Hill au niveau du traitement et du scénario, on retrouve pourtant des thèmes parfois similaires mais jamais approfondis.

Le héros principal a la particularité de pouvoir se changer en monstre.', 'https://fr.wikipedia.org/wiki/The_Suffering'),
  ('Q198092', 'The King of Fighters 2002: Challenge to Ultimate Battle est un jeu vidéo de combat développé par Eolith et édité par Eolith et Playmore en 2002 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES (NGM 265). C''est le neuvième épisode de la série The King of Fighters.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_2002:_Challenge_to_Ultimate_Battle'),
  ('Q213217', 'Mafia: The City of Lost Heaven est un jeu vidéo d''action-aventure développé par Illusion Softworks sorti en 2002 pour Microsoft Windows et édité par Gathering of Developers. Chaleureusement salué par la critique internationale, les développeurs ont alors porté le jeu sur PlayStation 2 et sur Xbox, qui fut édité en 2004 par Take Two Interactive. Les suites du jeu, Mafia II et Mafia III, sont sorties le 27 août 2010 et le 7 octobre 2016.', 'https://fr.wikipedia.org/wiki/Mafia:_The_City_of_Lost_Heaven'),
  ('Q1047938', 'Guitar Hero 3: Legends of Rock est un jeu vidéo de rythme développé par Neversoft et édité par RedOctane en 2007. Le jeu est disponible sur PlayStation 2, PlayStation 3, Wii, Xbox 360, Mac OS X et Windows. Il s''agit du troisième épisode de la série Guitar Hero.', 'https://fr.wikipedia.org/wiki/Guitar_Hero_3:_Legends_of_Rock'),
  ('Q1046160', 'Brunswick Pro Bowling est un jeu vidéo de bowling développé par Point of View, Inc..', 'https://fr.wikipedia.org/wiki/Brunswick_Pro_Bowling'),
  ('Q1037042', 'Hitman 2: Silent Assassin est un jeu vidéo d''infiltration, développé par IO Interactive, sorti en 2002 sur PC, PlayStation 2 et Xbox et en 2003 sur GameCube.', 'https://fr.wikipedia.org/wiki/Hitman_2:_Silent_Assassin'),
  ('Q1041461', 'Crisis Zone est un jeu vidéo de tir au pistolet développé par Namco et Gashin Sound System et édité par Namco. Il est sorti en arcade sur le System 23 en 2000, puis fut porté sur PlayStation 2 le 22 septembre 2004. Ce jeu fait partie de la série Time Crisis.', 'https://fr.wikipedia.org/wiki/Crisis_Zone'),
  ('Q1132810', 'Onimusha 2: Samurai''s Destiny est un jeu vidéo de type hack ''n'' slash développé par Capcom Production Studio 2 et édité par Capcom en 2002 sur PlayStation 2.

Une version remastérisée du jeu est sortie le 23 mai 2025 sur Windows, Nintendo Switch, Xbox One et PlayStation 4.', 'https://fr.wikipedia.org/wiki/Onimusha_2:_Samurai%27s_Destiny'),
  ('Q605271', 'Capcom vs. SNK 2: Millionaire Fighting 2001 est un jeu de combat en 2D développé par Capcom Production Studio 1 et édité par Capcom en août 2001 au Japon sur système Naomi GD-ROM. Il est d’abord sorti sur borne d’arcade avant d''apparaître dans le monde entier sur les consoles de jeu vidéo Dreamcast, PlayStation 2, GameCube et Xbox. Au Japon, le jeu est publié sous le titre de Capcom vs. SNK 2: Millionaire Fighting 2001.

Dans la jaquette version Dreamcast, un deuxième disque sur lequel le nom du jeu est Capcom Taisen Fan Disk est fourni, mais pas séparément. Il permet de regarder des vidéos de Capcom vs. SNK 2, regarder des images apparaissant dans le jeu précédent et enfin télécharger des données de sauvegarde pour certains jeux de Dreamcast (version japonaises, bien sûr).', 'https://fr.wikipedia.org/wiki/Capcom_vs._SNK_2:_Mark_of_the_Millennium_2001'),
  ('Q773981', 'Utawareru mono est un jeu vidéo développé par Leaf et édité par Aquaplus. À mi-chemin entre le visual novel et le tactical RPG, le jeu présente un certain nombre de scènes hentai. Il est sorti au Japon en avril 2002 sur Windows, puis porté sur PlayStation 2 en octobre 2006 et sur PlayStation Portable en mai 2009. Trois adaptations en mangas sont publiées par ASCII Media Works entre 2005 et 2010. Une adaptation en anime par le studio OLM est diffusée entre avril et septembre 2006. Plusieurs autres adaptations comme des anthologies ou des drama CD ont vu le jour.

Une suite vidéoludique intitulée Utawareru mono: Itsuwari no kamen est commercialisée en septembre 2015 sur PlayStation 3, PlayStation 4 et PlayStation Vita, couplée avec une adaptation en anime par le studio White Fox, diffusée entre octobre 2015 et mars 2016.', 'https://fr.wikipedia.org/wiki/Utawareru_mono'),
  ('Q753892', 'Prince of Persia: Les Deux Royaumes (Prince of Persia: The Two Thrones en anglais) est un jeu vidéo multi plates-formes développé par Ubisoft Montréal et Ubisoft Casablanca, et édité par Ubisoft en 2005.

Le jeu reprend l''orientation du précédent volet en étant assez sombre et brutal. Les Deux Royaumes est le troisième et dernier épisode de la trilogie des Sables du Temps. Il a été réédité sur PSP et Wii sous le nom de Prince of Persia: Rival Swords.', 'https://fr.wikipedia.org/wiki/Prince_of_Persia_:_Les_Deux_Royaumes'),
  ('Q769141', 'K 2000: The Game (Knight Rider: The Game) est un jeu vidéo basé sur la série télévisée K 2000 développé par Davilex Games et sorti le 22 novembre 2002 sous Windows et sur PlayStation 2.

Le jeu permet de prendre le contrôle de KITT dans une série de 15 missions incluant courses et explorations. Ainsi, le joueur devra partir à la poursuite de voitures et hélicoptères, mais également se rendre sur certains lieux pour y trouver et scanner des cibles précises. Il y croisera des personnages célèbres de la série comme Devon Miles, Bonnie Barstow, KARR ou Garth Knight.', 'https://fr.wikipedia.org/wiki/K_2000:_The_Game'),
  ('Q774869', 'Sega Soccer Slam est un jeu vidéo de football développé par Black Box Games, édité par Sega et sorti en 2002 sur GameCube, Xbox et PlayStation 2.

Ce jeu met en scène des équipes de 4 joueurs sur un terrain à dimension réduite. Les règles du jeu sont simples: il n''y en a pas ! Tous les moyens sont bons pour faire entrer le ballon dans les buts adverses. Ainsi, vous pouvez frapper vos adversaires, faire des tirs aériens hallucinants, ou détruire l''armure du gardien et le faire entrer dans ses cages. Les personnages sont complètement loufoques et ont un design très bande dessinée, voire cartoon.', 'https://fr.wikipedia.org/wiki/Sega_Soccer_Slam'),
  ('Q771481', 'Mana Khemia 2: Fall of Alchemy マナケミア2 〜おちた学園と錬金術士たち〜 (Mana Khemia 2 ~Ochita Gakuen to Renkinjutsushi Tachi~) est un jeu vidéo développé et édité par le studio japonais Gust Corporation. Il s’agit d’un jeu de rôle publié en 2008 au Japon et en 2009 en Amérique du Nord pour PlayStation 2.', 'https://fr.wikipedia.org/wiki/Mana_Khemia_2:_Fall_of_Alchemy'),
  ('Q94778', 'Grand Theft Auto: Liberty City Stories est un jeu vidéo d''action-aventure à monde ouvert, développé par Rockstar North et Rockstar Leeds, initialement commercialisé le 24 octobre 2005 sur PlayStation Portable. Il s''agit du neuvième jeu de la série Grand Theft Auto, précédé par Grand Theft Auto: San Andreas et suivi par Grand Theft Auto: Vice City Stories. Il est publié et distribué par Capcom au Japon. Il est porté sur PlayStation 3 via le PlayStation Network le 2 avril 2013.

Une version sur PlayStation 2 est sortie le 6 juin 2006 en Amérique du Nord et le 22 juin 2006 en Europe. À la période de sa sortie, la version PS2 est commercialisée moitié prix par rapport à celui de la version PSP. Le 17 décembre 2015, Rockstar Games annonce que le jeu sortira sur l''App Store d''Apple le jour même et est sorti sur Android le 11 février 2016.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto:_Liberty_City_Stories'),
  ('Q94640', 'Grand Theft Auto: Vice City Stories communément appelé GTA: Vice City Stories ou encore GTA: VCS est un jeu vidéo d''action-aventure en monde ouvert développé par les studios Rockstar Leeds et Rockstar North et distribué par Rockstar Games. Il s''agit du dixième jeu de la série Grand Theft Auto. Le jeu a été officiellement annoncé le 10 mai 2006 durant l''E3 à la fois par Rockstar et par Sony. GTA VCS devait sortir uniquement sur PSP, mais des raisons financières ont fait qu''une version pour PlayStation 2 est sortie le 9 mars 2007.

Comme Grand Theft Auto: Liberty City Stories, qui était un dérivé de Grand Theft Auto III, GTA VCS reprend largement le contenu de Grand Theft Auto: Vice City, mais offre un scénario et des missions qui lui sont propres. Il s''agit en effet d''un épisode préquelle. Les premières images du jeu dévoilées montraient la possibilité de nager et de piloter un hélicoptère, un bateau ou une motomarine.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto:_Vice_City_Stories'),
  ('Q94671', 'Grand Theft Auto: Vice City, communément appelé GTA: Vice City ou encore GTA: VC est un jeu vidéo de tir à la troisième personne à monde ouvert développé par Rockstar North et initialement publié par Rockstar Games le 29 octobre 2002 sur console PlayStation 2, le 12 mai 2003 sur Microsoft Windows, et le 31 octobre 2003 sur console Xbox. Il s''agit du sixième opus de la série Grand Theft Auto, et le premier volet principal depuis la sortie de son prédécesseur Grand Theft Auto III.

Grand Theft Auto: Vice City est joué en vision objective dans un environnement ouvert, permettant au joueur d''interagir à sa guise avec le jeu. Le scénario se déroule en 1986 dans la ville fictive de Vice City, inspirée de la ville américaine de Miami et de la culture américaine des années 1980. Le mode solo suit Tommy Vercetti, un ancien membre de la Mafia libéré de prison.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto:_Vice_City'),
  ('Q83265', 'Grand Theft Auto: San Andreas (souvent abrégé en GTA: San Andreas, San Andreas ou GTA: SA) est un jeu vidéo de tir à la troisième personne, de conduite et d''action-aventure en monde ouvert, développé par Rockstar North en Écosse (Royaume-Uni). Le jeu vidéo est initialement commercialisé en octobre 2004 sur console PlayStation 2. Il est, par la suite, commercialisé en juin 2005 sur console Xbox et sur Microsoft Windows (PC). Il est le septième opus en date de la série Grand Theft Auto, le dernier volet majeur de l''univers 3D avant le passage de la franchise à l''univers HD avec Grand Theft Auto IV.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto:_San_Andreas'),
  ('Q1169638', 'Alvin et les Chipmunks (Alvin and the Chipmunks) est un jeu vidéo de rythme développé par Sensory Sweep Studios et édité par Brash Entertainment, sorti en 2007 sur Windows, Wii, PlayStation 2 et Nintendo DS.

Il est adapté du film du même nom.', 'https://fr.wikipedia.org/wiki/Alvin_et_les_Chipmunks_(jeu_vid%C3%A9o)'),
  ('Q1175156', 'Max Payne est un jeu vidéo d''action et de tir à la troisième personne développé par Remedy Entertainment et produit par 3D Realms. Il est à l''origine coédité en juillet 2001 sur Microsoft Windows par Gathering of Developers et Take-Two Interactive, et par la suite porté en décembre 2001 sur PlayStation 2 et Xbox par Rockstar Games, sur macOS en juillet 2002 par MacSoft Games et Feral Interactive, et adapté sur iOS et Android en 2012. Max Payne devient également jouable via la rétrocompatibilité sur Xbox 360 en 2009, sur PlayStation 3 en 2012, sur PlayStation 4 en 2016, et sur Xbox One et Xbox Series X/S en 2021. Enfin, une adaptation en vue isométrique réalisée par Möbius Entertainment paraît en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Max_Payne_(jeu_vid%C3%A9o)'),
  ('Q975773', 'Gran Turismo 3: A-Spec (ou simplement GT3) est un jeu vidéo de course automobile développé par Polyphony Digital et édité par Sony Computer Entertainment en 2001 sur PlayStation 2.

Troisième opus de la série Gran Turismo, le jeu se vend à près de 15 millions d''exemplaires écoulés à travers le monde et pousse le réalisme visuel à un degré inégalé à l''époque tout en approfondissant l''expérience de jeu proposé par Gran Turismo 2.', 'https://fr.wikipedia.org/wiki/Gran_Turismo_3:_A-Spec'),
  ('Q961506', 'R-Type Final est un jeu vidéo développé et édité par Irem sur PlayStation 2 en 2003. Il s''agit d''un shoot ''em up à défilement horizontal. Il fait partie de la série R-Type.

Dans ce volet, le joueur se bat contre la Bydo Core, un organisme étrange qui menace l''humanité...', 'https://fr.wikipedia.org/wiki/R-Type_Final'),
  ('Q960458', 'Jak 3 est un jeu vidéo de plates-formes développé par Naughty Dog et édité par Sony Computer Entertainment en 2004 sur PlayStation 2. Il s''agit de la suite de Jak II: Hors-la-loi.

En 2012, le jeu a été remastérisé en haute définition et porté dans une compilation disponible sur PlayStation 3 puis en 2013 sur PlayStation Vita, The Jak and Daxter Trilogy.', 'https://fr.wikipedia.org/wiki/Jak_3'),
  ('Q967563', 'Angelique Etoile est un jeu vidéo japonais de simulation de drague de la franchise Angelique, sorti en 2003.', 'https://fr.wikipedia.org/wiki/Angelique_Etoile'),
  ('Q964925', 'Urban Reign est un jeu vidéo de genre beat them up multijoueur développé par Namco sorti en 2005 pour PlayStation 2.', 'https://fr.wikipedia.org/wiki/Urban_Reign'),
  ('Q962645', 'Second Sight est un jeu vidéo de tir à la troisième personne développé par Free Radical Design et édité par Codemasters, sorti en 2004 sur GameCube, PlayStation 2, Xbox et en 2005 sur Windows.

Basé sur un concept de David Doak, œuvre de science-fiction, le jeu déploie une technique narrative de flashbacks dans un thriller paranormal, associant suspense psychologique et pouvoirs surnaturels.

En 2015, la société THQ Nordic fait l''acquisition, avec la série des Timesplitters, de la licence de Second Sight.

En 2018, c''est au tour de Koch Media d''acquérir la licence de Second Sight.', 'https://fr.wikipedia.org/wiki/Second_Sight_(jeu_vid%C3%A9o)'),
  ('Q1058179', 'Puyo Pop Fever ou Puyo Puyo Fever au Japon est un jeu vidéo de puzzle développé par Sonic Team et édité par Sega pour le système d''arcade

NAOMI GD-ROM, le jeu fait partie de la série de jeux vidéo Puyo Puyo, c''est aussi le seul jeu de la série après Puyo Pop à sortir également en Amérique du Nord et en Europe, si on ne compte pas Kirby''s Ghost Trap et Dr. Robotnik''s Mean Bean Machine et avant Puyo Puyo Tetris. En dehors du Japon, le jeu a été édité par Sega sur les versions Nintendo GameCube, PlayStation 2 et Xbox, Atlus sur la version Nintendo DS et THQ sur la version Game Boy Advance. les versions Xbox et PSP n''ont jamais été commercialisées en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Puyo_Pop_Fever'),
  ('Q1058692', 'Zone of the Enders: The 2d Runner, également connu sous le nom de Anubis: Zone of the Enders, est un jeu vidéo d''action développé et édité par Konami en 2003 sur PlayStation 2. Le jeu a été réalisé par Shuyo Murata et produit par Hideo Kojima. Il fait partie de l''univers fictionnel Zone of the Enders.

Un portage PlayStation 4 et Windows est annoncé au Tokyo Game Show 2017 sous le titre Zone of the Enders: The 2nd Runner M∀RS.', 'https://fr.wikipedia.org/wiki/Zone_of_the_Enders:_The_2nd_Runner'),
  ('Q1131234', 'Soul Link est une série animée japonaise racontant les aventures d´un groupe de cadets militaires de 2045 à bord d´un hôtel spatial appelé Aries.

Cette série a débuté sous la forme d´un jeu vidéo pour adultes disponible sous Microsoft Windows et PlayStation 2 sorti au Japon le 17 décembre 2004. Par la suite, le thème est repris dans une série animée de 12 épisodes ainsi que dans deux romans.

Le 29 juin 2006, un nouveau jeu appelé Soul Link EXTENSION sort au Japon pour PlayStation 2.', 'https://fr.wikipedia.org/wiki/Soul_Link'),
  ('Q1129775', 'Killzone est un jeu vidéo de tir à la première personne développé par Guerrilla Games et édité par Sony Computer Entertainment en novembre 2004 sur PlayStation 2.

Le jeu a connu une suite, Killzone: Liberation, sur PlayStation Portable et une autre, Killzone 2, est sortie début 2009 sur PlayStation 3 ainsi que Killzone 3 sur la même console en 2011. Enfin, Killzone: Shadow Fall est sorti sur PlayStation 4 et Killzone Mercenary sur PlayStation Vita.', 'https://fr.wikipedia.org/wiki/Killzone_(jeu_vid%C3%A9o)'),
  ('Q1131694', 'Naruto: Uzumaki Chronicles est un jeu vidéo de type beat them all développé par Racjin et édité par Namco Bandai Games, sorti en 2005 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Naruto:_Uzumaki_Chronicles'),
  ('Q1125364', 'Conflict: Desert Storm II, sous-titré Conflict: Desert Storm II: Back to Baghdad en Amérique du Nord, est un jeu vidéo d''action à la troisième personne, développé par Pivotal Games et édité par SCi, sorti en 2003. Il s''agit du second épisode de la série Conflict.', 'https://fr.wikipedia.org/wiki/Conflict:_Desert_Storm_II'),
  ('Q621616', 'Tomb Raider: L''Ange des ténèbres (Tomb Raider: The Angel of Darkness) est un jeu vidéo d''action-aventure développé par Core Design et édité par Eidos Interactive en 2003 sur PlayStation 2 et Windows.

Sixième épisode de la série Tomb Raider, le jeu met en scène le personnage de Lara Croft, qui est dans l''appartement de son ami, Werner Von Croy, quand celui-ci meurt terrassé mystérieusement. Tout l''accable et elle n''a d''autre solution que de fuir devant l''arrivée de la police. L''aventure débute dans un Paris terrorisé par le Monstrum, où elle rencontre des personnages effrayés et peu enclins à aider. Elle va devoir enquêter seule pour savoir pourquoi et comment son ami est mort. Elle découvre que les ficelles sont tirées par une secte peu orthodoxe, la Coterie, dont le but est d''acquérir l''immortalité et de dominer le monde par le réveil du Dormeur, dernier représentant des Nephilim dont il est dit qu''ils sont issus de l''union entre un ange et une humaine.', 'https://fr.wikipedia.org/wiki/Tomb_Raider_:_L%27Ange_des_t%C3%A9n%C3%A8bres'),
  ('Q612273', 'FIFA Street est un jeu vidéo sorti en 2005 basé sur le football de rue et le foot freestyle, donc avec des gestes du football technique.

Adapté sur PC et consoles, le premier volet de ce jeu est sorti en 2005 avec en star principale le joueur de football brésilien Ronaldinho.

Les commentaires sont signés Kool Shen.', 'https://fr.wikipedia.org/wiki/FIFA_Street_(jeu_vid%C3%A9o,_2005)'),
  ('Q612844', 'Tales of Destiny 2 est un jeu vidéo de rôle développé et édité par Namco sur PlayStation 2 en 2002 uniquement au Japon. Il est porté en 2007 sur PlayStation Portable au Japon. Il fait partie de la série Tales of.

C''est la suite directe du jeu vidéo Tales of Destiny. L''action prend place dans le même monde fictif.', 'https://fr.wikipedia.org/wiki/Tales_of_Destiny_2'),
  ('Q613088', 'Pro Evolution Soccer 2010 (abrégé PES 2010) est un jeu vidéo de football, édité et développé par Konami et son célèbre producteur Shingo Takatsuka. Il est sorti le 22 octobre 2009 sur PlayStation 3, Xbox 360, PC-DVD et téléphone mobile. Le 5 novembre 2009 il est sorti sur PlayStation 2 et PlayStation Portable puis le 19 novembre 2009 pour la version Nintendo Wii.

C''est le 9e jeu de la série des Pro Evolution Soccer et il est le principal concurrent de FIFA 10 d''Electronic Arts.

Les stars Lionel Messi (déjà présent sur l''édition 2009), Fernando Torres, Yoann Gourcuff et Alessandro Del Piero seront les ambassadeurs du jeu dans leurs pays respectifs. Il est à noter que les versions PS2, Wii et PSP sont sorties quelques jours après les versions PS3, PC et Xbox 360.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_2010'),
  ('Q822849', 'Canis Canem Edit, ou Bully en Amérique du Nord, est un jeu vidéo d''action-aventure en monde ouvert développé par Rockstar Vancouver et édité par Rockstar Games sorti en 2006 sur PlayStation 2. Un portage du jeu, titré Bully: Scholarship Edition et développé par Rockstar New England ou Rockstar Toronto selon les versions, est sorti en 2008 sur Xbox 360, Wii et PC.

Le personnage, contrôlé par le joueur, est un jeune adolescent envoyé dans une école privée. Le but est de gagner le respect des différentes bandes de l''école et de la ville via diverses missions.

Au départ, le jeu devait s''appeler Bully (littéralement « la brute » en anglais) en référence à la mascotte de l''établissement, mais pour la sortie anglaise, les distributeurs de Take Two Interactive, société mère de Rockstar Games, s''y sont opposés car le titre sous-entendait que le jeu est violent, « bully » signifiant également « bizutage ». Pour ces raisons et pour d''autres, ce titre a été remplacé par l''actuel « Canis canem edit », locution latine qui signifie littéralement « les chiens mangent les chiens », mais dont le sens se rapproche plus de l''expression "chacun pour soi". La version Xbox 360 et Wii furent nommées finalement Bully: Scholarship Edition. Bully a été réédité pour PlayStation 4 disponible via PlayStation Network le 22 mars 2016. Une version mise à jour de la Scholarship Edition, intitulée Anniversary Edition, a été développée par War Drum Studios et publiée pour Android et iOS le 8 décembre 2016.', 'https://fr.wikipedia.org/wiki/Canis_Canem_Edit'),
  ('Q820855', 'Secret Weapons Over Normandy est un jeu vidéo de simulation de vol de combat développé par Totally Games et édité par LucasArts, sorti en 2003 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Secret_Weapons_Over_Normandy'),
  ('Q817369', 'God of War (littéralement « Dieu de la Guerre ») est un jeu vidéo d''action-aventure et hack n'' slash développé par Santa Monica Studio et publié par Sony Computer Entertainment (SCE). D''abord sorti le 22 mars 2005 sur PlayStation 2 aux États-Unis, le jeu arrive en Europe le 22 juin. God of War est le premier jeu d''une longue série, le troisième par ordre chronologique. Largement inspiré de la mythologie grecque, le récit se passe en Grèce antique avec la vengeance comme thème central. Le joueur est aux commandes de Kratos, un guerrier spartiate qui sert les dieux Olympiens. La déesse Athéna donne à Kratos la mission de tuer Arès, le dieu de la Guerre et ancien mentor du protagoniste qui l''a précédemment trompé et manipulé afin que celui-ci tue sa femme et sa fille. Alors qu''Arès attaque la ville d''Athènes à cause de sa haine pour Athéna, Kratos part en quête d''un objet capable de stopper le Dieu une fois pour toutes: la boîte de Pandore.', 'https://fr.wikipedia.org/wiki/God_of_War_(jeu_vid%C3%A9o,_2005)'),
  ('Q627877', 'Unreal Tournament (abrégé UT99) est un jeu vidéo de tir à la première personne développé par Epic Games et Digital Extremes et publié par GT Interactive sur PC le 26 novembre 1999 aux États-Unis et à partir de décembre 1999 en Europe. Le jeu a également été publié sur Linux en 1999, puis sur Macintosh par MacSoft Games le 17 janvier 2000. Le jeu a enfin été publié par Infogrames sur PlayStation 2 le 26 octobre 2000 et sur Dreamcast le 14 mars 2001. Unreal Tournament se déroule dans un univers de science-fiction dans lequel le joueur incarne un combattant participant à un tournoi de combats à mort. Son mode solo rompt avec les jeux de tir subjectif classique en se focalisant sur des affrontements contre des bots dans différents modes de jeu comme les matchs à mort, la capture du drapeau, la domination ou l''assaut.', 'https://fr.wikipedia.org/wiki/Unreal_Tournament'),
  ('Q630596', 'Guitar Hero: Aerosmith est un jeu vidéo de rythme issu de la série Guitar Hero consacré au groupe Aerosmith. Sa sortie a lieu le 27 juin 2008. Il contient des morceaux du groupe et également de ses influences et des groupes ayant assuré leur première partie. Les personnages du jeu sont les membres du groupe, mais également des personnages imaginaires tirés de l''univers du jeu. Le jeu est accessible sur les plateformes PlayStation 2, PlayStation 3, Xbox 360, Wii, PC et Mac.', 'https://fr.wikipedia.org/wiki/Guitar_Hero:_Aerosmith'),
  ('Q626802', 'Kingdom Hearts II est un jeu vidéo de type action-RPG développé par Square Enix et distribué par Buena Vista Games et Square Enix, en 2005 pour la PlayStation 2, console de jeux vidéo de Sony. Le jeu est la suite de la collaboration entre Disney Interactive et Square Enix de 2002, Kingdom Hearts, qui combine des éléments de l''univers de Disney et de celui de Square dans un jeu d''action-RPG. Cet opus est un peu plus sombre que son prédécesseur. La popularité de ce jeu s''est ressentie dans la publication de romans et d''une série de mangas basés sur son histoire. En mars 2007 une version internationale, Kingdom Hearts II: Final Mix+, est publiée.', 'https://fr.wikipedia.org/wiki/Kingdom_Hearts_2'),
  ('Q1153260', 'Bionicle Heroes est un jeu vidéo de type TPS ou FPS développé par Traveller''s Tales et édité par Eidos Interactive, basé sur la gamme Bionicle de jeu de construction Lego. Le jeu est sorti sur GameCube, Wii, PlayStation 2, Xbox 360, PC, Nintendo DS et Game Boy Advance en 2006.

L''histoire est basée sur l''axe de l''histoire Bionicle de l''année 2006: Les Toa Inika arrivent sur l''île de Voya Nui afin de lutter contre les mystérieux Piraka et de retrouver le légendaire Masque de Vie.

C’est le dernier jeu Lego à sortir sur GameCube, le premier sur Wii, et le deuxième sur Xbox 360.', 'https://fr.wikipedia.org/wiki/Bionicle_Heroes'),
  ('Q1154327', 'XIII est un jeu vidéo de tir à la première personne développé par Ubisoft et sorti en 2003 sur PC, PlayStation 2, GameCube, Xbox.

Le jeu est une adaptation de la bande dessinée éponyme de Jean Van Hamme et William Vance, dont l''intrigue puise librement dans les cinq premiers volumes de la série. Le jeu met en scène le personnage de XIII, un amnésique à la recherche de son identité après s''être réveillé sur une plage. Pris dans une conspiration par un mystérieux groupe, il est pourchassé par le FBI qui l''accuse d''avoir tué le président des États-Unis.

Il s''agit du premier jeu de tir à la première personne utilisant des graphismes en cel-shading. Le comédien David Duchovny prête sa voix au protagoniste.', 'https://fr.wikipedia.org/wiki/XIII_(jeu_vid%C3%A9o,_2003)'),
  ('Q1154104', 'DJ Hero est un jeu vidéo de rythme sur PlayStation 3, PlayStation 2, Wii et Xbox 360. Le jeu est basé sur le même principe que Guitar Hero avec, à la place d''une réplique de guitare, une réplique de platine vinyle sur laquelle il faut scratcher. Le jeu comporte 93 titres et est sorti en France le 29 octobre 2009. DJ Hero comporte des styles musicaux variés: de l''électro au rock en passant par le hip-hop et la dance.', 'https://fr.wikipedia.org/wiki/DJ_Hero'),
  ('Q930060', 'Playboy: The Mansion est un jeu vidéo de simulation économique développé par Cyberlore Studios et édité par Arush Entertainment et Groove Games, sorti en 2005 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Playboy:_The_Mansion'),
  ('Q925748', 'Ed, Edd n Eddy: The Mis-Edventures est un jeu vidéo de plates-formes développé par Artificial Mind and Movement et édité par Midway Games, sorti en 2005 sur Windows, GameCube, PlayStation 2, Xbox et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Ed,_Edd_n_Eddy:_The_Mis-Edventures'),
  ('Q927012', 'WWE SmackDown vs. Raw 2007 est un jeu vidéo de catch professionnel distribué par THQ et développé par Yuke''s Media Creation. Le jeu est basé sur la promotion de lutte professionnelle World Wrestling Entertainment (WWE). THQ, Yuke''s et la WWE confirment officiellement le jeu le 31 mars 2006. Il est commercialisé fin 2006 sur consoles PlayStation 2, Xbox 360 et PlayStation Portable. Cette opus 2007 est le premier jeu de la série WWE SmackDown à être commercialisé en dehors des consoles PlayStation.

Le jeu intronise une nouvelle variété de fonctionnalités incluant le système de contrôle analogique (notamment le changement des touches de contrôle) et les combats dans le public. Le jeu inclut également un nombre d''amélioration des modes et matchs de la version précédente.', 'https://fr.wikipedia.org/wiki/WWE_SmackDown_vs._Raw_2007'),
  ('Q925438', 'Rogue Trooper est un jeu vidéo de tir à la troisième personne développé par Rebellion Developments et édité par Eidos Interactive, sorti en 2006 sur Windows, Wii, PlayStation 2 et Xbox.

La version Wii est sous-titrée The Quartz Zone Massacre. Il ressort en version Redux en 2017 sur Nintendo Switch, PlayStation 4 et Xbox One.

Il basé sur le comics du même nom.', 'https://fr.wikipedia.org/wiki/Rogue_Trooper_(jeu_vid%C3%A9o,_2006)'),
  ('Q618121', 'Ape Escape 2 est un jeu vidéo de plate-forme sorti en 2002 sur PlayStation 2. Le jeu a été développé par SCE Japan Studio et édité par Sony Computer Entertainment.', 'https://fr.wikipedia.org/wiki/Ape_Escape_2'),
  ('Q617257', 'Shin Megami Tensei: Devil Summoner 2 - Raidou Kuzunoha vs. King Abaddon est un jeu vidéo de type action-RPG développé et édité par Atlus, sorti en 2008 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei:_Devil_Summoner_2_-_Raidou_Kuzunoha_vs._King_Abaddon'),
  ('Q1061953', 'Warhammer 40,000: Fire Warrior est un jeu vidéo de tir à la première personne développé par Kuju Entertainment et publié par THQ en octobre 2003 sur PlayStation 2 et Microsoft Windows. Le jeu se déroule dans l’univers de science-fiction de Warhammer 40,000 créé par Games Workshop. Le joueur y incarne un guerrier du feu Tau, Shas''la Kais, cherchant à défendre sa race contre les agressions de l’Imperium et des forces du Chaos. Le jeu propose également un mode multijoueur proposant plusieurs modes de jeu comme le match à mort et la capture du drapeau.', 'https://fr.wikipedia.org/wiki/Warhammer_40,000:_Fire_Warrior'),
  ('Q614121', 'Planetarian: chiisana hoshi no yume, littéralement Planetarian ~La rêverie de la petite planète~, est un visual novel post-apocalyptique japonais dont le protagoniste est un homme d''âge mûr qui, dans une ville morte, trouve un robot qui fonctionne mal. L''homme, appelé tout simplement « the junker », reste avec le robot pendant une période de temps et essaie de réparer le projecteur du planétarium où se déroule l''histoire.

Planetarian est d''abord diffusé sur internet en 2004 par Key, un studio japonais de logiciel dont les œuvres précédentes comprennent Kanon et Air. Planetarian n''a pas de contenu destiné aux adultes; c''est la deuxième des œuvres de Key à ce faire, la première étant Clannad. Il est sorti en CD-ROM le 28 avril 2006. Une version à édition limitée a été envoyée lors des précommandes et les premières commandes dès sa mise en vente; elle contenait un livre de 243 pages de nouvelles basées sur l''univers de fiction de Planetarian ainsi qu''un shitajiki en bonus. Furent produits un port de PlayStation 2, publié par Prototype et une version portable du jeu par NTT DoCoMo, tous les deux en 2006. La version pour téléphone portable est utilisée sur les téléphones FOMA. Un drama CD basé sur la nouvelle appelée « Snow Globe » est sortie fin 2006, et deux autres en juillet 2007. Un animé est en cours de diffusion en 2016.', 'https://fr.wikipedia.org/wiki/Planetarian_%EF%BD%9Echiisana_hoshi_no_yume%EF%BD%9E'),
  ('Q220365', 'Need for Speed: Most Wanted est un jeu vidéo de course développé par EA Black Box et édité par Electronic Arts, sorti en Europe à partir du 11 novembre 2005.

Comme dans les opus précédents, le jeu reprend les déplacements libres du joueur dans un monde ouvert pour rejoindre un départ de course de rue ou un point de modification et personnalisation du véhicule. La police y fait son retour et développe des moyens variés et proportionnels pour appréhender le joueur qui ne cesse de les défier durant la progression de la carrière.

Les versions sur consoles portables sont différentes. Celle sur PSP est titrée Need for Speed: Most Wanted 5-1-0.', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_Most_Wanted_(jeu_vid%C3%A9o,_2005)'),
  ('Q580202', 'Syberia est un jeu vidéo d''aventure en pointer-et-cliquer belgo-canadien réalisé par Benoît Sokal. Développé et édité par Microïds, il est sorti en 2002 sur PC, puis a été porté sur PlayStation 2 et Xbox en 2003, sur Nintendo DS en 2008 et sur Nintendo Switch en 2017.

L''héroïne du jeu, Kate Walker, est une avocate américaine chargée de conclure le rachat de l''usine d''automates familiale des Voralberg dans le petit village alpin de Valadilène. Mais la révélation de l''existence d''un héritier potentiel, Hans Voralberg, qui a disparu en Europe de l''Est, contraint Kate à se lancer dans un voyage qui l''emmène toujours plus loin vers l''est, sur les traces de Hans et de ses automates de génie, à travers des lieux de plus en plus étranges.', 'https://fr.wikipedia.org/wiki/Syberia'),
  ('Q613298', 'Cars: Quatre Roues est un jeu vidéo de course édité par THQ, sorti en juin 2006 sur GameCube, PlayStation 2, PlayStation Portable, Nintendo DS, Game Boy Advance, Windows et Xbox. Les versions Xbox 360 et Wii sortent elles vers la fin de cette même année. Les versions sur consoles de salon (à part la version Wii) ont toutes été développées par Rainbow Studios, la version PlayStation Portable par Locomotive Games, les versions Nintendo DS et Game Boy Advance par Helixe et la version Wii par Incinerator Studios. La version console a été portée sur PC par Beenox.

Le jeu est basé sur l''univers du film du même nom, sorti la même année. L''histoire se passe ici après les événements du film, Flash McQueen habitant désormais à Radiator Springs et commençant une nouvelle saison de la Piston Cup.', 'https://fr.wikipedia.org/wiki/Cars_:_Quatre_Roues_(jeu_vid%C3%A9o)'),
  ('Q580276', 'Hype: The Time Quest est un jeu d''aventure sur Microsoft Windows développé par Playmobil Interactive et édité par Ubisoft. L''histoire met en scène un univers Playmobil médiéval dans lequel le joueur voyage dans le temps pour retrouver son époque.', 'https://fr.wikipedia.org/wiki/Hype:_The_Time_Quest'),
  ('Q613124', 'Silent Hill 4: The Room est un jeu vidéo de genre survival horror édité par Konami et développé en interne par la Team Silent, sorti en 2004 sur PlayStation 2, Xbox et Windows. Il fait partie de la série Silent Hill.

Le joueur incarne Henry Townshend, un habitant de South Ashfield qui se retrouve mystérieusement enfermé de l''intérieur dans son appartement, et tente de s''en échapper. Au fil du jeu, Henry explore une série de mondes étranges et affronte Walter Sullivan, un tueur en série revenu d’entre les morts. Le jeu n''est pas directement lié scénaristiquement aux épisodes précédents de la série, mais il en reprend néanmoins quelques éléments narratifs.', 'https://fr.wikipedia.org/wiki/Silent_Hill_4:_The_Room'),
  ('Q994428', 'Akai Ito est un jeu d''adventure d''horreur japonais de Success Corporation, sorti exclusivement sur PlayStation 2 au Japon le 20 octobre 2004.', 'https://fr.wikipedia.org/wiki/Akai_Ito'),
  ('Q996322', 'Phantasy Star Universe (PSU AotI) est un action-RPG en ligne créé par la Sonic Team et édité par Sega sur les supports suivants: PC, PlayStation 2 et en téléchargement sur le Xbox Live.

Au Japon, le titre est sorti sur PC et PlayStation 2 le 27 septembre 2007. Sur Xbox 360 en téléchargement via le Xbox Live le 20 novembre de la même année, tout continent confondu.

La sortie européenne fut pour le 25 janvier 2008 sur PC et PlayStation 2.

Ce jeu fait suite au premier épisode Universe de la série.', 'https://fr.wikipedia.org/wiki/Phantasy_Star_Universe:_Ambition_of_the_Illuminus'),
  ('Q979080', 'Volt, star malgré lui est un jeu vidéo d''action-aventure développé par Avalanche Software et édité par Disney Interactive Studios sur Wii, PlayStation 2, PlayStation 3, Xbox 360 et Windows en novembre 2008. Parallèlement, Altron a développé une version exclusive sur Nintendo DS du fait de son format portable.

Il s''agit de l''adaptation en jeu vidéo du film d''animation du même nom produit par Walt Disney Pictures.', 'https://fr.wikipedia.org/wiki/Volt,_star_malgr%C3%A9_lui_(jeu_vid%C3%A9o)'),
  ('Q985099', 'Romancing SaGa est un jeu vidéo de rôle de la série SaGa développé et édité par Square sur Super Famicom le 28 janvier 1992 uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Romancing_SaGa'),
  ('Q583301', 'FIFA 10 est un jeu vidéo de football développé par EA Canada et HB Studios, et édité par EA Sports. Suite de FIFA 09, il s''agit du dix-septième épisode principal de la série FIFA Football.

Après un FIFA 09 fort acclamé par les critiques et les joueurs, pour son authenticité d''un point de vue footballistique, les développeurs d''EA Sports ont décidé de faire de ce jeu vidéo la simulation ultime pour cette nouvelle édition.', 'https://fr.wikipedia.org/wiki/FIFA_10'),
  ('Q580667', 'Tomb Raider: Anniversary est un jeu vidéo d''action-aventure développé par Crystal Dynamics et édité par Eidos Interactive, sorti en 2007 sur PlayStation 2, Windows, Wii, Xbox 360, PlayStation Portable et Macintosh.

Réalisé à l''occasion du 10e anniversaire de la série Tomb Raider, Tomb Raider: Anniversary constitue un remake du premier épisode, Tomb Raider, paru en 1996. Le jeu utilise le moteur graphique optimisé du précédent épisode, Tomb Raider: Legend, et présente une Lara Croft encore plus détaillée, fine et rapide; la célèbre héroïne y apparaît aussi bien évidemment plus jeune.

À sa sortie, Tomb Raider: Anniversary a reçu des critiques généralement positives de la part des critiques, qui l''ont jugé digne d''un remake du jeu original, bien que certaines critiques aient été dirigées vers les graphismes du jeu et les problèmes techniques occasionnels.', 'https://fr.wikipedia.org/wiki/Tomb_Raider:_Anniversary'),
  ('Q1247366', 'Da Vinci Code (The Da Vinci Code) est un jeu vidéo d''aventure développé par The Collective et édité par 2K Games, sorti en 2006 sur Windows, PlayStation 2 et Xbox.

Le jeu est adapté du roman du même nom et est sorti en même temps que son adaptation au cinéma.

Le game designer Charles Cecil a travaillé comme consultant sur les énigmes du jeu.', 'https://fr.wikipedia.org/wiki/Da_Vinci_Code_(jeu_vid%C3%A9o)'),
  ('Q1255566', 'Drakengard est un action-RPG sorti sur PlayStation 2 en 2003 (au Japon), édité par Take-Two et par Square Enix, développé par Cavia.', 'https://fr.wikipedia.org/wiki/Drakengard_(jeu_vid%C3%A9o)'),
  ('Q836690', 'The Simpsons: Hit and Run est un jeu vidéo de course et d''action-aventure basé sur la série d''animation américaine Les Simpson. Le jeu est développé par Radical Entertainment, distribué par Fox Interactive et édité par Vivendi Games en Amérique du Nord et par Sierra Entertainment dans le reste du monde. Il sort en 2003 sur GameCube, PlayStation 2, Xbox et Microsoft Windows. L''histoire et les dialogues du jeu sont développés par des scénaristes des Simpson, et les voix des personnages sont celles de la distribution habituelle de la série.

Le jeu suit la famille Simpson et leur ami Apu Nahasapeemapetilon, qui sont témoins de plusieurs événements étranges survenus dans la ville de Springfield: l''installation de caméras de sécurité, l''apparition de camionnettes mystérieuses et de cercles de culture, et la distribution d''une nouvelle boisson de la marque de soda Buzz Cola qui rend fou. Prenant les choses en main, ils découvrent plusieurs secrets dérangeants et réalisent rapidement que ces événements font partie d''une conspiration extraterrestre de plus grande envergure, dont sont à l''origine Kang et Kodos.', 'https://fr.wikipedia.org/wiki/The_Simpsons:_Hit_and_Run'),
  ('Q967889', 'Alone in the Dark est un jeu vidéo développé par Eden Studios et édité par Atari Inc., sorti en 2008 sur PlayStation 2, PlayStation 3, Wii, Windows et Xbox 360. Il s''agit du cinquième épisode de la série Alone in the Dark, série de jeu d''action-aventure horrifique, créditée pour avoir initié le genre survival horror. Les versions PlayStation 2 et Wii sont développées par le studio Hydravision. La version PlayStation 3 sortie quelques mois après les autres versions, et sous-titrée Inferno, apporte notamment la correction de plusieurs bugs liés au gameplay, ainsi qu''une scène de jeu inédite.', 'https://fr.wikipedia.org/wiki/Alone_in_the_Dark_(jeu_vid%C3%A9o,_2008)'),
  ('Q969774', 'Hulk est un jeu vidéo de type beat them all développé par Radical Entertainment et édité par Vivendi Games en 2003 sur toutes les consoles de jeux vidéo 128 bits (excepté la Dreamcast) et également sur Windows.

Parallèlement, une version exclusive sur Game Boy Advance, du fait de son format portable, a été développée par Pocket Studios sous le titre The Incredible Hulk.

Il s''agit d''un dérivé du film du même nom sorti en salle en 2003.', 'https://fr.wikipedia.org/wiki/Hulk_(jeu_vid%C3%A9o)'),
  ('Q969184', 'Made Man est un jeu vidéo de tir à la troisième personne développé par SilverBack Studios et édité par Mastertronic, sorti en 2006 sur Windows et PlayStation 2.

Son scénario a été écrit par David Fisher en collaboration avec l''ancien mafieux Salvatore Bonanno.', 'https://fr.wikipedia.org/wiki/Made_Man'),
  ('Q973343', 'Batman: Vengeance est un jeu vidéo mettant en scène le super-héros Batman. Il s''agit d''un jeu d''action sorti en 2001 sur GameCube, PlayStation 2, Xbox et Windows. Il a été développé et édité par Ubisoft en collaboration avec Warner Bros. Interactive Entertainment et DC comics. Il a connu un portage sur Game Boy Advance sous la forme d''un jeu de plates-formes.

Le jeu est basé sur la série animée "The New Batman Advendtures" (TNBA) de Bruce Timm et Paul Dini.', 'https://fr.wikipedia.org/wiki/Batman_:_Vengeance'),
  ('Q970327', 'Les Chroniques de Spiderwick (The Spiderwick Chronicles) est un jeu vidéo d''action-aventure sorti en 2008 pour Nintendo DS, PC, Wii, Xbox 360 et PlayStation 2. Il est édité par Sierra Entertainment et basé sur le film américain Les Chroniques de Spiderwick, réalisé par Mark Waters pour Paramount Pictures et lui-même adapté du livre pour enfants écrit par Holly Black et illustré par Tony DiTerlizzi.', 'https://fr.wikipedia.org/wiki/Les_Chroniques_de_Spiderwick_(jeu_vid%C3%A9o)'),
  ('Q1071749', 'The King of Fighters 2003 est un jeu vidéo de combat développé et édité par SNK Playmore en 2003 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES en 2004 (NGM 271). C''est le dixième épisode de la série The King of Fighters. Le jeu est converti sur PlayStation 2 en 2004 et sur Xbox en 2005.

Eolith, l''entreprise sud coréenne qui s''était occupée de développer The King of Fighters 2001 et 2002, s''associe en 2003 après la faillite de SNK, avec la société M-Dream China pour produire des jeux mobiles. La série est ainsi de nouveau produite au Japon avec The King of Fighters 2003, le jeu marque également le dernier épisode de la série à paraître sur les systèmes Neo-Geo MVS et Neo-Geo AES, la cartouche pèse 716 Mb.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_2003'),
  ('Q1070821', '007: Quantum of Solace est un jeu de tir à la première personne (jeu de tir à la troisième personne pour Nintendo DS et PlayStation 2) basé sur les films Casino Royale et Quantum of Solace. Le jeu est sorti pour Microsoft Windows, Nintendo DS, PlayStation 2, PlayStation 3, Wii et Xbox 360. Le jeu est sorti le 31 octobre 2008 en Europe [2], le 4 novembre 2008 en Amérique du Nord [2] et le 19 novembre 2008 en Australie. [2] La sortie du jeu a coïncidé avec la sortie de Quantum of Solace. [3] Le jeu est le premier titre de James Bond publié par Activision; la société a acquis la licence de jeu vidéo de la franchise James Bond en 2006. [4] Le jeu est sorti sur Microsoft Windows, PlayStation 3, Wii et Xbox 360 développé par Treyarch, Beenox a porté les versions Microsoft Windows et Wii aux côtés de Treyarch, tandis que Vicarious Visions et Eurocom ont développé leurs propres versions pour Nintendo DS et PlayStation 2. Il est propulsé par le moteur IW 3.0. Il est le premier à présenter la voix et la ressemblance de Daniel Craig, ainsi que celles d''Eva Green, Judi Dench, Mads Mikkelsen, Olga Kurylenko et Mathieu Amalric. C''est également le seul titre James Bond publié par Activision à être développé principalement par un studio américain, car les derniers jeux Bond publiés par Activision seraient développés par les studios britanniques Eurocom (à Derby) et Bizarre Creations (à Liverpool).', 'https://fr.wikipedia.org/wiki/007:_Quantum_of_Solace_(jeu_vid%C3%A9o)'),
  ('Q663540', 'Summoner est un jeu vidéo développé par Volition, Inc. et édité par THQ en 2001 sur PlayStation 2 et Windows. Le jeu s''apparente à un jeu de rôle. Il est sorti le 22 juin 2001. Il a pour suite Summoner 2.', 'https://fr.wikipedia.org/wiki/Summoner'),
  ('Q657658', 'Les Griffin, le jeu vidéo (Family Guy Video Game!) est un jeu vidéo d''action-aventure développé par High Voltage Software et édité par 2K Games, sorti en 2006 sur PlayStation 2, Xbox et PlayStation Portable.

Basé sur la série du même nom. Il a pour suite Family Guy: Back to the Multiverse.', 'https://fr.wikipedia.org/wiki/Les_Griffin,_le_jeu_vid%C3%A9o'),
  ('Q1072003', 'The King of Fighters 2000 est un jeu vidéo de combat développé et édité par SNK en 2000 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES (NGM 257). C''est le septième volet de la série The King of Fighters et le dernier produit par SNK avant que celle-ci ne soit en faillite.

Le jeu a été adapté sur Dreamcast (exclusif au Japon) et sur PlayStation 2 en 2002. La version standalone sur PlayStation 2 pour le continent nord américain a été publié sous forme de pack comprenant le huitième volet, à savoir The King of Fighters 2001. Une compilation de la saga du NESTS intitulée The King of Fighters NESTS Hen et regroupant The King of Fighters''99, 2000 et 2001 est sortie uniquement au Japon sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_2000'),
  ('Q840699', 'Silent Hill: Ørigins, appelé Silent Hill Zero au Japon, est un jeu vidéo de type survival horror développé par Climax Studios et édité par Konami en 2007 sur PlayStation Portable. Le jeu a été adapté sur PlayStation 2 en 2008.

Silent Hill: Origins constitue la préquelle de la série Silent Hill. Le joueur incarne Travis Grady, un conducteur de poids lourd qui se retrouve pris au piège de la ville de Silent Hill après avoir sauvé une jeune fille, Alessa, de l''incendie de sa maison.', 'https://fr.wikipedia.org/wiki/Silent_Hill:_Origins'),
  ('Q840167', 'Star Wars: Le Pouvoir de la Force (Star Wars: The Force Unleashed) est un jeu d''action développé par LucasArts en collaboration avec ILM, sorti en septembre 2008. Le jeu est disponible sur les consoles de salon PlayStation 2, PlayStation 3, Wii, Xbox 360 et les consoles portables Nintendo DS et PSP. Il existe une version Windows et Mac OS X du jeu.

Le jeu s''inscrit dans le projet multimédia Le Pouvoir de la Force inachevé, comportant également une suite, et décliné en roman et bande dessinée et figurines. Ce type de déclinaison « tout sauf le film » était déjà apparu pour Les Ombres de l''Empire. Le jeu se situe entre l''épisode III et l''épisode IV, et raconte la naissance de l''alliance rebelle et l''histoire de l''apprenti secret de Dark Vador. Cependant, le 14 décembre 2013, Pablo Hidalgo annonce officiellement que Le Pouvoir de la Force n''est plus canon dans la continuité de l''univers étendu.', 'https://fr.wikipedia.org/wiki/Star_Wars_:_Le_Pouvoir_de_la_Force'),
  ('Q840505', 'Shin Megami Tensei: Devil Summoner - Raidou Kuzunoha vs. The Soulless Army est un jeu vidéo de type action-RPG développé et édité par Atlus, sorti en 2006 sur PlayStation 2.

Une version remasterisé intitulée Raidou Remastered: The Mystery of the Soulless Army est sorti le 19 juin 2025 sur Windows, Nintendo Switch, Playstation 5 et Xbox Series.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei:_Devil_Summoner_-_Raidou_Kuzunoha_vs._The_Soulless_Army'),
  ('Q1197046', 'Monster Hunter est un jeu vidéo développé par Capcom Production Studio 1 et édité par Capcom sur PlayStation 2 en 2004. Cet action-RPG est le premier épisode de la série Monster Hunter.', 'https://fr.wikipedia.org/wiki/Monster_Hunter_(jeu_vid%C3%A9o)'),
  ('Q1195153', 'Rock Band est un jeu vidéo musical développé par Harmonix, sorti le 20 novembre 2007 aux États-Unis sur les consoles PlayStation 2, PlayStation 3, Wii et Xbox 360. Il est commercialisé en France sur Xbox 360 depuis le 22 mai 2008, sur Wii depuis le 11 septembre 2008 et sur PlayStation 3 depuis le 18 septembre 2008.

Rock Band permet aux joueurs de créer leurs propres groupes de rock virtuels en donnant la possibilité de jouer à 4 joueurs en simultané grâce à l''utilisation de périphériques inspirés de réels instruments de musique, vendus avec le jeu ou indépendamment. L''édition spéciale comprend le jeu en lui-même ainsi qu''une batterie, une guitare et un micro.', 'https://fr.wikipedia.org/wiki/Rock_Band_(jeu_vid%C3%A9o)'),
  ('Q1199043', 'Metal Slug 5 est un jeu vidéo de type run and gun développé et édité par SNK Playmore en 2003 sur Neo-Geo MVS, en 2004 sur Neo-Geo AES (NGM 268). C''est le sixième épisode de la série Metal Slug''. Metal Slug 5 est sorti au format cartouche mais également en version PCB.', 'https://fr.wikipedia.org/wiki/Metal_Slug_5'),
  ('Q1192752', 'Tales of Legendia est un jeu vidéo de rôle développé et édité par Namco sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Tales_of_Legendia'),
  ('Q239889', 'Hitman: Blood Money est un jeu vidéo d''infiltration, développé par IO Interactive et édité par Eidos Interactive, sorti en mai 2006 sur Windows, PlayStation 2, Xbox et Xbox 360. Warner Bros. Interactive Entertainment a publié des versions améliorées d''Absolution et Blood Money, sorti sur PlayStation 4 et Xbox One en janvier 2019. Un portage intitulé Hitman: Blood Money — Reprisal est sorti pour iOS et Android le 30 novembre 2023, ainsi que la Nintendo Switch le 25 janvier 2024.', 'https://fr.wikipedia.org/wiki/Hitman:_Blood_Money'),
  ('Q1199051', 'Metal Slug 6 est un jeu vidéo de run and gun créé par SNK Playmore, sorti sur le système arcade Atomiswave. Il sera également porté comme épisode dans les compilations Metal Slug Anthology (sorti sur les consoles PlayStation 2, PlayStation Portable et Wii) et Metal Slug Collection (sorti sur PC).', 'https://fr.wikipedia.org/wiki/Metal_Slug_6'),
  ('Q1200987', 'Destroy All Humans! est un jeu vidéo de tir à la troisième personne sorti en 2005 sur Xbox et PlayStation 2. Il a été développé par Pandemic Studios et édité par THQ. Il met en scène un « furon » (une race extraterrestre) belliqueux du nom de Cryptosporidium-137 (Crypto) ayant pour mission d''asservir l''espèce humaine ainsi que de récupérer l''ADN de leur troncs cérébraux. Il est aidé dans sa tâche par Orthopox-13 (Pox) son supérieur hiérarchique qui lui donne ses objectifs de mission. Le jeu se déroule en 1959 aux États-Unis. Il fait honneur et parodie les séries B de science fiction de cette période. Il n''hésite également pas à tourner en dérision la paranoïa croissante de la menace rouge, l''URSS, ou aussi nommée Maccarthysme, dont le gouvernement se sert afin de dissimuler la présence et les actes de l''alien.', 'https://fr.wikipedia.org/wiki/Destroy_All_Humans!'),
  ('Q1199047', 'Metal Slug 4 est un jeu vidéo de type run and gun développé par Mega Enterprise et édité par Playmore en 2002 sur Neo-Geo MVS, Neo-Geo AES (NGM 263). C''est le cinquième épisode de la série Metal Slug.', 'https://fr.wikipedia.org/wiki/Metal_Slug_4'),
  ('Q1134973', 'Neo Angelique est un jeu vidéo japonais de simulation de drague sorti en 2006, relance de la franchise Angelique. Il est suivi en 2008 de versions améliorées nommées Neo Angelique Full Voice puis Neo Angelique Special.', 'https://fr.wikipedia.org/wiki/Neo_Angelique_(jeu_vid%C3%A9o)'),
  ('Q180181', 'GoldenEye: Au service du mal, connu sous le nom de GoldenEye: Rogue Agent dans son titre original et de GoldenEye: Dark Agent au Japon est un jeu vidéo de tir à la première personne développé par EA Los Angeles et édité par Electronic Arts, sorti en 2004 sur PlayStation 2, GameCube, Xbox et en 2005 sur Nintendo DS.

Le joueur incarne un ex-agent du MI6, qui a été recruté par Auric Goldfinger et désormais au service d''une organisation criminelle afin d''assassiner Dr. No. Plusieurs personnages de l''univers de James Bond font leur apparition, dont Oddjob, Francisco Scaramanga, Xenia Onatopp et Pussy Galore.', 'https://fr.wikipedia.org/wiki/GoldenEye_:_Au_service_du_mal'),
  ('Q182771', 'Les Sims 2 est un jeu vidéo de simulation de vie développé par Maxis, édité par Electronic Arts le 14 novembre 2004 sur PC (Windows) et adapté sur Mac OS X le 17 juin 2005. Il est adapté sur Game Boy Advance, GameCube, Nintendo DS, Playstation 2, Xbox et PSP. Il est le second épisode de la série après Les Sims.', 'https://fr.wikipedia.org/wiki/Les_Sims_2'),
  ('Q183590', 'TOCA Race Driver 2 est un jeu vidéo de course sorti en 2004 sur PC, Xbox, PlayStation 2.', 'https://fr.wikipedia.org/wiki/TOCA_Race_Driver_2'),
  ('Q1302197', 'Princess Lover! est un visual novel japonais et le premier titre développé par Ricotta. Il a d''abord été publié comme un eroge pour Microsoft Windows le 27 juin 2008, dans les éditions limitées et régulières, qui a été suivie par une version pour tous les âges pour la PlayStation 2 le 28 janvier 2010. Le gameplay de Princess Lover! suit une ligne d''intrigue linéaire qui offre des scénarios prédéterminés et des choix d''interaction, et son histoire se concentre sur l''appel des quatre personnages principaux féminins.

Princess Lover! a reçu plusieurs transitions vers d''autres médias. Le jeu a d''abord été adapté en une série de cinq light novels écrits par Utsusemi et illustrés par Hyūma Yoshi avec des pages de couvertures réalisées par Kei Komori. Il a ensuite été suivi de trois adaptations de mangas. Une adaptation anime produite par le studio d''animation GoHands a été diffusée au Japon du 5 juillet au 20 septembre 2009 sur différentes chaînes et réseaux de télévisions. Une émission de webradio a également été produite pour promouvoir l''adaptation anime du 3 juillet au 2 octobre 2009.', 'https://fr.wikipedia.org/wiki/Princess_Lover!'),
  ('Q1300159', 'Mercenaries 2: L''Enfer des favelas (titre original: Mercenaries 2: World in Flames) est un jeu vidéo d''action-aventure, développé par Pandemic Studios et édité par Electronic Arts, sorti en Amérique du Nord le 31 août 2008 et en Europe le 5 septembre 2008 sur PlayStation 2, PlayStation 3, Xbox 360 et Windows. C''est la suite de Mercenaries: Playground of Destruction.', 'https://fr.wikipedia.org/wiki/Mercenaries_2_:_L%27Enfer_des_favelas'),
  ('Q1313644', 'Tourist Trophy: The Real Riding Simulator est un jeu vidéo de course de moto développé par Polyphony Digital et édité par Sony Computer Entertainment en 2006 sur PlayStation 2. Développé par les créateurs de la série Gran Turismo, le jeu partage son moteur avec Gran Turismo 4, les circuits et l''esthétique de la célèbre simulation automobile.

Le jeu se découpe entre son mode Arcade et son mode Tourist Trophy. Ce dernier comprend sept sous-parties: École de pilotage, Mode Défi, Épreuves, Garage, Équipement, Mode Photo et Contre-la-montre.

Ce jeu a été réédité sous le label Platinum, grâce un nombre de ventes dépassant les 400 000 exemplaires.', 'https://fr.wikipedia.org/wiki/Tourist_Trophy:_The_Real_Riding_Simulator'),
  ('Q1073511', 'Tekken 4 est un jeu vidéo de combat développé et distribué par Namco sur borne d''arcade en 2001, plus précisément sur System 246, puis adapté sur console PlayStation 2. Il s''agit du deuxième jeu de la série Tekken à sortir sur PlayStation 2 après Tekken Tag Tournament. La suite du jeu, intitulée Tekken 5 est initialement sortie en 2004.', 'https://fr.wikipedia.org/wiki/Tekken_4'),
  ('Q1074021', 'Digimon World Data Squad est un jeu vidéo d''action-aventure et de rôle commercialisé au Japon le 30 novembre 2006 par Bandai Namco Games sur console PlayStation 2.', 'https://fr.wikipedia.org/wiki/Digimon_World_Data_Squad'),
  ('Q783839', 'Midnight Club 3: DUB édition est un jeu vidéo de course développé par Rockstar San Diego et Eutechnyx et édité en 2005 par Disney Interactive, Sega et Rockstar Games sur PlayStation 2, Xbox et PlayStation Portable.

Le jeu s''inscrit dans la mouvance tuning et propose 60 véhicules différents (moto, camion, voitures de sport, etc).', 'https://fr.wikipedia.org/wiki/Midnight_Club_3:_DUB_Edition'),
  ('Q784143', 'Call of Duty 2: Big Red One est un jeu de tir à la première personne se déroulant pendant la Seconde Guerre mondiale sur les fronts nord-africain (Opération Torch), sicilien (Opération Husky) et français (Opération Overlord, ligne Siegfried…) avec la 1re division d''infanterie américaine (Big Red One). Il est sorti en 2005 sur GameCube, PlayStation 2 et Xbox. Cette version est très différente de Call of Duty 2 sur PC et Xbox 360. Le joueur incarne une jeune recrue avec les soldats Bloomflied, Denley, Glenn Hawkins, Stephen Kelly et Delaney.

Le jeu comporte plusieurs acteurs présents dans la mini-série Frères d''armes, tels Michael Cudlitz, James Madio, Frank John Hughes, Richard Speight Jr., Ross McCall, Rick Gomez, et Rene Morono.', 'https://fr.wikipedia.org/wiki/Call_of_Duty_2:_Big_Red_One'),
  ('Q794367', 'Beyond Good and Evil, parfois abrégé BGE, est un jeu vidéo d''action-aventure développé et édité par Ubisoft en 2003 sur PlayStation 2, Xbox, GameCube et PC (Windows).

Le jeu mélange différents genres de jeu (aventure, infiltration, course) et fait évoluer le joueur dans un monde poétique et onirique victime d''une invasion extraterrestre. Le joueur y incarne Jade, jeune reporter photographe, aidée de l''homme-cochon Pey''j et de l''espion Double H dans son combat contre les sections Alpha et les extra-terrestres DomZ aux côtés du réseau IRIS.

Imaginé et conçu par le Franco-Monégasque Michel Ancel, créateur de Rayman, Beyond Good and Evil a été bien accueilli par la critique. Sa musique a également fait l''objet d''éloges. Le jeu a obtenu deux prix aux Imagina Games Awards et a reçu plusieurs nominations aux Game Developers Choice Awards et aux Interactive Achievement Awards. Il n''a cependant pas eu le succès escompté auprès du public. Malgré cela, il devrait connaître un second épisode en forme de préquelle qui portera le titre de Beyond Good and Evil 2.', 'https://fr.wikipedia.org/wiki/Beyond_Good_and_Evil'),
  ('Q1068962', 'Sonic Heroes est un jeu vidéo de plates-formes, développé par Sonic Team et sorti sur GameCube, PS2, Xbox et Windows le 30 décembre 2003.

L''histoire est dans la continuité des deux épisodes Sonic Adventure, mais la mécanique et la forme du jeu s''en éloignent, revenant à l''ambiance des premiers jeux Megadrive, à savoir des niveaux thématisés qui s''enchainent et plus de linéarité comme ce fut le cas sur les premiers épisodes en 2D.

Dans Sonic Heroes, le joueur a le choix entre quatre histoires où, dans chacune d''entre elles, intervient une « team » composée de trois membres avec lesquels le joueur joue simultanément et entre lesquels il peut alterner en cours de niveau en fonction des aptitudes dont il a besoin: la Team Sonic (Sonic, Tails et Knuckles), la Team Dark (Shadow, Rouge et E-123 Oméga), la Team Rose (Amy, Cream et Big) et la Team Chaotix (Vector, Espio et Charmy).', 'https://fr.wikipedia.org/wiki/Sonic_Heroes'),
  ('Q1067771', 'Shin Megami Tensei III: Nocturne est un jeu vidéo de rôle développé par Atlus sur PlayStation 2. Il a été édité en 2003 au Japon puis réédité en 2004 sous le titre Shin Megami Tensei III: Nocturne Maniax avec divers bonus. C''est cette version Maniax qui a été publiée en Europe en 2005 sous le nom de Shin Megami Tensei: Lucifer''s Call par le studio Ghostlight.

Il s''agit du cinquième opus de la branche "principale" des Shin Megami Tensei, qui appartient elle-même à la série des Megami Tensei.

Il est aussi le premier jeu de la licence Shin Megami Tensei publié sur ce continent, et un des rares à avoir été traduit en français.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei_III:_Nocturne'),
  ('Q1158842', 'NBA 2K8 est un jeu vidéo de basket-ball développé par Visual Concepts et édité par 2K Sports sorti en 2007.

Il est disponible en France depuis le 23 novembre 2007 sur PlayStation 3, Xbox 360, PlayStation 2 et PC.

C''est le neuvième épisode de la franchise 2K et le principal concurrent de NBA Live 08.

Avec la licence officielle de la NBA, les joueurs peuvent choisir parmi les 30 équipes de la ligue et évoluer avec les plus grands joueurs tels que Kobe Bryant ou LeBron James.

Il est considéré comme l''opus le plus abouti de la franchise.', 'https://fr.wikipedia.org/wiki/NBA_2K8');

insert into import_summary (wikidata_id, summary, source) values
  ('Q1155913', 'TOCA Race Driver (Pro Race Driver aux États-Unis) est un jeu de course automobile développé et édité par Codemasters, en 2002, pour PlayStation 2, Xbox et Windows. Il est le quatrième jeu de la série Toca.', 'https://fr.wikipedia.org/wiki/TOCA_Race_Driver'),
  ('Q1164863', 'Escape from Monkey Island est un jeu d''aventure graphique de type pointer-et-cliquer développé et publié par LucasArts en novembre 2000. Initialement commercialisé sur PC, le jeu est ensuite porté sur Macintosh en avril 2001 puis sur PlayStation 2 en juin 2001. C’est le quatrième volet de la série Monkey Island et fait suite à The Curse of Monkey Island publié en 1997. Le jeu se déroule dans une version imaginaire des Caraïbes pendant la grande époque de la piraterie. Le joueur incarne le personnage de Guybrush Threepwood et doit explorer des îles imaginaires du jeu et résoudre des puzzles pour avancer. Le jeu a été conçu par Sean Clark et Michael Stemmle. Contrairement aux premiers épisodes de la série, il est basé sur le moteur GrimE de Grim Fandango qui mélange des arrières plans pré-rendu et des personnages en trois dimensions. Il bénéficie également du système audio iMUSE permettant de synchroniser la musique avec les évènements du jeu. À sa sortie, il est très bien accueilli par la presse spécialisée malgré des critiques concernant son interface.', 'https://fr.wikipedia.org/wiki/Escape_from_Monkey_Island'),
  ('Q1158680', 'Madden NFL 06 est un jeu vidéo de sport (football américain) sorti en 2005 sur PlayStation 2, GameCube, Xbox, Xbox 360, Windows Mobile, PlayStation Portable, Game Boy Advance, Nintendo DS et PC (Windows).

Le jeu fait partie de la série Madden NFL.', 'https://fr.wikipedia.org/wiki/Madden_NFL_06'),
  ('Q1163024', 'Rugby 08 est un jeu vidéo de rugby à XV sorti en 2007 sur Windows et PlayStation 2. Le jeu a été développé par HB Studios puis édité par Electronic Arts via sa branche EA Sports.

C''est la suite de Rugby 05 et Rugby 06.', 'https://fr.wikipedia.org/wiki/Rugby_08'),
  ('Q845212', 'To Heart 2, stylisé ToHeart2, est un jeu vidéo de type visual novel et eroge développé par Leaf et édité par Aquaplus, sorti en 2004 sur Windows, PlayStation 2, PlayStation 3 et PlayStation Portable.

Il fait suite à To Heart et a été adapté en manga et en anime.', 'https://fr.wikipedia.org/wiki/To_Heart_2'),
  ('Q1052488', 'Tekken 5 est un jeu vidéo de combat développé et édité par Namco commercialisé en 2004 sur borne d''arcade, puis adapté l''année suivante sur console PlayStation 2. Il s''agit du sixième jeu de la série homonyme à être commercialisé, et celui marquant son dixième anniversaire depuis la sortie du premier opus. Une suite, intitulée Tekken 6, est initialement commercialisée en 2007 sur borne d''arcade puis adapté sur PlayStation 3 et Xbox 360 en 2009.', 'https://fr.wikipedia.org/wiki/Tekken_5'),
  ('Q1313975', 'Mortal Kombat: Shaolin Monks est un jeu vidéo d''action/aventure déconseillé aux moins de 16 ans, de la série Mortal Kombat. Il est sorti le 28 octobre 2005 en France sur PlayStation 2 et sur Xbox. Ce Mortal Kombat est un remake de Mortal Kombat II', 'https://fr.wikipedia.org/wiki/Mortal_Kombat:_Shaolin_Monks'),
  ('Q1053110', 'Tom Clancy''s Splinter Cell: Pandora Tomorrow est un jeu vidéo d''infiltration, développé par Ubisoft Shanghai et Ubisoft Annecy, sorti sur de multiples plates-formes en 2004.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Splinter_Cell:_Pandora_Tomorrow'),
  ('Q839794', 'Devil May Cry 3: L''Éveil de Dante est un jeu vidéo d''action, développé par Capcom Production Studio 1 et édité par Capcom en 2005 sur PlayStation 2. Il a été adapté sur Windows en 2006, puis via la collection HD regroupant les trois premiers opus sur PC, PlayStation 3, Xbox 360, PlayStation 4 et Xbox One. Il sort aussi plus tard sur Nintendo Switch.', 'https://fr.wikipedia.org/wiki/Devil_May_Cry_3_:_L%27%C3%89veil_de_Dante'),
  ('Q654534', 'Looney Tunes: Acme Arsenal est un jeu vidéo d''action-aventure à la troisième personne développé par Redtribe et publié par Warner Bros. Interactive, sorti en 2007 sur Wii, PlayStation 2 et Xbox 360. Il est basé sur la série de cartoons Looney Tunes.', 'https://fr.wikipedia.org/wiki/Looney_Tunes:_Acme_Arsenal'),
  ('Q652481', 'Twisted Metal: Head-On est un jeu de combat motorisé développé par Incognito Entertainment et publié par Sony Computer Entertainment sur PlayStation Portable le 24 mars 2005 et sur PlayStation 2 le 5 février 2008 (les dates de sorties sont celles en Amérique du Nord). Twisted Metal: Head-On est le septième jeu de la série Twisted Metal, et le premier à être complètement jouable en ligne.

Les fans de la série considèrent que les deux épisodes développés par 989 Studios (Twisted Metal III et Twisted Metal 4) ne font pas réellement partie de la série; Head-On est considéré comme la suite directe de Twisted Metal 2, et donc le « vrai Twisted Metal 3 ».', 'https://fr.wikipedia.org/wiki/Twisted_Metal:_Head-On'),
  ('Q655031', 'Superman Returns est un jeu vidéo d''action édité par Electronic Arts et développé par EA Tiburon sur différentes plates-formes, adapté du film du même nom de Bryan Singer sorti en 2006.

La version sur Game Boy Advance sous-titrée La Forteresse de Solitude est un jeu de puzzle.', 'https://fr.wikipedia.org/wiki/Superman_Returns_(jeu_vid%C3%A9o)'),
  ('Q652938', 'NBA Live 2005 est un jeu vidéo de basket-ball sorti en 2004 et fonctionne sur PlayStation 2, Xbox, Gamecube et PC. Le jeu a été développé par EA Canada puis édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/NBA_Live_2005'),
  ('Q656028', 'Giants: Citizen Kabuto est un jeu vidéo de Jeu de tir à la première personne ou tir à la troisième personne qui mélange plusieurs styles de gameplay. Le jeu est sorti le 7 décembre 2000 sur PC, il a été développé par Planet Moon Studios et édité par Interplay Entertainment. Il a ensuite été porté sur PlayStation 2 en 2001 par Digital Mayhem, puis sur Mac par MacPlay la même année.', 'https://fr.wikipedia.org/wiki/Giants:_Citizen_Kabuto'),
  ('Q225912', 'Kingdom Hearts est un jeu vidéo d’action-RPG développé et édité par Square et distribué par Disney Interactive à partir de 2002 sur PlayStation 2. Il s’agit du premier opus de la série Kingdom Hearts qui résulte de la collaboration entre les studios Square et Disney. Le jeu combine ainsi de nombreux personnages et lieux issus des univers de Disney et de Square dans un jeu d’action-RPG. La popularité du jeu se ressent dans la publication de romans et d’une série de mangas basés sur son histoire.

L’histoire suit un jeune garçon, Sora, poussé dans une bataille contre les forces des ténèbres. Pour l’aider dans sa quête, il est rejoint par Donald Duck, Dingo et d’autres personnages de Disney.', 'https://fr.wikipedia.org/wiki/Kingdom_Hearts_(jeu_vid%C3%A9o)'),
  ('Q235710', 'Futurama est un jeu de plates-formes en 3D sorti en 2003 sur PlayStation 2 et Xbox (le projet de développement sur GameCube a été abandonné). Il se déroule dans l''univers de la série d''animation Futurama.', 'https://fr.wikipedia.org/wiki/Futurama_(jeu_vid%C3%A9o)'),
  ('Q1074108', '25 to Life est un jeu vidéo de tir à la troisième personne développé par Avalanche Software et édité par Eidos Interactive, sorti en 2006 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/25_to_Life'),
  ('Q1087832', 'Warriors Orochi est un jeu vidéo d''action disponible sur les plates-formes PSP, Xbox 360, PS2 et PC. Développé par Koei et sorti en 2007, ce jeu est un mélange de la série Dynasty Warriors et celle de Samurai Warriors.', 'https://fr.wikipedia.org/wiki/Warriors_Orochi'),
  ('Q1078509', 'Shonen Jump''s One Piece Grand Battle, connu au Japon sous le titre One Piece: Grand Battle Rush! est un jeu vidéo de combat développé par Ganbarion et édité par Bandai en 2005 sur PlayStation 2 et GameCube.', 'https://fr.wikipedia.org/wiki/Shonen_Jump%27s_One_Piece:_Grand_Battle'),
  ('Q223381', 'Final Fantasy X, est le dixième épisode canon de la série de jeux de rôle Final Fantasy, et le premier épisode sorti sur la PlayStation 2 de Sony. Le titre sort au Japon le 19 juillet 2001, aux États-Unis le 18 décembre 2001, en Europe le 29 mai 2002 puis en Corée du Sud le 4 juin 2002. Il s''agit du premier jeu de la série à être édité en Corée.

Final Fantasy X/X-2 HD Remaster, une compilation réunissant le jeu et sa suite Final Fantasy X-2, sort le 21 mars 2014 sur PlayStation 3 et PlayStation Vita. Elle comprend les deux jeux dans leurs éditions internationales, et propose un contenu inédit en Europe avec l''épisode The Last Mission pour Final Fantasy X-2.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_X'),
  ('Q633011', 'Final Fantasy X-2 (X-2 est prononcé « dix-deux ») est un jeu vidéo de rôle développé initialement par Squaresoft et édité par l''entreprise japonaise Enix. Il s''agit de la suite de Final Fantasy X, faisant du jeu le premier Final Fantasy à être la suite directe d''un précédent épisode. Il est sorti en mars 2003 au Japon, en novembre en Amérique du Nord, puis en février 2004 en Europe sur Playstation 2.

Le jeu est réédité dans une version internationale en février 2004 au Japon. Cette version contient de nombreuses scènes supplémentaires et cinématiques exclusives.

Final Fantasy X/X-2 HD Remaster, une compilation réunissant le jeu et Final Fantasy X, sort le 21 mars 2014 en France sur PlayStation 3 et PlayStation Vita, puis est portée sur d''autres plates-formes. La compilation comprend les deux jeux dans leurs éditions internationales, et propose un contenu inédit en Europe avec l''épisode The Last Mission pour Final Fantasy X-2[réf. nécessaire].', 'https://fr.wikipedia.org/wiki/Final_Fantasy_X-2'),
  ('Q642062', 'Harvest Moon: Save the Homeland est un jeu vidéo de type simulation de vie / RPG sorti le 20 novembre 2001 aux États-Unis sur PlayStation 2. C''est le premier jeu de la série Harvest Moon publié sur cette console. Une version téléchargeable pour PS4 est sortie sur le PS Store le 9 mai 2017.', 'https://fr.wikipedia.org/wiki/Harvest_Moon:_Save_the_Homeland'),
  ('Q1093923', 'Spider-Man: Allié ou Ennemi (Spider-Man: Friend or Foe) est un jeu vidéo d''action développé par Next Level Games et édité par Activision en 2007 sur Xbox 360, Wii et PlayStation 2. Parallèlement, Artificial Mind & Movement a développé les versions Nintendo DS et PSP, et Beenox Studios pour la version Windows.', 'https://fr.wikipedia.org/wiki/Spider-Man_:_Alli%C3%A9_ou_Ennemi'),
  ('Q1092945', 'Battlefield 2: Modern Combat est un jeu de tir à la première personne basé sur la franchise Battlefield de Electronic Arts. Tout d''abord sorti sur PlayStation 2 et Xbox, c''est le premier épisode de la série à sortir sur console.', 'https://fr.wikipedia.org/wiki/Battlefield_2:_Modern_Combat'),
  ('Q644793', 'Deus Ex [deɪəsˈɛks] (parfois abrégé DX) est un jeu vidéo alliant la jouabilité d''un jeu de tir à la première personne avec les possibilités d''évolution d''un personnage et la liberté d''action propres au jeu de rôle. Développé par Ion Storm Austin et édité par Eidos Interactive en 2000, le jeu est sorti sur Windows et Mac OS; en 2002, il a été adapté sur PlayStation 2 et renommé en Deus Ex: The Conspiracy en dehors d''Europe. Le 16 mai 2012, Square Enix a annoncé un portage sur le PlayStation Network, dans la catégorie « Classique PS2 ».

L''action se déroule en 2052, dans un futur dystopique et cyberpunk. Le joueur incarne l''agent JC Denton, l''un des premiers humains au corps rempli de millions de nanorobots qui lui confèrent des capacités supérieures. Fraichement intégré au sein de l''UNATCO, une agence antiterroriste internationale sous l''égide de l''Organisation des Nations unies (ONU), JC découvre rapidement que la question du terrorisme est bien plus complexe que ce qu''on veut lui faire croire; il se retrouve au centre d''une conspiration politique mondiale mêlant de nombreuses organisations secrètes où les desseins de chacun ne se révèlent que progressivement.', 'https://fr.wikipedia.org/wiki/Deus_Ex_(jeu_vid%C3%A9o)'),
  ('Q641697', 'Red Dead Revolver est un jeu vidéo d''action-aventure développé par Rockstar San Diego et édité par Rockstar Games sur PlayStation 2 et Xbox. Il est commercialisé le 3 mai 2004 en Amérique du Nord et le 11 juin en Europe.

Il s''agit du premier opus de la série de jeux vidéo Red Dead.', 'https://fr.wikipedia.org/wiki/Red_Dead_Revolver'),
  ('Q838147', 'Beatmania IIDX 10th style est un jeu de rythme qui fait partie de la série des Beatmania IIDX.', 'https://fr.wikipedia.org/wiki/Beatmania_IIDX_10th_style'),
  ('Q838152', 'Beatmania IIDX 7th style est un jeu de rythme qui fait partie de la série des Beatmania IIDX.', 'https://fr.wikipedia.org/wiki/Beatmania_IIDX_7th_style'),
  ('Q838156', 'Beatmania IIDX 9th style est un jeu de rythme qui fait partie de la série des Beatmania IIDX.', 'https://fr.wikipedia.org/wiki/Beatmania_IIDX_9th_style'),
  ('Q838178', 'Beatmania IIDX 8th style est un jeu de rythme qui fait partie de la série des Beatmania IIDX.', 'https://fr.wikipedia.org/wiki/Beatmania_IIDX_8th_style'),
  ('Q837338', 'Silent Hill 3 est un jeu vidéo de genre survival horror développé et édité par Konami, sorti en 2003 sur PlayStation 2 et ensuite sur Windows. C''est le 3e épisode de la série Silent Hill et, scénaristiquement, la suite directe de Silent Hill, sorti en 1999 sur PlayStation.

Silent Hill 2 et Silent Hill 3 font partie de la compilation Silent Hill HD Collection (en) sortie en mars 2012 sur PlayStation 3 et Xbox 360.

À la suite du succès des ventes de Silent Hill 2 Remake, un remake de ce troisième jeu, intitulé Silent Hill 3 Remake, serait en développement par Bloober Team.', 'https://fr.wikipedia.org/wiki/Silent_Hill_3'),
  ('Q1206519', 'Katamari Damacy est un jeu vidéo d''action-réflexion développé et édité par Namco sur PlayStation 2. Il est sorti le 18 mars 2004 au Japon et le 21 septembre 2004 en Amérique du Nord. Le jeu est issu d''un projet du Namco Digital Hollywood Game Laboratory, école de développement de jeu vidéo fondée par Namco, avec un budget total de moins d''un million d''euros. L''équipe menée par Keita Takahashi a gardé quatre points à l''esprit lors de la conception du jeu: la fraîcheur et la facilité de compréhension du concept, l''humour ainsi que le plaisir procuré en y jouant.

Le jeu met en scène un petit prince en mission pour reconstruire les étoiles, constellations et la Lune, détruites par inadvertance par son père, le Roi de tout le Cosmos. Pour ce faire, il se sert d''un katamari, une boule magique adhésive qui grandit à mesure qu''elle amasse des objets, jusqu''à ce qu''elle soit assez grande pour former une nouvelle étoile. Le jeu se déroule dans un Japon contemporain fortement stylisé, à différentes échelles.', 'https://fr.wikipedia.org/wiki/Katamari_Damacy'),
  ('Q1203242', 'The Matrix: Path of Néo est un jeu vidéo d''action-aventure développé par Shiny Entertainment et sorti en 2005.', 'https://fr.wikipedia.org/wiki/The_Matrix:_Path_of_Neo'),
  ('Q1205695', 'Akane-Iro ni Somaru Saka est un jeu vidéo de type visual novel / roman vidéoludique japonais pour adulte développé par Feng et sorti le 27 juillet 2007 puis adapté en manga et en anime.', 'https://fr.wikipedia.org/wiki/Akane-Iro_ni_Somaru_Saka'),
  ('Q1201073', 'Da Capo II est un visual novel japonais développée par Circus. Il est sorti le 26 mai 2006 pour les ordinateurs sous Microsoft Windows. C''est la suite directe de Da Capo sorti en 2002. Il a été adapté sous de nombreuses formes.', 'https://fr.wikipedia.org/wiki/Da_Capo_II'),
  ('Q647667', 'Scooby-Doo! Démasqué (Scooby-Doo! Unmasked) est un jeu vidéo de plates-formes développé par Artificial Mind and Movement et édité par THQ, sorti en 2005 sur GameCube, PlayStation 2, Xbox, Game Boy Advance et Nintendo DS.', 'https://fr.wikipedia.org/wiki/Scooby-Doo!_D%C3%A9masqu%C3%A9'),
  ('Q1315644', 'Pro Evolution Soccer 2012 (abrégé en PES 2012) est un jeu vidéo de football de Konami qui est sorti le 29 septembre 2011 sur PlayStation 3, Xbox 360, PC, Nintendo DS le 27 octobre 2011 sur PSP et PS2 le 10 novembre 2011 sur Wii et prochainement sur Nintendo 3DS, iOS et Android.

La démo sortie le mercredi 24 août sur le PSN et sur PC permet de jouer des matchs de 10 minutes avec 4 équipes en mode exhibition: Manchester United, Naples, Milan AC et FC Porto et 2 équipes de Copa Santander. La seconde démo permet de jouer avec Tottenham Hotspur, l''Inter Milan, le Bayern Munich, et le Rangers Football Club pour l''Europe, le Club América, et l''Internacional pour l''Amérique du Sud.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_2012'),
  ('Q1317811', 'Mortal Kombat: Mystification (communément abrégé MK:M) est un jeu vidéo de combat, de la série Mortal Kombat. Il est connu sous le nom de Mortal Kombat: Deception dans le reste du monde. Il fait suite à Mortal Kombat: Deadly Alliance et est sorti en France sur PlayStation 2 et Xbox. Il est également sorti sur Gamecube en mars 2005 aux États-Unis.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_:_Mystification'),
  ('Q1316321', 'Klonoa 2: Lunatea''s Veil est un jeu vidéo de plates-formes développé et édité par Namco, sorti à partir de 2001 sur PlayStation 2. Il s''agit du troisième jeu de la série Klonoa.', 'https://fr.wikipedia.org/wiki/Klonoa_2:_Lunatea%27s_Veil'),
  ('Q840733', 'SOS: The Final Escape, ou Disaster Report en Amérique du Nord, est un jeu vidéo d''action-aventure et de survie, développé par Irem sur PlayStation 2. Il est sorti au Japon le 25 avril 2002, puis en Europe en novembre 2002 et en Amérique du Nord en février 2003.

Le jeu met en scène divers personnages qui tentent de survivre et de s''échapper d''une île artificielle construite sur l''Océan Pacifique, qui s''effondre inéluctablement. Le joueur incarne Keith Helm, un jeune reporter qui doit enquêter sur les causes de la catastrophe, tout en essayant de se frayer un chemin hors de l''île, en évitant les immeubles qui s''écroulent autour de lui et les débris provoqués par les fréquents tremblements de terre.', 'https://fr.wikipedia.org/wiki/SOS:_The_Final_Escape'),
  ('Q845695', 'Gran Turismo 4 (GT4) est un jeu vidéo de course automobile développé par Polyphony Digital et édité par Sony Computer Entertainment en 2004 sur PlayStation 2.

Le jeu fait partie de la série Gran Turismo. Il s''est vendu à près de 12 millions d''exemplaires dans le monde.', 'https://fr.wikipedia.org/wiki/Gran_Turismo_4'),
  ('Q1117741', 'Medal of Honor: Avant-garde (en anglais, Medal of Honor: Vanguard) est un jeu vidéo développé par EA Los Angeles et édité par Electronic Arts. Il s’agit d’un jeu de tir à la première personne sorti en 2007 sur PlayStation 2 et Wii. Il fait partie de la série Medal of Honor.

Le jeu se déroule durant la seconde Guerre mondiale.', 'https://fr.wikipedia.org/wiki/Medal_of_Honor_:_Avant-garde'),
  ('Q1112104', 'Ace Combat: Squadron Leader (appelé Ace Combat 5: The Unsung War dans les versions non-européennes) est un simulateur de vol de combat sur PlayStation 2, sorti le 21 octobre 2004 au Japon, le 24 octobre 2004 en Amérique du Nord et le 23 février 2005 en Europe. Il est développé et édité par Namco.', 'https://fr.wikipedia.org/wiki/Ace_Combat:_Squadron_Leader'),
  ('Q1114671', 'Leisure Suit Larry: Magna Cum Laude est un jeu vidéo sorti en 2004, huitième opus de la série Leisure Suit Larry. C''est le premier opus sans le protagoniste original, Larry Laffer, remplacé par son neveu Larry Lovage. Cet opus marque le départ d''Al Lowe, créateur de la série.', 'https://fr.wikipedia.org/wiki/Leisure_Suit_Larry:_Magna_Cum_Laude'),
  ('Q377242', 'Tom Clancy''s Splinter Cell est un jeu vidéo d''infiltration développé par Ubisoft Montréal au Québec.

La participation de l''écrivain Tom Clancy semble ambigüe. Roxane Gosselin, producteur associé du jeu, déclare: « Tom Clancy était très impliqué dans le scénario – il a étudié le script et nous a donné beaucoup de bons conseils»; d''autres articles semblent indiquer au contraire que l''écrivain ne semblait accorder que peu d''intérêt au projet, et que son équipe n''aurait donné qu''une seule indication: le joueur ne pouvait en aucun cas commettre de meurtre dans une église.

Le héros, Sam Fisher, est un ancien commando de marine de l''US Navy SEALS devenu agent d''élite d''Echelon 3, une entité secrète de la NSA (National Security Agency). Hyper-entraîné dans l''art du déplacement furtif, de l''infiltration et de l''utilisation des technologies de la guerre de l''information, il sait se glisser d''une zone d''ombre à l''autre afin de réaliser les objectifs qui lui ont été assignés (collecte de renseignements, sabotage, etc.), tout en se méfiant des gardes, qui n''hésiteront pas à l''abattre s''il n''est pas assez discret, pour se faufiler derrière eux sans être vu.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Splinter_Cell_(jeu_vid%C3%A9o)'),
  ('Q308961', 'Call of Duty 3: En marche vers Paris est un jeu de tir à la première personne développé par Treyarch et édité par Activision en 2006. Le jeu est sorti sur PlayStation 2, PlayStation 3, Xbox, Xbox 360 et Wii.

Comme les deux premiers épisodes de la série, le jeu prend pour cadre la Seconde Guerre mondiale. L''histoire se concentre sur la Bataille de la Poche de Falaise vécue sous différents points de vue (américain, anglais, français, canadien et polonais). Le sous-titre "En marche vers Paris" n''est inclus que dans le titre français du jeu, et l''épisode ne permet pas de revivre la Libération de Paris en elle-même.', 'https://fr.wikipedia.org/wiki/Call_of_Duty_3_:_En_marche_vers_Paris'),
  ('Q310003', 'Killer7 est un jeu vidéo d''action-aventure développé par Grasshopper Manufacture et édité par Capcom en 2005 sur GameCube et PlayStation 2. Un remaster sur PC est annoncé en mai 2018 et sort en novembre de la même année.', 'https://fr.wikipedia.org/wiki/Killer7'),
  ('Q1186739', 'WWE All Stars est un jeu d''arcade-combat publié par THQ et développé par THQ San Diego sur consoles PlayStation 2, PlayStation 3, PlayStation Portable, Wii et Xbox 360 dans le cadre d''un contrat d''édition avec la branche de catch professionnel World Wrestling Entertainment (WWE). Dans la même lignée que la série Smackdown vs. Raw, All-Stars s''écarte tout de même du concept de simulation, tous ses aspects sont en effet caricaturés, exagérés autant les personnages que les combats en eux-mêmes l''idée étant de faire s''affronter le plus grand roster jamais réuni. Il est sorti le 29 mars 2011 aux États-Unis et le 1er avril 2011 en Europe.', 'https://fr.wikipedia.org/wiki/WWE_All_Stars'),
  ('Q1182593', 'Defender est un jeu vidéo développé par Williams Electronics, paru en 1981 sur borne d''arcade. C''est le shoot ''em up qui inaugure le scrolling horizontal. Defender a été, grâce aux nouveautés apportées au genre et à sa rapidité, un jeu très populaire dans les salles d''arcade au début des années 1980.

Il a donné lieu à une suite, avec Stargate (également appelé Defender II) en 1981, et un remake sur ps2 en 2002 sous le titre Defender: For All Mankind.', 'https://fr.wikipedia.org/wiki/Defender_(jeu_vid%C3%A9o,_1981)'),
  ('Q1353904', 'Otome wa boku ni koishiteru, également connu sous le nom d''Otoboku, est un visual novel de type eroge développé et édité au Japon par Caramel Box le 28 janvier 2005 sur PC (Windows). Le jeu est ensuite adapté sur PlayStation 2 et PlayStation Portable, sans contenu pour adultes. La version Windows est éditée en anglais par MangaGamer en 2012. L''histoire relate la vie de Mizuho Miyanokouji, un lycéen androgyne transféré dans une école pour filles selon les dernières volontés de son grand-père.

Le gameplay d’Otoboku est non linéaire et offre des scénarios prédéterminés, qui se concentrent sur l’intérêt que portent les six personnages principaux féminins au personnage joueur. Le jeu se classe au second rang des ventes de jeux bishōjo PC lors de sa sortie au Japon, puis intègre plusieurs fois dans le top 50 des ventes. Caramel Box édite deux fan disc en 2005 et 2007, respectivement Caramel Box Yarukibako et Caramel Box Yarukibako 2, qui permettent de compléter l''histoire d''Otoboku. Une suite d’Otoboku intitulée Otome wa boku ni koishiteru: Futari no Elder, est éditée le 30 juin 2010 sur PC. Cette suite est également adaptée sur PlayStation Portable sans son contenu réservé aux adultes. Elle reprend le contexte de son aîné, mais intègre un personnage différent nommé Chihaya Kisakinomiya.', 'https://fr.wikipedia.org/wiki/Otome_wa_boku_ni_koishiteru'),
  ('Q1334705', 'Metal Slug 3 est un jeu vidéo du type run and gun développé et édité par SNK en 2000 sur Neo-Geo MVS et Neo-Geo AES (NGM 256). C''est le quatrième épisode de la série Metal Slug, il a été porté sur PlayStation 2 en 2003 et sur Xbox en 2004 Xbox.', 'https://fr.wikipedia.org/wiki/Metal_Slug_3'),
  ('Q1343613', 'Garou: Mark of the Wolves est un jeu de combat 2D développé par SNK et sorti sur Neo-Geo MVS en 1999 et Neo-Geo AES en 2000 (NGM / NGH 253). Le jeu est réédité en 2001 sur Dreamcast, en 2005 sur PlayStation 2 et en 2020 sur PlayStation 4. Huitième épisode de la série Fatal Fury, il est l''un des derniers jeux de SNK avant son rachat. Garou: Mark of the Wolves est considéré comme l''un des plus grands jeux de combat.[réf. nécessaire]', 'https://fr.wikipedia.org/wiki/Garou:_Mark_of_the_Wolves'),
  ('Q842259', 'FIFA 08 est un jeu vidéo de football développé et édité par Electronic Arts en 2007. Le jeu est disponible sur PlayStation 2, PlayStation 3, Xbox 360, Wii, Windows, Nintendo DS et PlayStation Portable.

C''est le 14e épisode la série FIFA Football.

Cet épisode propose un mode en ligne permettant de créer des compétitions ou d''y participer, et également de participer à des modes en 5 contre 5. L''autre grande nouveauté est le mode "deviens pro" qui permet d''incarner et de contrôler un seul joueur sur le terrain.', 'https://fr.wikipedia.org/wiki/FIFA_08'),
  ('Q840889', 'Devil May Cry est un jeu vidéo d''action développé par Capcom Production Studio 4 et édité par Capcom en 2001 sur PlayStation 2. Il a connu un succès critique et commercial et fut suivi de quatre autres épisodes. Une adaptation en anime par le Studio Madhouse a également vu le jour en 2007.', 'https://fr.wikipedia.org/wiki/Devil_May_Cry_(jeu_vid%C3%A9o)'),
  ('Q663665', 'Need for Speed: ProStreet est un jeu vidéo de course automobile développé par EA Black Box et édité par Electronic Arts en 2007 de la série des Need For Speed. Le jeu est disponible sur PlayStation 2, PlayStation 3, Wii, Windows, Xbox 360, Nintendo DS, PSP.', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_ProStreet'),
  ('Q665785', 'Tomb Raider: Legend est un jeu vidéo développé par Crystal Dynamics et édité par Eidos Interactive. Mélange d’action-aventure et de plates-formes, le jeu est sorti sur PlayStation 2, Windows, Xbox et Xbox 360 en avril 2006. Il a par la suite été porté sur GameCube, Game Boy Advance, Nintendo DS et PlayStation Portable avec l’assistance de Buzz Monkey Software et HumanSoft.

Il s’agit du septième épisode de la série Tomb Raider et le premier à ne pas avoir été développé par le studio britannique Core Design. Cette décision d’Eidos fait suite aux ventes décevantes et la réception critique désastreuse du précédent opus, L’Ange des ténèbres.', 'https://fr.wikipedia.org/wiki/Tomb_Raider:_Legend'),
  ('Q663782', 'World Racing est un jeu de course de voiture, plutôt orienté arcade, développé par Synetic, édité par TDK Mediactive, sorti en février 2003 sur Xbox et en septembre 2003 sur Windows et sur PlayStation 2. Le jeu comprend la plupart des voitures Mercedes-Benz, et seulement cette marque. Le nombre de voitures et de circuits disponibles s''élève à plus de 100. Le jeu possède également un grand nombre d''environnements différents, qui sont au nombre de sept, dont les Alpes, le Nevada ou encore l''Australie. En avril 2004, le titre sort sur GameCube, dans une version non optimisée malgré le retard de la date de sortie par rapport aux autres supports. Une suite, World Racing 2, est sortie le 25 novembre 2005 sur Xbox, Playstation 2 et sur ordinateur.', 'https://fr.wikipedia.org/wiki/World_Racing'),
  ('Q4189720', 'Tak et le Pouvoir de Juju (Tak and the Power of Juju) est un jeu vidéo de plates-formes développé par Avalanche Software et édité par THQ, sorti en 2003 sur GameCube, PlayStation 2 et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Tak_et_le_Pouvoir_de_Juju_(jeu_vid%C3%A9o)'),
  ('Q4117112', 'Kinetica est un jeu vidéo de course développé par SIE Santa Monica Studio et édité par Sony Computer Entertainment, sorti en 2001 sur PlayStation 2. Il est ressorti sur PlayStation 4 en 2016.', 'https://fr.wikipedia.org/wiki/Kinetica'),
  ('Q4116562', 'Dead to Rights est un jeu vidéo d''action en vue à la troisième personne, développé et édité par Namco, sorti dans un premier temps sur Xbox, puis sur PlayStation 2 et GameCube, et enfin sur PC. Une adaptation du jeu sur Game Boy Advance est sortie en 2004.', 'https://fr.wikipedia.org/wiki/Dead_to_Rights_(jeu_vid%C3%A9o)'),
  ('Q4050405', 'Super Monkey Ball Deluxe est un jeu vidéo de genre party game développé et édité par Sega, sorti en Europe en 2005 sur PlayStation 2 et Xbox. C''est le quatrième jeu de la série Super Monkey Ball, et aussi le premier à être sorti sur PlayStation 2 et Xbox. Le jeu contient l''intégralité des 118 niveaux de Super Monkey Ball et des 140 niveaux de Super Monkey Ball 2, auxquels s''ajoutent 42 niveaux inédits, pour un total de 300 niveaux. Le jeu se distingue aussi par son grand nombre de mini-jeux, parmi lesquels beaucoup ont été créés spécialement pour cette édition Deluxe.

Le jeu a reçu des critiques globalement positives, réussissant à atteindre de très bons scores sur les agrégateurs GameRankings et Metacritic. Les testeurs ont apprécié le système de jeu et les mini-jeux au principe simple mais néanmoins ardus, mais ont regretté l''aspect daté des graphismes et du son, et la trop grande similarité avec les deux premiers jeux de la série.', 'https://fr.wikipedia.org/wiki/Super_Monkey_Ball_Deluxe'),
  ('Q4051592', 'Top Gun: Combat Zones est un jeu vidéo de combat aérien développé et édité par Titus Software, sorti en 2001 sur PlayStation 2, GameCube (en 2002), Windows et Game Boy Advance. Il est adapté du film Top Gun sorti en 1986.', 'https://fr.wikipedia.org/wiki/Top_Gun:_Combat_Zones'),
  ('Q4052993', 'Way of the Samurai 2 est un jeu vidéo d''action-aventure développé par Acquire et édité par Spike, sorti en 2003 sur PlayStation 2 et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Way_of_the_Samurai_2'),
  ('Q1514853', 'SOS Fantômes, le jeu vidéo (Ghostbusters: The Video Game) est un jeu vidéo édité par Atari Inc., en association avec Sony Pictures et qui est sorti en juin 2009 sur les deux dernières consoles de salon PlayStation en Europe (les autres versions arriveront plus tard sur le continent).

Les versions PlayStation 3, Xbox 360 et PC sont développées par le studio Terminal Reality, tandis que les versions PlayStation 2, PlayStation Portable, et Wii sont à la charge de Red Fly Studios. Une version différente pour la Nintendo DS est également développée par Zen Studios (en).

Le joueur incarne un 5e Ghostbuster sans nom et sans textes (néanmoins, on peut entendre sa voix par moments), fraîchement recruté. Le script a été écrit par Dan Aykroyd et Harold Ramis, les scénaristes et acteurs des films originaux. D''ailleurs, les personnages sont joués par les acteurs des films eux-mêmes. L''histoire se déroule après le deuxième film; Dan Aykroyd a même considéré ce jeu comme le troisième épisode (avant que ne sorte bien sûr Sos Fantômes: l''Héritage).', 'https://fr.wikipedia.org/wiki/SOS_Fant%C3%B4mes,_le_jeu_vid%C3%A9o'),
  ('Q1512540', 'Haunting Ground, appelé Demento en version originale japonaise, est un jeu vidéo développé par Capcom Production Studio 1 et édité par la société Capcom, sorti en 2005 sur la console PlayStation 2. Il s''agit d''un spin-off de la série Clock Tower. Le gameplay est d''ailleurs très similaire à Clock Tower 3 et la maniabilité à Resident Evil Outbreak.

Haunting Ground est un jeu d''horreur psychologique. Le joueur incarne une jeune femme, Fiona Belli, qui se retrouve piégée dans un château occupé par d''inquiétants personnages. La survie de l''héroïne repose sur la capacité à fuir ses poursuivants et sur la complicité avec un chien, Hewie, qui défend la jeune femme et l''aide à résoudre les énigmes.', 'https://fr.wikipedia.org/wiki/Haunting_Ground'),
  ('Q285449', 'Ef - a fairy tale of the two. (litt. « ef - un conte de fée à deux ») est une série de jeux vidéo japonais pour adulte de type visual novel développée et éditée par Minori sur PC au format DVD. Elle compte deux opus: ef - the first tale. (litt. « ef - le premier conte ») et ef - the latter tale. (litt. « ef - le second conte »), sortis respectivement le 22 décembre 2006 et le 30 mai 2008 au Japon uniquement. La vidéo d''introduction du jeu est réalisée par Makoto Shinkai et la bande son est composée par Tenmon avec qui l''auteur et l''éditeur ont déjà travaillé. Le chara design féminin est assuré par Naru Nanao et le masculin par 2C Galore.', 'https://fr.wikipedia.org/wiki/Ef:_A_Fairy_Tale_of_the_Two'),
  ('Q285208', 'Syphon Filter: The Omega Strain est un jeu vidéo de Tir à la troisième personne et d''infiltration développé par SCE Bend Studio et édité par Sony Computer Entertainment en 2004 sur PlayStation 2.

Le jeu fait partie de la série Syphon Filter.

Un des scénarios originellement prévu a été censuré par Sony après d''intenses pressions de politiciens québécois. Le joueur devait abattre des terroristes du Front de libération du Québec qui perpétraient une attaque dans un centre commercial et dans le métro de Toronto. La Toronto Transit Commission a également critiqué le jeu.', 'https://fr.wikipedia.org/wiki/Syphon_Filter:_The_Omega_Strain'),
  ('Q288884', 'G.I. Joe: Le Réveil du Cobra (G.I. Joe: The Rise of Cobra) est un jeu vidéo d''action développé par Double Helix Games et édité par Electronic Arts, sorti en 2009 sur PlayStation 2, PlayStation 3, Wii, Xbox 360, PlayStation Portable et Nintendo DS. Il est adapté du film G.I. Joe: Le Réveil du Cobra, lui-même basé sur la gamme de jouets G.I. Joe.', 'https://fr.wikipedia.org/wiki/G.I._Joe_:_Le_R%C3%A9veil_du_Cobra_(jeu_vid%C3%A9o)'),
  ('Q285827', '4x4 Evo 2 (abréviation de 4x4 Evolution 2) est un jeu vidéo de course développé par Terminal Reality et édité par Gathering of Developers sur Windows et Xbox en 2001 en Amérique du Nord, puis en 2002 en Europe. La même année, le jeu est publié par Aspyr sur MacOS seulement en Amérique du Nord, et par Universal Pictures sur GameCube dans la même région. En 2003, il est édité par Bam! Entertainment sur PlayStation 2 uniquement en Europe. Il s''agit de la suite de 4x4 Evolution (2000).', 'https://fr.wikipedia.org/wiki/4x4_Evo_2'),
  ('Q287276', 'Destroy All Humans! 2 est un jeu vidéo de plates-formes sorti sur PlayStation 2 et Xbox. Il s''agit de la suite de Destroy All Humans!. Le jeu est sorti le 17 octobre 2006 aux États-Unis. Le jeu a été développé par Pandemic Studios.', 'https://fr.wikipedia.org/wiki/Destroy_All_Humans!_2'),
  ('Q249167', 'V-Rally 3 est un jeu vidéo de course de rallye automobile développé par Eden Studios et édité par Infogrames sous la marque Atari en 2002 sur PlayStation 2 et Game Boy Advance. Le jeu a été adapté l''année suivante sur Xbox, GameCube et Windows.', 'https://fr.wikipedia.org/wiki/V-Rally_3'),
  ('Q247935', 'Metal Gear Solid 3: Snake Eater est un jeu vidéo d''action-infiltration créé, produit et réalisé par Hideo Kojima, développé et édité par Konami en 2004 sur PlayStation 2. Il a été réédité en 2006 sur le même support avec un nouveau sous-titre: Subsistence; et en 2012 sur Nintendo 3DS sous le titre Metal Gear Solid: Snake Eater 3D.

Il s''agit d''une préquelle, et non une suite directe à Metal Gear Solid 2: Sons of Liberty.

En mai 2023, un remake intitulé Metal Gear Solid Delta: Snake Eater est annoncé sur PlayStation 5, Xbox Series et Microsoft Windows pour le 28 août 2025.', 'https://fr.wikipedia.org/wiki/Metal_Gear_Solid_3:_Snake_Eater'),
  ('Q250989', 'TOCA Race Driver 3 est un jeu vidéo de course automobile de la série TOCA développé et édité par Codemasters en 2006 sur PlayStation 2, Windows et Xbox.', 'https://fr.wikipedia.org/wiki/TOCA_Race_Driver_3'),
  ('Q247210', 'Need for Speed: Underground (abrégé en NFSU) est un jeu vidéo de course développé par EA Black Box et publié par Electronic Arts en 2003. Il fait partie de la série des Need for Speed.

L''ambiance du jeu (voitures tuning suréquipées participant à des courses de rues illégales) a été grandement inspiré par la culture de la scène import et les films Fast and Furious et 2 Fast 2 Furious.

NFSU est un opus complètement repensé de la série des Need for Speed qui propose un mode carrière (l''underground) avec une histoire, et un mode garage qui permet aux joueurs de personnaliser entièrement leurs voitures au niveau performance et visuel avec un grand nombre de marques. Toutes les courses se déroulent dans une ville la nuit. Le terme « Underground » (lit. souterrain) du titre fait référence aux voitures « tunées » et à la scène import plutôt qu''à l''économie souterraine. Tout cela, ajouté au style de jeu d''arcade, sont devenues des points controverses pour les fans de Need for Speed. Cependant, ce titre a été un très grand succès commercial et a inspiré une suite.', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_Underground'),
  ('Q693311', 'Rez est un jeu vidéo développé par United Game Artists et édité par Sega. Il est sorti sur Dreamcast et PlayStation 2 en 2001.

Le jeu a été réédité sous le titre Rez HD et Rez Infinite.', 'https://fr.wikipedia.org/wiki/Rez'),
  ('Q247161', 'Dynasty Warriors 5, connu au Japon sous le titre Shin Sangokumusō 4 est un jeu vidéo de type hack ''n'' slash'' faisant partie de la série Dynasty Warriors, sorti en 2005 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Dynasty_Warriors_5'),
  ('Q684160', 'Yakuza 2 est un jeu vidéo d''action-aventure développé par Amusement Vision et édité par Sega, sorti en 2006 sur la console PlayStation 2. Il fait suite à Yakuza. Il est ensuite sorti sur PlayStation 3 en 2012 et sur Wii U en 2013, uniquement au Japon.

Un remake intitulé Yakuza Kiwami 2, développé par le Ryu ga Gotoku Studio, est sorti sur PlayStation 4 en décembre 2017 au Japon et le 28 août 2018 dans le reste du mondUn an s''est écoulé depuis l''incident impliquant le clan Tojo et les 10 milliards de yens disparus. Kazuma Kiryu et Haruka vivent à présent des jours heureux. Cependant, ils sont replongés dans le feu de l''action lorsque Yukio Terada, le 5e dirigeant du clan Tojo, se fait assassiner sous leurs yeux. Kazuma doit alors reprendre le chemin dangereux qu''il croyait avoir laissé derrière lui pour de bon.', 'https://fr.wikipedia.org/wiki/Yakuza_2'),
  ('Q1314174', 'WWE SmackDown vs. Raw 2010 (également connu sous le titre WWE SvR 2010), est un jeu vidéo de catch professionnel développé par Yuke''s et publié par THQ sur consoles PlayStation 2 (PS2), PlayStation 3 (PS3), PlayStation Portable (PSP), Wii, Nintendo DS, et Xbox 360. Le jeu est la onzième édition de la série WWE SmackDown vs. Raw. Il est commercialisé en octobre 2009. TOSE supervise la version Nintendo DS.

WWE SmackDown vs. Raw 2010 est basé sur la promotion professionnelle de la World Wrestling Entertainment (WWE), et est intitulé d''après les deux branches de la fédération: SmackDown et Raw. Il expose également d''anciennes superstars de la troisième branche ECW. C''est également le dernier jeu à exposer la ECW dans le titre. Similaire aux précédents jeu de la série, cette opus 2010 implique les joueurs dans une variante de matchs et de modes. Le jeu ajoute également plusieurs nouvelles fonctions dans les versions Xbox 360 et PlayStation 3.', 'https://fr.wikipedia.org/wiki/WWE_SmackDown_vs._Raw_2010'),
  ('Q1314852', 'Kessen est un jeu vidéo de tactique en temps réel développé et édité par Koei, sorti en 2000 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Kessen'),
  ('Q1257775', 'Crash TwinSanity (Crash Bandicoot 5: Crash & Cortex no Yabō au Japon) est un jeu vidéo de plates-formes développé par Traveller''s Tales et édité par Vivendi Universal Games le 28 septembre 2004 en Amérique du Nord, le 8 octobre et le 9 décembre de la même année, en Europe et au Japon, sur PlayStation 2 et Xbox. Il s''agit du cinquième opus de la série Crash Bandicoot, qui fait suite à Crash Bandicoot: La Vengeance de Cortex, sorti en octobre 2001.

Le scénario met en scène Crash Bandicoot et le Docteur Neo Cortex, qui doivent s''associer pour contrecarrer les plans des Jumeaux Maléfiques, Victor et Moritz, deux perroquets venus de la Dixième Dimension, désireux de détruire l''île de N. Sanity. Le système de jeu innove par rapport aux titres précédents de la série en permettant d''incarner deux nouveaux personnages jouables, Cortex et sa nièce Nina, et de contrôler Crash et Cortex ensemble.', 'https://fr.wikipedia.org/wiki/Crash_TwinSanity'),
  ('Q1266307', 'Call of Duty: World at War - Final Fronts est un jeu vidéo de tir à la première personne développé par Rebellion Developments et édité par Activision, sorti en 2008 sur PlayStation 2.

Cette version de Call of Duty: World at War propose un scénario et des missions exclusives sur le théâtre du Pacifique et la bataille des Ardennes.', 'https://fr.wikipedia.org/wiki/Call_of_Duty:_World_at_War_-_Final_Fronts'),
  ('Q1265969', 'Sly 3 (nommé Sly 3: Honor Among Thieves dans sa version originale nord-américaine et Kaitou Sly Cooper 3 au Japon) est un jeu vidéo de plate-forme développé par Sucker Punch Productions et édité par Sony Computer Entertainment en 2005 sur PlayStation 2. Il s''agit du troisième volet de la série Sly.

En 2010, le jeu a été remastérisé en haute définition et porté dans une compilation disponible sur PlayStation 3 puis en 2014 sur PlayStation Vita: The Sly Trilogy.', 'https://fr.wikipedia.org/wiki/Sly_3'),
  ('Q327594', 'Final Fantasy XII est un jeu vidéo de rôle développé et édité par Square Enix, sorti sur PlayStation 2 le 16 mars 2006 au Japon. Il a été édité en Amérique du Nord le 31 octobre 2006 par Square Enix, et en Europe en février 2007 par Ubisoft. Avant sa sortie européenne, le jeu s''était déjà vendu à plus de quatre millions d''exemplaires dans le reste du monde.

Final Fantasy XII se déroule dans le monde imaginaire d''Ivalice, où deux puissants empires, Rozarria et Archadia, se disputent la domination des terres. Le jeu débute deux ans après qu''Archadia a annexé le petit royaume de Dalmasca. Dans ce contexte général, le jeu se concentre sur Vaan, un jeune aventurier dalmascan qui rejoint le mouvement de résistance de la princesse Ashe contre l''empire archadien.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_XII'),
  ('Q337995', 'Mushihime-sama est un shoot ''em up développé par Cave. Il est publié en 2004 sur borne d''arcade (Cave 3rd Generation), puis porté sur PlayStation 2 en 2005 et sur Xbox 360 en mai 2012 (version retravaillé en HD). La suite Mushihime-Sama Futari sort en 2006 en arcade et sur Xbox 360 en 2009. Une version Steam est parue le 5 novembre 2015 éditée par Degica.', 'https://fr.wikipedia.org/wiki/Mushihime-Sama'),
  ('Q846051', 'Shadow of the Colossus (littéralement L''Ombre du colosse), ou Wander and the Colossus au Japon, est un jeu vidéo d''action-aventure codéveloppé par Japan Studio et Team Ico (lequel a précédemment dirigé le jeu Ico) et édité par Sony Computer Entertainment pour la PlayStation 2. Le jeu est sorti en octobre 2005 en Amérique du Nord et au Japon, et en février 2006 en Europe.

Le jeu raconte l''histoire d''un jeune homme nommé Wander qui se rend sur une terre abandonnée sacrée afin de redonner vie à Mono une jeune fille. Pour ce faire, il doit combattre et tuer seize colosses en différents endroit où ils évoluent.', 'https://fr.wikipedia.org/wiki/Shadow_of_the_Colossus'),
  ('Q679254', 'Cocoto Kart Racer est un jeu vidéo de course sorti en 2005 sur,PlayStation 2, GameCube, Nintendo DS, en 2006 Game Boy Advance, en 2007 sur Windows, en 2008 sur Wii et en 2009 sur Windows Mobile. Le jeu a été développé par Neko Entertainment et édité par Bigben Interactive.', 'https://fr.wikipedia.org/wiki/Cocoto_Kart_Racer'),
  ('Q682892', 'Kanon est un visual novel japonais développé par Key et sorti le 4 juin 1999. La version originale, conçue pour PC, fut évaluée pour un public majeur (18+) par l''Ethics Organization of Computer Software mais une version tous publics fut éditée en janvier 2000. D''autres versions tous publics furent ensuite produites pour Dreamcast, PlayStation 2, et PlayStation Portable.

Plus tard, une nouvelle version, appelée, la Kanon Standard Edition, fut publiée sur PC sous forme de DVD-ROM dans sa version adulte et tous publics. La Standard Edition incorpore les quelques graphismes supplémentaires des versions tous publics du jeu. Les deux Standard Edition apportent la compatibilité pour Windows 2000/XP ainsi que d''autres améliorations techniques comme l''ajout d''emplacements de sauvegarde supplémentaires. La version tous publics de la Standard Edition est identique aux versions tous publics précédentes.', 'https://fr.wikipedia.org/wiki/Kanon_(visual_novel)'),
  ('Q678394', 'Final Fantasy XI, aussi connu sous le nom de Final Fantasy XI: Online, est un jeu de rôle en ligne massivement multijoueur créé et publié par Square (maintenant Square Enix) en tant qu''élément de la saga Final Fantasy. Il est dans un premier temps sorti au Japon sur la console PlayStation 2 de Sony le 16 mai 2002 et fut publié pour PC Windows le 5 novembre de la même année. Il sortit par la suite sur le marché Américain le 28 octobre 2003. Une version Xbox 360 sortie mondialement en avril 2006 en tant que premier MMORPG de la console. La mise à jour 1.31 du firmware de la PlayStation 3 permet à l''utilisateur d''installer le jeu en utilisant les disques PlayStation 2.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_XI'),
  ('Q862524', 'Harry Potter et le Prince de sang-mêlé est un jeu vidéo d''action-aventure sorti le 2 juillet 2009 sur Nintendo DS, PlayStation 2, PlayStation Portable, Windows, Xbox 360, PlayStation 3, Nintendo Wii et Macintosh. Le jeu est édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Harry_Potter_et_le_Prince_de_sang-m%C3%AAl%C3%A9_(jeu_vid%C3%A9o)'),
  ('Q861203', 'BloodRayne 2 est un jeu vidéo d''action et est le deuxième jeu de la série BloodRayne. Il est sorti en 2004 en Amérique du Nord et en 2006 en Europe. Comme pour le premier épisode, il a été développé par Terminal Reality. Le jeu est sorti sur PlayStation 2, Xbox et Windows.', 'https://fr.wikipedia.org/wiki/BloodRayne_2_(jeu_vid%C3%A9o)'),
  ('Q859380', 'Harry Potter: Coupe du monde de quidditch (Harry Potter: Quidditch World Cup) est un jeu vidéo de sport simulant le quidditch, sport fictif présent dans les aventures de la série littéraire Harry Potter de J. K. Rowling. Le jeu est développé par EA Bright Light et édité par EA Games, et sort en France le 6 novembre 2003, sans pour autant coïncider avec la sortie d''un livre ni d''un film.

Le jeu est disponible sur différentes plateformes: PC, Xbox, PlayStation 2, GameCube et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Harry_Potter_:_Coupe_du_monde_de_quidditch'),
  ('Q1442157', 'Tom Clancy''s Rainbow Six: Lockdown est le quatrième jeu entier de la série Rainbow Six. Il a été développé par Red Storm Entertainment.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Rainbow_Six:_Lockdown'),
  ('Q1453395', 'NBA 2K9 est un jeu vidéo de basket-ball développé par Visual Concepts et édité par 2K Sports sorti en 2008.

Il est disponible en France depuis le 10 octobre 2008 sur PlayStation 3, Xbox 360, PlayStation 2 et PC.

C''est le dixième épisode de la franchise 2K et est le principal concurrent de NBA Live 09.

Avec la licence officielle de la NBA vous pouvez choisir parmi les 30 équipes de la ligue et évoluer avec plusieurs joueurs tels Kobe Bryant ou LeBron James.', 'https://fr.wikipedia.org/wiki/NBA_2K9'),
  ('Q1441569', 'Pro Evolution Soccer 2009 (souvent abrégé PES 2009) est un jeu vidéo de football, édité et développé par Konami. C''est le 8e jeu de la série Pro Evolution Soccer. Le jeu est sorti en Europe le 16 octobre 2008 sur PlayStation 3, Xbox 360, Windows et téléphones mobiles et le 30 octobre 2008 sur PlayStation 2 et PSP. La version Wii est sortie le 26 mars 2009.

Après un volet 2008 très critiqué pour son rendu "arcade" et la montée en puissance de son grand rival FIFA 08, ce nouvel épisode revient aux sources avec un gameplay retouché, de nouveaux modes de jeu (notamment "Be A Legend" comme la Ligue des champions)[réf. nécessaire]. L''argentin Lionel Messi sera l''ambassadeur de ce nouvel épisode. On peut néanmoins signaler que cette version est dépourvue du mode communauté, mode qui avait vu le jour en 2008, qui sera réhabilité pour le PES2010.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_2009'),
  ('Q1456475', 'Neo Contra est un jeu vidéo d''action de type shoot them up développé et édité par Konami. Il fait partie de la série Contra et est une suite directe à Contra: Shattered Soldier. Le jeu est disponible depuis 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Neo_Contra'),
  ('Q307273', 'GrimGrimoire est un Jeu de stratégie en temps réel en 2D développé par Vanillaware pour la PlayStation 2. NIS America s’est occupé de la localisation et de la publication pour l’Amérique et Koei pour l’Europe.', 'https://fr.wikipedia.org/wiki/GrimGrimoire'),
  ('Q290136', 'Space Channel 5 est un jeu vidéo de rythme développé par United Game Artists et édité par Sega sur Dreamcast en 1999. Le jeu est porté sur PlayStation 2 en 2002, puis adapté sur Game Boy Advance par Art Co. en 2003 sous l''appellation Space Channel 5: Ulala''s Cosmic Attack. Le joueur incarne Ulala, une jeune reporter pour la chaîne de télévision spatiale Space Channel 5. Le but du jeu est de sauver des êtres humains d''une invasion extra-terrestre en dansant et en chantant.

Le jeu est conçu par Tetsuya Mizuguchi, avec l''objectif de s''adresser à un public féminin. La production dure deux ans, et l''équipe de développement compte environ vingt personnes. La musique, composée par Naofumi Hataya et Kenichi Tokoi, s''inspire des big bands des années 1960. Le morceau de jazz « Mexican Flyer » de Ken Woodman façonne le style musical du jeu, et en devient la chanson thème. Le style d''ensemble du jeu est influencé par la culture des années 1950 et 1960, et par les clips vidéos ultérieurs de Peter Gabriel et Michael Jackson; ce dernier apparaît en caméo dans le dernier niveau du jeu en tant que Space Michael.', 'https://fr.wikipedia.org/wiki/Space_Channel_5_(jeu_vid%C3%A9o)'),
  ('Q290981', 'Legends of Wrestling II est un jeu vidéo de combat de catch développé par Acclaim Studios Salt Lake City et édité par Acclaim Entertainment, sorti en 2002 sur GameCube, PlayStation 2, Xbox et Game Boy Advance.

Il fait suite à Legends of Wrestling.', 'https://fr.wikipedia.org/wiki/Legends_of_Wrestling_II'),
  ('Q1441478', 'Tom Clancy''s Rainbow Six 3: Raven Shield est un jeu vidéo de type FPS tactique développé par Red Storm Entertainment et édité par Ubisoft en 2003 sur Windows. Il a été adapté sur GameCube, Mac OS X, PlayStation 2 et Xbox.

La version Xbox se nomme Tom Clancy''s Rainbow Six 3: Black Arrow et est une version améliorée.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Rainbow_Six_3:_Raven_Shield'),
  ('Q1437623', 'Formula One 05 est un jeu vidéo de course de Formule 1 développé par Sony Studio Liverpool et édité sur PlayStation 2. Il s''agit d''un jeu officiel de la série Formula One. Le jeu est sorti en Europe le 29 juin 2005 et au Japon le 22 septembre 2005 (soit 3 mois après la sortie du jeu en Europe) pour la PlayStation 2. Le jeu F1 Grand Prix est son équivalent sur PlayStation Portable. Le principal mode du jeu reste le mode carrière, une option en place depuis l''opus précédent.

La cinématique d''introduction du jeu représente une course de Formule 1, le tout sur le morceau Butterflies and Hurricanes de Muse.', 'https://fr.wikipedia.org/wiki/Formula_One_05'),
  ('Q1427606', 'Soldier of Fortune (parfois abrégé SoF) est un jeu vidéo de tir à la première personne créé par Raven Software et édité par Activision sorti le 17 mars 2000 pour Windows. Utilisant un moteur 3D dérivé de celui de Quake II c''est un des premiers jeux à utiliser une localisation des dégâts aussi poussée, ce qui lui a valu de défrayer la chronique lors de sa sortie, étant jugé comme une apologie de la violence dans les jeux vidéo. Il a dû se doter d''un système de contrôle parental prévenant l''apparition du sang dans le jeu.

Il fut ensuite porté sur PlayStation 2 et sur Dreamcast en 2001.

Loki Software l''a également adapté pour GNU/Linux.', 'https://fr.wikipedia.org/wiki/Soldier_of_Fortune_(jeu_vid%C3%A9o)'),
  ('Q1440394', 'Thrillville: Le Parc en folie (Thrillville: Off the Rails) est un jeu vidéo de gestion développé par Frontier Developments et édité par LucasArts, sorti en 2007 sur PlayStation 2, Windows, Xbox 360 et PlayStation Portable, Nintendo DS et Wii.', 'https://fr.wikipedia.org/wiki/Thrillville_:_Le_Parc_en_folie'),
  ('Q1403142', 'Syphon Filter: Logan''s Shadow est un jeu vidéo de Tir à la troisième personne et d''infiltration développé par SCE Bend Studio et édité par Sony Computer Entertainment en 2007 sur PlayStation Portable.

Il s''agit du 6e épisode de la série Syphon Filter. L''histoire mélange contre-terrorisme, avec un groupe voulant se procurer une nouvelle technologie de destruction, et complots internes, avec Lian Xing qui se retrouve accusée d''être un agent double. Visuellement très similaire à Dark Mirror, le gameplay propose en plus des combats sous-marins et des actions contextuelles pendant le jeu, par exemple pour éliminer discrètement un ennemi.', 'https://fr.wikipedia.org/wiki/Syphon_Filter:_Logan%27s_Shadow'),
  ('Q1371574', 'Samurai Warriors (Sengoku Musou) est un jeu vidéo de type hack ''n'' slash, développé par Koei et publié en 2004.', 'https://fr.wikipedia.org/wiki/Samurai_Warriors'),
  ('Q1324448', 'Ico est un jeu vidéo d''action-aventure développé par la Team Ico et sorti en 2001 sur PlayStation 2. Une version remastérisée en haute définition est ensuite incluse dans The Ico & Shadow of the Colossus Collection sur PlayStation 3, sorti en septembre 2011.

Le joueur incarne Ico, un garçon né avec des cornes, chose que les habitants de son village considèrent comme un mauvais présage. Après avoir été enfermé dans une forteresse isolée, il libère Yorda, la fille de la Reine des lieux qui compte se servir d''elle pour prolonger sa propre existence. Ico doit coopérer avec Yorda afin de s''échapper du château, tout en la protégeant de leurs ennemis, en l''aidant à franchir différents obstacles et en résolvant des énigmes.', 'https://fr.wikipedia.org/wiki/Ico_(jeu_vid%C3%A9o)'),
  ('Q1318106', 'Pro Evolution Soccer 2011 (abrégé PES 2011) est un jeu vidéo de football sorti sur PlayStation 3, Xbox 360 et PC le 28 septembre 2010. Il est ensuite sorti sur Wii, PlayStation Portable, PlayStation 2 le 28 octobre 2010 et une version 3DS est sorti le 25 mars 2011 (en même temps que la Nintendo 3DS). Ce sera le 10e jeu de la série des Pro Evolution Soccer et il est le principal concurrent de FIFA 11 d''Electronic Arts.

Une Ligue des Masters en ligne, nouveau système de jeu inédit dans la série, permettra d''organiser des confrontations en championnat entre les joueurs du monde entier en lui permettant d''utiliser l''équipe qu''il aura conçue. Il y a également un mode de jeu permettant de créer son propre stade.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_2011'),
  ('Q674217', 'Alexandra Ledermann: Aventures au galop est un jeu vidéo d''équitation développé par Independent Arts et édité par Ubisoft, sorti en 2006 sur Game Boy Advance.

Le jeu s''intitule Pferd und Pony: Mein Gestüt en Allemagne et Horsez en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Alexandra_Ledermann_:_Aventures_au_galop'),
  ('Q671185', 'Taz: Wanted est un jeu vidéo d’action-aventure et jeu de plate-forme développé par Blitz Games et édité par Infogrames, sorti en 2002 sur Windows, GameCube, PlayStation 2 et Xbox.

Il met en scène Taz, le Diable de Tasmanie issu de l’univers des Looney Tunes.', 'https://fr.wikipedia.org/wiki/Taz_Wanted'),
  ('Q1327449', 'Fahrenheit (commercialisé sous l''appellation Indigo Prophecy en Amérique du Nord) est un jeu vidéo d''aventure développé par le studio français Quantic Dream et publié par Atari en 2005.

Le jeu se déroule en 2009 à New York, sous une interminable tempête de neige. Lucas Kane, un banal employé de banque, entre soudainement dans un état de transe et poignarde un homme dans les toilettes d''un diner. Revenu à lui, il panique et s''enfuit. Carla Valenti, l''officier de police chargé de résoudre le meurtre, part à sa recherche, aidée de son adjoint, Tyler Miles. Mais pour ces trois protagonistes, les évènements vont bientôt avoir des conséquences qu''aucun ne soupçonnait. Rapidement, le paranormal s''en mêle et l''affaire prend une envergure mondiale. Sur fond de prophétie millénaire (d''où le Indigo Prophecy (« Prophétie indigo ») du titre américain), le jeu propose de partager la vie des trois personnages pour comprendre ce qu''il se trame.', 'https://fr.wikipedia.org/wiki/Fahrenheit_(jeu_vid%C3%A9o)'),
  ('Q1328117', 'MX vs. ATV Unleashed est un jeu vidéo de simulation de course sorti sur PlayStation 2, Xbox, Microsoft Windows et téléphones mobiles. Développé par Rainbow Studios et publié par THQ, le jeu vidéo est sorti en 2005 en Amérique du Nord et en Europe. MX vs. ATV Unleashed est un crossover entre la trilogie MX de THQ (comprenant MX 2002 featuring Ricky Carmichael, MX Superfly et MX Unleashed) et la série ATV Offroad Fury de Sony, et il propose le même support de console pour deux joueurs et un support en ligne pour huit joueurs. La version PC dispose d''une fonction « éditeur de piste ».

Un portage PlayStation Portable de Unleashed, intitulé MX vs. ATV: On the Edge, est sorti en 2006, et une suite, MX vs. ATV Untamed est sortie fin 2007.', 'https://fr.wikipedia.org/wiki/MX_vs._ATV_Unleashed'),
  ('Q1328166', 'WALL-E est un jeu vidéo d''action-aventure édité par THQ et développé par Asobo Studio, Heavy Iron Studios ou Helixe selon les plates-formes, adapté du film du même nom réalisé par le studio d''animation Pixar sorti en 2008.', 'https://fr.wikipedia.org/wiki/WALL-E_(jeu_vid%C3%A9o)'),
  ('Q484634', 'Togainu no Chi est un jeu vidéo de type visual novel créé par Nitro+chiral. Le jeu a premièrement été édité au Japon sur PC en 2005, puis sur PlayStation 2 en 2008. Il est aussi sorti sur PSP en décembre 2010.

Il a aussi été adapté en un roman, trois manga et une série d''anime.

En France, seule la série de manga dessinée par Suguro Chayamachi est sortie, éditée par les éditions Ankama en juin 2011. Cinq volumes sont parus à ce jour.', 'https://fr.wikipedia.org/wiki/Togainu_no_Chi'),
  ('Q496526', 'Tales of Symphonia est un jeu vidéo de rôle développé par Namco Tales Studio et édité par Namco. Il s’agit du septième opus de la série des Tales of. C’est le troisième de la série à être publié en Amérique du Nord et le premier à paraître en Europe. Le jeu est publié à partir de 2003 sur GameCube et, uniquement au Japon, sur PlayStation 2. Il est également sorti sur PlayStation 3 dans la compilation Tales of Symphonia Chronicles. Une version remastérisée est sortie en février 2023 sur Nintendo Switch, PlayStation 4 et Xbox One, avec une compatibilité sur PlayStation 5 et Xbox Series.

Le scénario du jeu prend place dans un monde nommé Sylvarant. Celui-ci est en proie à une pénurie de mana, qui est la source vitale de toute chose. Les Humains qui vivent dans ce monde subissent en outre la persécution des Désians, une organisation composée de Demi-Elfes qui les exploitent. La pénurie de mana et l’invasion des Désians s’expliquent par le sommeil dans lequel est tombé la déesse Martel. Afin de la réveiller, les Anges doivent désigner un Élu qui devra accomplir le périple de la régénération du monde à la Tour du Salut.', 'https://fr.wikipedia.org/wiki/Tales_of_Symphonia'),
  ('Q471974', 'Need for Speed: Undercover est un jeu vidéo de course automobile développé par EA Black Box et édité par Electronic Arts sorti en 2008. Le jeu est disponible sur PlayStation 2, PlayStation 3, Wii, Windows, Xbox 360, Nintendo DS, PlayStation Portable et téléphone portable. Il fait partie de la série Need For Speed.

Need for Speed: Undercover reprend ce qui a fait le succès de la série depuis les versions "tuning", et peut être rapproché de Need for Speed: Most Wanted (2005) Need for Speed: Carbon (2006) et Need for Speed: ProStreet (2007). Le jeu reste sur le principe des poursuites de police et aussi de la possibilité à détruire des éléments du décor en fonçant dedans comme Most Wanted et Carbon.', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_Undercover'),
  ('Q507396', 'Crash: Génération Mutant (Crash: Mind over Mutant) est un jeu d''action-aventure développé par Radical Entertainment pour PlayStation 2, Xbox 360, Wii, Nintendo DS et PSP, sorti le 7 octobre 2008 en Amérique du Nord et le 31 octobre 2008 en Europe et en Australie. Les développeurs de la version Nintendo DS sont une compagnie japonaise de jeux vidéo nommée TOSE. Pour la version PSP, les développeurs restent les mêmes, mais le jeu a été porté directement de la version PlayStation 2 par Virtuos. Le jeu s''est écoulé à 3 millions d''exemplaires. En comptant ce dernier épisode, la série s''est écoulée à plus de 38 millions d''exemplaires.', 'https://fr.wikipedia.org/wiki/Crash_:_G%C3%A9n%C3%A9ration_Mutant'),
  ('Q500586', 'Echo Night: Beyond, connu au Japon sous le titre Nebula: Echo Night, est un jeu vidéo d''action-aventure édité par Indie Games et développé par From Software en 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Echo_Night:_Beyond'),
  ('Q1369501', 'Gran Turismo Concept (GTC) est un jeu vidéo de course automobile développé par Polyphony Digital et édité par Sony Computer Entertainment, sorti en 2002 sur la console PlayStation 2. Le jeu est proposé en trois versions: Gran Turismo Concept: 2001 Tokyo, Gran Turismo Concept: 2002 Tokyo - Seoul et Gran Turismo Concept: 2002 Tokyo - Geneva.', 'https://fr.wikipedia.org/wiki/Gran_Turismo_Concept'),
  ('Q1356946', 'Way of the Samurai, connu au Japon sous le titre Samurai, est un jeu vidéo d''action-aventure développé par Acquire et édité par Spike, sorti en 2002 sur PlayStation 2.

Se déroulant en 1878, durant l’ère Meiji, il permet au joueur d''incarner un rōnin, un samouraï sans maître, errant dans la région du col de Rokkotsu, une localité rurale théâtre d''une lutte de pouvoir entre trois factions rivales: le gouvernement central, la famille Kurou et les traditionalistes du clan Akadama.

Le jeu propose une structure narrative ouverte et non linéaire où les choix du joueur, qu’il s’agisse de dialogues ou d’actions, influencent directement le scénario et mènent à l’une des six conclusions possibles. Ainsi, si l’aventure principale ne dure que quelques heures, sa rejouabilité est élevée. Les combats se déroulent en temps réel et intègrent un système de garde, de postures et de techniques variées; la maîtrise de dizaines d’armes (sabres, haches, marteaux, etc.) et leur amélioration par un forgeron sont essentielles.', 'https://fr.wikipedia.org/wiki/Way_of_the_Samurai'),
  ('Q1355158', 'FlatOut 2 est un jeu vidéo de course sorti en 2006 sur PlayStation 2, Windows, Mac OS et Xbox. Le jeu a été développé par Bugbear Entertainment puis édité par Empire Interactive, il fait suite à FlatOut. Il existe une version HD de ce jeu FlatOut: Ultimate Carnage sorti en 2007 sur Xbox 360 puis en 2008 sur PC (Windows). Et une version PlayStation Portable est sortie: elle s''appelle FlatOut: Head On.', 'https://fr.wikipedia.org/wiki/FlatOut_2'),
  ('Q1369354', 'Iron Man est un jeu vidéo d''action développé par Secret Level et édité par Sega sur Windows, PlayStation 3, Xbox 360, Nintendo DS et PlayStation Portable le 2 mai 2008. Parallèlement, Artificial Mind & Movement a développé une autre version pour la Wii et la PlayStation 2.

Le jeu est une adaptation dérivée du film éponyme, sorti le même jour aux États-Unis.', 'https://fr.wikipedia.org/wiki/Iron_Man_(jeu_vid%C3%A9o)'),
  ('Q372385', 'Le Seigneur des anneaux: Le Tiers-Âge est un jeu vidéo de style RPG, sorti sur GameCube, PlayStation 2, Xbox et Game Boy Advance en 2004. Le jeu a été développé par EA Redwood Shores et édité par Electronic Arts, qui disposait des droits d''adaptation de la trilogie cinématographique de Peter Jackson, mais pas de l''univers du roman Le Seigneur des anneaux de J. R. R. Tolkien dont elle était l''adaptation.

Sur GameCube, Playstation 2 et Xbox, on se déplace avec des héros comme Berethor du Gondor, Idrial de la Lothlorien, Elegost de Dunedain, Hadhod de Fundin, Morwen du Penmark ou Eaoden de Riddermark, inventés pour les besoins du jeu. On parcourt des endroits comme la Moria et on combat des ennemis comme le Balrog. Ce jeu est de style RPG. En se promenant pour faire les quêtes et chercher des trésors, on rencontre des ennemis et un combat commence. On choisit, un tour à la fois, les actions de ceux qu''on contrôle. Il y a possibilité de jouer à deux joueurs; quand il n''y a pas de combat, le jeu reste le même, mais lors des combats, chacun des joueurs contrôle son personnage. Dans les combats, il est possible d''obtenir jusqu''à trois personnages sur un maximum de six, qui joignent l''action au cours du jeu.', 'https://fr.wikipedia.org/wiki/Le_Seigneur_des_anneaux_:_Le_Tiers-%C3%82ge'),
  ('Q373305', 'Bloody Roar 4 est un jeu vidéo de combat développé par Hudson Soft et Eighting, édité par Konami, sorti en 2003 sur PlayStation 2 et PlayStation 3.', 'https://fr.wikipedia.org/wiki/Bloody_Roar_4'),
  ('Q373112', 'Romance of the Three Kingdoms VII est un jeu vidéo de grande stratégie et de stratégie au tour par tour développé et édité par Koei, sorti en 2000 sur Windows, Mac, PlayStation 2 et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Romance_of_the_Three_Kingdoms_VII'),
  ('Q367135', 'Dirge of Cerberus: Final Fantasy VII est un jeu vidéo mêlant Action-RPG et tir à la troisième personne, développé par Square Enix, sorti en 2006 au Japon.

Dirge of Cerberus est le troisième projet de Compilation of Final Fantasy VII. L''histoire se déroule trois ans après le jeu original et se fonde sur le personnage de Vincent Valentine, ex-Turk mystérieux. Le jeu se présente sous la forme d''un shooter RPG, combinant à la fois le gameplay des jeux de tir ainsi que celui des jeux de rôles typiques.', 'https://fr.wikipedia.org/wiki/Dirge_of_Cerberus:_Final_Fantasy_VII'),
  ('Q375672', 'X-Squad (X-Fire /Crossfire) est un jeu vidéo d''action développé par Square Electronic Arts et édité par Electronic Arts, sorti en 2000 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/X-Squad'),
  ('Q426939', 'FIFA 11 est un jeu vidéo de football développé par EA Canada et édité par EA Sports. Il est sorti en 2010 sur PC, PlayStation 3, Xbox 360, Nintendo DS, PlayStation Portable, PlayStation 2 et Wii puis a été adapté sur téléphone mobile. Il est le dix-septième jeu de la franchise FIFA Football.

Le jeu propose un mode en ligne permettant de créer des compétitions ou d''y participer, et également à des modes en 11 contre 11. En effet, c''est la première fois dans l''histoire du jeu vidéo de football, qu''un jeu permette d''incarner un gardien mais seulement durant les parties multijoueurs ou en mode "Be a Goalkeeper". Un nouveau mode, « Personnality + », rend chaque joueur avec des réactions uniques.', 'https://fr.wikipedia.org/wiki/FIFA_11'),
  ('Q427467', 'Fate/unlimited codes est un jeu vidéo de combat développé par cavia, inc. et 8ing en collaboration avec Capcom. Il est basé sur le visual novel Fate/stay night. Sorti au Japon le 11 juin 2008 sur les arcades équipées de System 246 et le 18 décembre 2008 sur PlayStation 2, un portage amélioré est sortie pour la PlayStation Portable au Japon le 18 juin 2009, auquel il était par la suite téléchargeable sur le PlayStation Store en Amérique du Nord et en Europe à partir du 3 et 10 septembre 2009 respectivement.

Le 30 mai 2012, il a été signalé qu''en raison de l''expiration de la licence numérique, Capcom USA, la branche américaine de la firme, a dû interrompre la vente du jeu sur le PlayStation Store dans cette région à compter du 12 juin 2012.', 'https://fr.wikipedia.org/wiki/Fate/unlimited_codes'),
  ('Q452402', 'Amagami est un jeu vidéo de drague japonais développé par Enterbrain sur PlayStation 2. Il est considéré comme le successeur spirituel de KimiKiss, les deux jeux ayant été élaborés et publiés par le studio Enterbrain. Amagami est mis en vente le 19 mars 2009. Diverses adaptations en manga sont réalisées à la suite du succès du jeu. Une adaptation en anime intitulée Amagami SS est diffusée au Japon du 1er juillet 2010 au 23 décembre 2010. Une seconde saison, Amagami SS+, est diffusée au Japon du 6 janvier 2012 au 29 mars 2012.', 'https://fr.wikipedia.org/wiki/Amagami'),
  ('Q440046', 'Le Seigneur des anneaux: Le Retour du Roi est un jeu vidéo de 2003 de type beat them all en vue à la troisième personne, développé par EA Redwood Shores et édité par Electronic Arts.

Il est basé sur les deuxième et troisième volets de l''adaptation cinématographique par Peter Jackson du roman Le Seigneur des anneaux de J. R. R. Tolkien: Les Deux Tours et Le Retour du roi, mais sa sortie a été coordonnée avec celle du troisième film, fin 2003. Le Retour du Roi a été développé en collaboration avec New Line Cinema qui détient la franchise des films. Le jeu est proche de son prédécesseur, Le Seigneur des anneaux: Les Deux Tours, mais son scénario se divise en trois branches; il y a aussi plus de personnages jouables, et une plus grande interactivité avec l''environnement. Deux joueurs peuvent jouer dans un mode coopératif sur certaines missions.', 'https://fr.wikipedia.org/wiki/Le_Seigneur_des_anneaux_:_Le_Retour_du_roi_(jeu_vid%C3%A9o)'),
  ('Q431238', 'The King of Fighters: Maximum Impact est un jeu de combat en 3D développé par SNK Playmore et Noise Factory et édité par SNK Playmore, sorti en 2004-2005 sur PlayStation 2 et Xbox.

Il s''agit d''un spin-off de la série The King of Fighters. C''est le 1er à être réalisé en 3D.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters:_Maximum_Impact'),
  ('Q1417303', 'Spartan: Total Warrior est un jeu vidéo de type action-RPG développé par Creative Assembly et publié par Sega le 7 octobre 2005 sur PlayStation 2, GameCube et Xbox. Le jeu est un spin-off de la série de jeux vidéo de stratégie Total War. Contrairement à ses prédécesseurs, le jeu propose en effet un système de jeu de type hack ''n'' slash, le joueur incarnant un guerrier spartiate guidé par le dieu de la guerre Arès et luttant avec ses alliés de la Grèce antique contre l’invasion de l’Empire romain. Il se distingue également du reste de la série en proposant un scénario fictif, mélangeant mythologie grecque et romaines, là où ses prédécesseurs prenaient places dans une trame historique réaliste. Il est enfin le seul opus de la série à avoir été publié sur console plutôt que sur ordinateur.', 'https://fr.wikipedia.org/wiki/Spartan:_Total_Warrior'),
  ('Q1407885', 'Tenchu: La Colère divine (天誅 参) (ou Tenchu: Wrath of Heaven) est un jeu vidéo d''infiltration développé par K2 et édité par Activision en Europe et en Amérique du Nord, et par From Software au Japon. Le jeu est sorti sur PlayStation 2 le 11 mars 2003 aux États-Unis, le 7 mars 2003 en Europe et le 24 avril 2003 au Japon. Le jeu a été porté sur Xbox sous le titre Tenchu: Le Retour des ténèbres (天誅 参 〜回帰ノ章〜) (Tenchu: Return from Darkness), puis sur PlayStation Portable sous le titre Ninja Katsugeki Tenchū San Portable.', 'https://fr.wikipedia.org/wiki/Tenchu_:_La_Col%C3%A8re_divine'),
  ('Q1416931', 'Rayman 3: Hoodlum Havoc est un jeu vidéo de plateforme et d''action-aventure développé par Ubisoft Paris et édité par Ubisoft. Il sort sur Nintendo GameCube en février 2003 puis sur PlayStation 2, Xbox et Microsoft Windows en mars de la même année et enfin sur macOS en février 2004.

Le joueur incarne Rayman, un personnage dépourvu de bras et de jambes mais possédant des mains et des pieds flottants. Sa mission est de sauver la Croisée des Rêves en arrêtant André, un Lums noir ayant créé une armée de Hoodlums pour conquérir le monde. Il progresse aux côtés de Globox, son meilleur ami ayant avalé André par accident et cherchant parallèlement à l''expulser de son corps.', 'https://fr.wikipedia.org/wiki/Rayman_3:_Hoodlum_Havoc'),
  ('Q1422943', 'Jurassic Park: Operation Genesis est un jeu vidéo de gestion s''inspirant de l''univers des films Jurassic Park, réalisés par Steven Spielberg. Développé par Blue Tongue Entertainment et édité par Universal Interactive, le jeu est sorti en 2003 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Jurassic_Park:_Operation_Genesis'),
  ('Q849901', 'Harry Potter et la Coupe de feu est un jeu vidéo d''action-aventure sorti en 2005 sur Game Boy Advance, GameCube, Nintendo DS, PlayStation 2, PlayStation Portable, Windows et Xbox. Le jeu a été édité par Electronic Arts.

Harry Potter et la Coupe de feu utilise la franchise Harry Potter et coïncide avec la sortie du 4e volet de la saga.

Le jeu, a été vendu sur les consoles portables de Nintendo à plus 1 000 000 exemplaires. Ces versions ont été développées par le studio français Magic Pockets.', 'https://fr.wikipedia.org/wiki/Harry_Potter_et_la_Coupe_de_feu_(jeu_vid%C3%A9o)'),
  ('Q846388', 'Zwei!! est un jeu vidéo de type action-RPG développé et édité par Nihon Falcom, sorti à partir de 2001 sur Windows, PlayStation 2 et PlayStation Portable. Le jeu est réédité sur Steam en 2018 sous le titre Zwei: The Arges Adventure

Il a pour suite Zwei II.', 'https://fr.wikipedia.org/wiki/Zwei!!'),
  ('Q1277009', 'Psychonauts est un jeu de plates-formes développé par Double Fine Productions et édité par Majesco, sorti en 2005 sur Xbox, PlayStation 2, Microsoft Windows, et en 2007 sur le marketplace de la Xbox 360. Une version Linux est sortie en 2012, portée par icculus, et diffusée via l''Humble Indie Bundle V.

Premier jeu de Double Fine Productions, une compagnie créée en juillet 2000 par Tim Schafer, reconnu pour son travail sur de grands classiques du jeu d''aventure de LucasArts, dont le dernier est Grim Fandango.

Le jeu glane le BAFTA Games Awards 2006 de la meilleure distribution vocale[réf. nécessaire]. Il connait deux suites: le jeu en réalité virtuelle Psychonauts in the Rhombus of Ruin (en) (2017) et Psychonauts 2 (2021).', 'https://fr.wikipedia.org/wiki/Psychonauts'),
  ('Q1281317', 'Code Lyoko: Plongez vers l''infini (Code Lyoko Quest for Infinity) est un jeu vidéo développé par Neko Entertainment sorti en 2007 sur Wii, PlayStation 2 et PlayStation Portable, basé sur la série télévisée d''animation Code Lyoko.', 'https://fr.wikipedia.org/wiki/Code_Lyoko_:_Plongez_vers_l%27infini'),
  ('Q1283808', 'Fire Blade est un jeu vidéo de simulation de vol de combat développé par Kuju Entertainment et édité par Midway Games, sorti en 2002 sur GameCube, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Fire_Blade'),
  ('Q1299648', 'Mortal Kombat: Armageddon est un jeu vidéo de combat développé par Midway Games. Il est disponible depuis 2006 sur PlayStation 2 et Xbox, et en 2007 sur Wii.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat:_Armageddon'),
  ('Q1289512', '18 Wheeler: American Pro Trucker est un jeu vidéo de course sorti sur arcade en 2000 au Japon, puis converti sur Dreamcast, PlayStation 2 et GameCube.', 'https://fr.wikipedia.org/wiki/18_Wheeler:_American_Pro_Trucker'),
  ('Q683373', 'Sonic Riders est un jeu vidéo de course sur GameCube, PlayStation 2, PC et Xbox sorti le 17 mars 2006 en France. Le jeu a été développé par Sonic Team puis édité par Sega, il fait partie de la série Sonic. Le jeu a fait l''objet de deux suites intitulées Sonic Riders: Zero Gravity et Sonic Free Riders.', 'https://fr.wikipedia.org/wiki/Sonic_Riders'),
  ('Q683502', 'Little Busters! est un visual novel japonais développé par Key. Il est d''abord sorti en édition limitée tous publics le 27 juillet 2007 sur PC sous forme de DVD. Une édition normale, également tous publics, est sortie le 28 septembre 2007. Little Busters! est le sixième jeu de Key, après d''autres titres comme Kanon, Air ou Clannad. Bien que les deux premières éditions de Little Busters! soit évaluées « tous publics », elles comportent cependant des images suggestives sous forme de fan service. Une version adulte (eroge), nommée Little Busters! Ecstasy, est sortie le 25 juillet 2008, à l''inverse de Kanon et Air qui sont d''abord sortis sous forme d''eroge, et ont ensuite connu des versions tous publics dont le contenu adulte a été retiré. Le titre du jeu, Little Busters!, vient d''un groupe d''amis se faisant appeler les « Little Busters » dont le héros du jeu, Riki Naoe, fait partie depuis son enfance. En juin 2010, Key a sorti un eroge qui est un spin-off de Little Busters!, Kud Wafter, qui continue l''histoire de Kudryavka Noumi, une des héroïnes de Little Busters! et de Ecstasy.', 'https://fr.wikipedia.org/wiki/Little_Busters!'),
  ('Q683422', 'Dynasty Warriors: Gundam 2 est un jeu vidéo de type hack ''n'' slash développé par Koei et Omega Force, puis édité par Namco Bandai Games en décembre 2008 sur PlayStation 2, PlayStation 3 et Xbox 360.

Il fait partie des séries Dynasty Warriors et Mobile Suit Gundam.', 'https://fr.wikipedia.org/wiki/Dynasty_Warriors:_Gundam_2'),
  ('Q275950', 'Resident Evil 4, sorti au Japon sous le nom Biohazard 4, est un jeu vidéo de tir à la troisième personne de type survival horror, développé par Capcom Production Studio 4 et édité par l''entreprise japonaise Capcom.

L''histoire se déroule six ans après les événements de Resident Evil 2. Elle met en scène l''agent Leon S. Kennedy, envoyé en Espagne par le gouvernement américain pour sauver la fille du président des États-Unis, enlevée et retenue en otage par une mystérieuse secte.

Le jeu connaît une période de développement longue et mouvementée, durant laquelle plusieurs versions bêta sont annulées. Dans le cadre d''un accord entre Nintendo et Capcom, il sort finalement sur GameCube au début de l''année 2005, où il sera considéré comme l''un des titres majeurs de cette console. Il est ensuite porté sur PlayStation 2 à la fin de l''année, Windows et Wii en 2007, puis réédité successivement sur la plupart des plates-formes du marché, témoignant d''une longévité atypique et d''un succès constamment renouvelé.', 'https://fr.wikipedia.org/wiki/Resident_Evil_4'),
  ('Q254851', 'Harry Potter et l''Ordre du Phénix est un jeu vidéo d''action-aventure sorti en 2007 sur Game Boy Advance, Nintendo DS, PlayStation 2, PlayStation Portable, Windows, Xbox 360, PlayStation 3 et Nintendo Wii. Le jeu a été édité par Electronic Arts.

Le jeu coïncide avec la sortie du 5e film de la saga, également sorti en 2007.', 'https://fr.wikipedia.org/wiki/Harry_Potter_et_l%27Ordre_du_Ph%C3%A9nix_(jeu_vid%C3%A9o)'),
  ('Q264736', 'Tigre et Dragon (ou Crouching Tiger, Hidden Dragon en anglais) est un jeu vidéo d''action-aventure développé par Bergsala Lightweight et Genki et édité en 2003 par ESP et Ubisoft sur PlayStation 2, Xbox, Game Boy Advance. Le jeu est basé sur l''univers du film homonyme de Ang Lee.', 'https://fr.wikipedia.org/wiki/Tigre_et_Dragon_(jeu_vid%C3%A9o)'),
  ('Q1565986', 'Tony Hawk''s Downhill Jam est un jeu vidéo édité par Activision de la série Tony Hawk''s Pro Skater sorti sur Wii, Game Boy Advance DS et PlayStation 2. Ce jeu faisait partie des jeux de lancements de la Wii.

C''est un hommage au jeu vidéo favori de Tony Hawk: Skate or Die!, dont Downhill Jam reprend le concept[réf. nécessaire].', 'https://fr.wikipedia.org/wiki/Tony_Hawk%27s_Downhill_Jam'),
  ('Q1573435', 'ONI est un jeu vidéo d''action/aventure développé par Bungie Software et édité par Take-Two Interactive en 2001 sur Windows et PlayStation 2.', 'https://fr.wikipedia.org/wiki/Oni_(jeu_vid%C3%A9o)'),
  ('Q1563780', 'Obscure (stylisé ObsCure) est un jeu vidéo de type survival horror développé par Hydravision et édité par Microïds en 2004 sur PlayStation 2, Xbox et PC.

Le jeu se démarque de Silent Hill et Resident Evil pour son côté teen horror movie et la possibilité de jouer à deux joueurs, en contrôlant 5 personnages différents (qui peuvent mourir définitivement tout au long du jeu).

La musique, composée par Olivier Derivière et interprétée par le chœur d''enfants de l''Opéra de Paris, donne aussi une ambiance étrange au jeu. Le titre connait une suite, Obscure 2, sortie en 2007.', 'https://fr.wikipedia.org/wiki/Obscure_(jeu_vid%C3%A9o)'),
  ('Q1547059', 'Jak and Daxter: The Lost Frontier est un jeu vidéo développé par High Impact Games sorti fin 2009 sur PlayStation 2 et PlayStation Portable. Il s''inscrit dans la lignée de la série Jak and Daxter mais celui-ci n''est plus développé que partiellement par Naughty Dog car cette tâche a été confiée à High Impact Games. La première bande-annonce a été dévoilée le 3 juin 2009 durant l''E3 2009.', 'https://fr.wikipedia.org/wiki/Jak_and_Daxter:_The_Lost_Frontier'),
  ('Q878492', 'Tom Clancy''s Splinter Cell: Double Agent est un jeu vidéo d''infiltration édité par Ubisoft en 2006. C''est le quatrième épisode de la saga Splinter Cell. Le jeu est développé par Ubisoft Shanghai pour la Xbox 360, la PlayStation 3 et les PC dotés de Windows et par Ubisoft Montréal et Ubisoft Milan pour la Xbox, la PlayStation 2, la GameCube et la Wii.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Splinter_Cell:_Double_Agent'),
  ('Q880040', 'Black est un jeu vidéo de tir à la première personne, développé par Criterion Games et édité par Electronic Arts, sorti le 23 février 2006.

Criterion Software a voulu recréer l''ambiance des films d''action Hollywoodiens en utilisant un univers totalement destructible, accompagné d''effets spéciaux spectaculaires: les bâtiments partent en ruines, les objets explosent. Un gros travail a été accompli sur la modélisation des armes et l''éjection des douilles.

La version Xbox est compatible avec la console Xbox 360 et il est sorti une version téléchargeable sur le Xbox Live en échange de 1200 Microsoft Points.', 'https://fr.wikipedia.org/wiki/Black_(jeu_vid%C3%A9o)'),
  ('Q870874', 'Shining Wind est un jeu vidéo d''action RPG sorti sur PlayStation 2 en 2007 au Japon. Ce jeu a été développé conjointement par les studios Nex Entertainment et Amusement Vision puis publié par Sega. Il fait partie de la série Shining.', 'https://fr.wikipedia.org/wiki/Shining_Wind'),
  ('Q925229', 'NCAA Football 08 est un jeu vidéo de sport (football américain) édité par EA Sports, sorti en 2007 sur Xbox 360, PlayStation 3, Xbox et PlayStation 2.', 'https://fr.wikipedia.org/wiki/NCAA_Football_08'),
  ('Q915860', 'Tomb Raider: Underworld est un jeu vidéo d’action-aventure développé par Crystal Dynamics et édité par Eidos Interactive, sorti sur Windows, Xbox 360, PlayStation 3, Wii et Nintendo DS le 21 novembre 2008. Une version PlayStation 2 est sorti le 23 janvier 2009. Seules les versions PlayStation 2 et Wii ont été développées par une société tierce du nom de Buzz Monkey Software. Une version sur téléphone mobile est sorti le 3 décembre 2008. Et une version Mac OS X est sorti le 14 juin 2012.

Il s’agit du huitième épisode de la série Tomb Raider, et du troisième développé par Crystal Dynamics.', 'https://fr.wikipedia.org/wiki/Tomb_Raider:_Underworld'),
  ('Q922110', 'Tomoyo After: It''s a Wonderful Life est un visual novel eroge japonais développé par Key et sorti le 25 novembre 2005 sur PC sous forme de DVD. Un portage sur PlayStation 2 sans le contenu réservé aux adultes a été réalisé par Prototype le 25 janvier 2007 sous le titre Tomoyo After: It''s a Wonderful Life CS Edition (« CS » signifiant consumer software, qu''on peut traduire par « logiciel pour le public »). Prototype a également sorti une version tous publics jouable sur téléphone portable FOMA le 2 juin 2008, et une version PSP basée sur la CS Edition le 19 mars 2009. Le gameplay de Tomoyo After suit un ensemble de scénarios prédéterminés contenant des interactions entre les personnages, et met l''accent sur l''attirance pour le personnage féminin principal, Tomoyo Sakagami. L’histoire suit la vie de Tomoya Okazaki, un jeune homme qui vient de quitter le lycée, et de Tomoyo, qui commencent à avoir une relation amoureuse.', 'https://fr.wikipedia.org/wiki/Tomoyo_After:_It%27s_a_Wonderful_Life'),
  ('Q376217', 'Driver Parallel Lines est un jeu vidéo de course-poursuites développé par Reflections Interactive et publié par Atari Inc. en 2006 sur PlayStation 2, Windows et Xbox. Le jeu est sorti sur Wii en 2007.

C''est le quatrième épisode de la série Driver, débuté sur PlayStation et Windows.

Annoncé en mai 2005 à l''E3, Driver: Parallel Lines tente de renouer ses liens avec les joueurs après les nombreuses critiques négatives à l''encontre de DRIV3R. Ce quatrième épisode a reçu un accueil critique plutôt mitigé positivement.', 'https://fr.wikipedia.org/wiki/Driver:_Parallel_Lines'),
  ('Q853344', 'Manhunt est un jeu vidéo d''infiltration et d''action de type survival horror développé par Rockstar North et édité en 2003 par Take2 Interactive sur PlayStation 2. Le jeu est sorti en 2004 sur Xbox et sous Windows.

Classifié « Jeunes Adultes » par l''ESRB et interdit aux moins de 18 ans, le titre fait parler de lui notamment à cause de sa violence.

Une suite, Manhunt 2, est sortie en 2007 en Amérique du Nord et en 2008 en Europe sur PlayStation 2, Wii et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Manhunt_(jeu_vid%C3%A9o)'),
  ('Q850587', 'Vampire Night est un jeu vidéo de tir au pistolet optique développé par Wow Entertainment et édité par Namco, sorti en 2000 sur borne d''arcade et en 2001 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Vampire_Night'),
  ('Q853941', 'Test Drive Unlimited (ou TDU) est un jeu vidéo de course sorti sur plusieurs plates-formes entre fin 2006 et mi-2007. Ce nouvel opus de Test Drive est très différent vis-à-vis de ses nombreux prédécesseurs. Atari Inc. et Eden Games offrent 1 000 miles (1 600 km) de routes praticables sur l''île d''Oahu, île principale de l''archipel d''Hawaï, qui abrite notamment Honolulu, la capitale de cet État américain.', 'https://fr.wikipedia.org/wiki/Test_Drive_Unlimited'),
  ('Q11680710', 'Chicken Little est un jeu vidéo d''action-aventure développé par Avalanche Software et Artificial Mind and Movement, édité par Buena Vista Games et sorti en 2005 sur GameCube, PlayStation 2, Xbox, Windows et Game Boy Advance. Il est adapté du film du même nom.', 'https://fr.wikipedia.org/wiki/Chicken_Little_(jeu_vid%C3%A9o)'),
  ('Q11704395', 'Billy et Mandy, aventuriers de l''au-delà (The Grim Adventures of Billy & Mandy) est un jeu vidéo de combat développé par High Voltage Software et édité par Midway Games, sorti en 2006 sur GameCube, Wii, PlayStation 2 et Game Boy Advance.

Il est adapté de la série du même nom.', 'https://fr.wikipedia.org/wiki/Billy_et_Mandy,_aventuriers_de_l%27au-del%C3%A0_(jeu_vid%C3%A9o)'),
  ('Q11690290', 'Major League Baseball 2K10 ou MLB 2K10 est un jeu vidéo de baseball sous licence MLB publié par 2K Sports. MLB 2K10 est disponible sur Windows, Xbox 360, PlayStation 3, PlayStation 2, PlayStation Portable, Wii et Nintendo DS. Le jeu est sorti en mars 2010 aux États-Unis.', 'https://fr.wikipedia.org/wiki/Major_League_Baseball_2K10'),
  ('Q11883844', 'NHL 2K8 est un jeu vidéo de hockey sur glace développé par Visual Concepts et édité par 2K Sports. Le jeu sort en 2007 sur PlayStation 2, Xbox 360 et PlayStation 3.', 'https://fr.wikipedia.org/wiki/NHL_2K8'),
  ('Q1487484', 'Gun est un jeu vidéo d''action développé par Neversoft et édité par Activision en novembre 2005 sur PlayStation 2, GameCube, Windows, Xbox et Xbox 360. Le jeu a été édité sur PlayStation Portable en 2006. L''action se déroule au début des années 1880 au Far West, dans le contexte de la Conquête de l''Ouest. Le jeu est en distribution depuis octobre 2006 sur la plate-forme de téléchargement Steam.', 'https://fr.wikipedia.org/wiki/Gun_(jeu_vid%C3%A9o)'),
  ('Q1457450', 'Grandia II est un jeu vidéo de rôle développé par Game Arts et édité par Ubisoft sur Dreamcast en 2000. Il est adapté sur PlayStation 2 et Windows en 2002. Suite de Grandia, il n''en reprend cependant ni l''histoire ni les personnages. Son système de combat original, sa réalisation soignée et ses personnages attachants en font l''un des jeux de rôle les plus appréciés de la Dreamcast avec Skies of Arcadia.', 'https://fr.wikipedia.org/wiki/Grandia_II'),
  ('Q1476611', 'True Crime: New York City est un jeu vidéo de tir en vue à la troisième personne dans un monde ouvert développé par Luxoflux et édité par Activision sur Xbox, PlayStation 2 et GameCube en 2005, et pour Windows en 2006.

Il est la suite du jeu vidéo True Crime: Streets of LA.', 'https://fr.wikipedia.org/wiki/True_Crime:_New_York_City'),
  ('Q1527294', 'Army Men: Major Malfunction est un jeu vidéo de tir à la troisième personne développé par Global Star Software et édité par Team17, sorti en 2006 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Army_Men:_Major_Malfunction'),
  ('Q1535956', 'Knights of the Temple: Infernal Crusade est un jeu vidéo d''action-aventure développé par Starbreeze Studios et édité par TDK Mediactive, sorti en 2004 sur Windows, GameCube, PlayStation 2 et Xbox.

Il a pour suite Knights of the Temple II.', 'https://fr.wikipedia.org/wiki/Knights_of_the_Temple:_Infernal_Crusade'),
  ('Q1515687', 'Total Overdose est un jeu vidéo de tir à la troisième personne édité par Eidos Interactive et développé par Deadline Games sorti sur PC, PlayStation 2 et Xbox. Il a connu une adaptation sur PSP nommée Chili con Carnage.', 'https://fr.wikipedia.org/wiki/Total_Overdose'),
  ('Q1516526', 'Rule of Rose est un jeu vidéo de type survival horror développé par le studio japonais Punchline, sorti en 2006 sur la console PlayStation 2. Son intrigue se déroule dans l''Angleterre des années 1930 et tourne autour d''une jeune fille de dix-neuf ans nommée Jennifer, qui se fait piéger dans un monde dirigé par des jeunes filles qui ont érigé une hiérarchie de classes appelée les Red Crayon Aristocrats.

Ce jeu a été comparé à d''autres survival horror, comme Silent Hill et Haunting Ground, à cause de l''horreur psychologique employée tout au long du jeu, et parce que le personnage principal est accompagné par un chien. Une polémique autour de son contenu a rendu les éditeurs frileux dans certains pays, où pour certains le jeu n''a pas été publié. Certaines scènes de violence ont été censurées en Europe contrairement à la version Japonaise.', 'https://fr.wikipedia.org/wiki/Rule_of_Rose'),
  ('Q1538087', 'Just Cause est un jeu vidéo de type GTA-like développé par Avalanche Studios et édité par Eidos Interactive, sorti le 22 septembre 2006 sur PC, PlayStation 2, Xbox et Xbox 360. La suite du jeu, Just Cause 2, est sortie le 26 mars 2010.', 'https://fr.wikipedia.org/wiki/Just_Cause_(jeu_vid%C3%A9o)'),
  ('Q1537200', 'Mercenaries: Playground of Destruction est un jeu vidéo de tir à la troisième personne sorti en 2005 sur PlayStation 2 et Xbox. Il a été développé par Pandemic Studios et édité par LucasArts.

Mercenaries a connu une suite, Mercenaries 2: L''Enfer des favelas, sortie en 2008 sur PC, PlayStation 2, PlayStation 3 et Xbox 360.', 'https://fr.wikipedia.org/wiki/Mercenaries:_Playground_of_Destruction'),
  ('Q282008', 'TimeSplitters 2 est un jeu vidéo de type FPS développé par le studio Free Radical Design, dont les principaux membres fondateurs ont participé à la réalisation de GoldenEye 007, et édité par Eidos Interactive en 2002. Commercialisé sur GameCube, PlayStation 2 et Xbox, cet épisode a apporté ses lettres de noblesse à une série entamée avec TimeSplitters en 2000, au lancement de la PlayStation 2.', 'https://fr.wikipedia.org/wiki/TimeSplitters_2'),
  ('Q278564', 'Colin McRae Rally 3 est un jeu vidéo de course de rallye, développé et édité par Codemasters, sorti en Europe le 25 octobre 2002 sur consoles PlayStation 2 et Xbox, et le 13 juin 2003 sur PC. Il fait partie de la série Colin McRae Rally.', 'https://fr.wikipedia.org/wiki/Colin_McRae_Rally_3'),
  ('Q279744', 'Half-Life est un jeu de tir à la première personne, développé par Valve Corporation et publié par Sierra le 19 novembre 1998 pour Microsoft Windows. Il est ensuite publié sur la plate-forme Steam depuis 2003 et disponible depuis janvier 2013 pour Mac et Linux. Le jeu utilise une version profondément modifiée du Quake engine, appelée GoldSrc. Le jeu a également été porté sur PlayStation 2 et publié le 15 novembre 2001.

Dans ce premier épisode de la saga Half-Life, le joueur incarne le docteur Gordon Freeman, un théoricien récemment diplômé qui, après des expériences de téléportation qui ont mal tourné, doit se battre contre les créatures extraterrestres accidentellement apparues dans le complexe puis contre un commando de militaires envoyés par le gouvernement pour nettoyer la zone.', 'https://fr.wikipedia.org/wiki/Half-Life_(jeu_vid%C3%A9o)'),
  ('Q729162', 'Alias est un jeu vidéo d''action-aventure basé sur la série télévisée américaine d''espionnage Alias. Développé par Acclaim Cheltenham, le jeu a été édité en 2004 par Acclaim Entertainment sur PlayStation 2, Windows et Xbox.', 'https://fr.wikipedia.org/wiki/Alias_(jeu_vid%C3%A9o)'),
  ('Q726190', 'Need for Speed: Underground 2, abrégé en NFSU2, est un jeu vidéo de course développé par EA Black Box et édité par Electronic Arts. Ce jeu, sorti en 2004, fait partie de la série des Need for Speed et est la suite du jeu similaire Need for Speed: Underground. Il est disponible sur GameCube, PlayStation 2, Xbox, Nintendo DS, Game Boy Advance et PC.

Une version différente est sortie en 2005 sur PlayStation Portable titrée Need for Speed: Underground Rivals.', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_Underground_2'),
  ('Q383700', 'Marvel vs. Capcom 2: New Age of Heroes est un jeu vidéo de combat développé par Capcom Production Studio 1 et édité par Capcom en 2000 sur système d''arcade Naomi. Il est porté sur console de jeux vidéo, la même année sur Dreamcast, en 2002 sur PlayStation 2 et Xbox, en 2009 sur les plates-formes de téléchargement PlayStation Network et Xbox Live Arcade.

Il s''agit du 4e épisode de la série Marvel vs. Capcom. Cette série est un crossover des environnements de jeux vidéo de la société Capcom (principalement de l''univers Street Fighter) et de l''univers Marvel Comics.', 'https://fr.wikipedia.org/wiki/Marvel_vs._Capcom_2:_New_Age_of_Heroes'),
  ('Q385184', 'Ōkami est un jeu vidéo d''action-aventure développé par Clover Studio et édité par Capcom en 2006 sur PlayStation 2. L''adaptation sur la console Wii, développée par Ready at Dawn, est sortie le 12 juin 2008. Un jeu similaire sur Nintendo DS appelé Ōkamiden est sorti début 2011.

Un portage en HD développé par HexaDrive sur PS3 compatible PS Move est sorti le 30 octobre 2012 en Amérique du Nord et le 31 octobre en Europe uniquement sur le PlayStation Network, au Japon le jeu sort le 1er novembre 2012 en version physique et digitale, gratuit pour les abonnés PlayStation Plus jusqu''au 31 mai 2013. Cette version HD subira un remake 5 ans plus tard sur PlayStation 4, Xbox One et Windows le 12 décembre 2017. Enfin, une version Nintendo Switch sort le 9 août 2018.', 'https://fr.wikipedia.org/wiki/%C5%8Ckami'),
  ('Q388109', 'Legend of Kay est un jeu vidéo d''action-aventure sorti sur PlayStation 2 en 2005.', 'https://fr.wikipedia.org/wiki/Legend_of_Kay'),
  ('Q5084400', 'Charlie''s Angels: Les Anges se déchaînent ! (Charlie''s Angels), est un jeu vidéo de genre beat ''em up développé par Neko Entertainment, édité par Ubisoft, et sorti partout dans le monde sur GameCube et uniquement en Europe sur PlayStation 2.

Il s''agit d''une adaptation de la franchise Drôles de dames, et plus précisément des deux premiers films faisant suite à la série télévisée originale. Se déroulant entre le premier et le deuxième film, il met en scène les détectives privés Alex Munday (Lucy Liu), Dylan Sanders (Drew Barrymore) et Natalie Cook (Cameron Diaz) alors qu''elles tentent de résoudre le mystère d''une série de disparitions de monuments nationaux. Liu, Barrymore et Diaz assurent le doublage de leurs personnages dans la version originale.', 'https://fr.wikipedia.org/wiki/Charlie%27s_Angels_:_Les_Anges_se_d%C3%A9cha%C3%AEnent_!_(jeu_vid%C3%A9o)'),
  ('Q5049067', 'Casper: Spirit Dimensions est un jeu vidéo d''action-aventure développé par Lucky Chicken Games et édité par TDK Mediactive Inc., sorti en 2001 sur GameCube et PlayStation 2, mettant en scène Casper le gentil fantôme.', 'https://fr.wikipedia.org/wiki/Casper:_Spirit_Dimensions'),
  ('Q5070055', 'Champions: Return to Arms est un jeu vidéo de type action-RPG développé par Snowblind Studios et édité par Sony Online Entertainment, sorti en 2005 sur PlayStation 2.

Il fait suite à Champions of Norrath.', 'https://fr.wikipedia.org/wiki/Champions:_Return_to_Arms'),
  ('Q5054224', 'Catwoman est un jeu vidéo d''action-aventure développé et édité par Electronic Arts, sorti en 2004 sur PlayStation 2, GameCube, Xbox et Windows. Il a été adapté sur Game Boy Advance par Magic Pockets. Il est basé sur le film du même nom d''après le personnage de comics édité par DC Comics.', 'https://fr.wikipedia.org/wiki/Catwoman_(jeu_vid%C3%A9o,_2004)'),
  ('Q5085755', 'Charlie et la Chocolaterie (Charlie and the Chocolate Factory) est un jeu vidéo d''action-aventure développé par High Voltage Software et édité par Global Star Software, sorti en 2005 sur Windows, GameCube, PlayStation 2, Xbox et Game Boy Advance.

Il s''agit de l''adaptation du film du même nom, sorti la même année et réalisé par Tim Burton.', 'https://fr.wikipedia.org/wiki/Charlie_et_la_Chocolaterie_(jeu_vid%C3%A9o,_2005)'),
  ('Q390004', 'The King of Fighters 2001 est un jeu de combat produit par Eolith pour la Neo-Geo. Il s''agit du huitième jeu de la série The King of Fighters, de la troisième et dernière partie de l''arc narratif "NESTS Chronicles" et du premier jeu produit après la fermeture du SNK original. Leu jeu a été produit par la Corée du Sud basée à Eolith et développé par Eolith et BrezzaSoft, une société formée par d''anciens employés de SNK. Pour cette raison, le logo SNK est affiché à l''ouverture, mais l''équipe de développement de SNK n''est pas du tout impliquée dans la production du jeu lui-même, à l''exception de la bande sonore. En raison de l''afflux de capitaux coréens, son influence se voit dans les personnages participants. Le jeu a été porté sur Sega Dreamcast au Japon uniquement et sur PlayStation 2. La version autonome PlayStation 2 est sortie en Amérique du Nord et en Europe dans un pack deux-en-un avec le jeu précédent de la série, The King of Fighters 2000. La version originale de Neo Geo et la version Sega Dreamcast ont été incluses dans The King of Fighters NESTS Hen compilation sortie pour la PlayStation 2 au Japon.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_2001'),
  ('Q405497', 'Air est un visual novel de type eroge japonais développé par Key et publié le 8 septembre 2000 pour les ordinateurs Windows. Key a par la suite édité des versions excluant le contenu érotique, permettant ainsi un portage vers Dreamcast, PlayStation 2, PlayStation Portable et PlayStation Vita. Le jeu suit la vie de Yukito Kunisaki, un forain itinérant à la recherche de la « fille dans le ciel ». Il arrive dans une ville balnéaire tranquille où il rencontre trois filles, dont l''une d''elles est la clé de la fin de son voyage.

Le gameplay d''Air est non-linéaire et offre des scénarios prédéterminés avec des moments d''interactions où le joueur est à la place des trois personnages principaux féminins. Le jeu est divisé est trois segments (« Rêve », « Été » et « Air ») qui servent de phases différentes pour l''histoire globale. Le jeu s''est placé dans les meilleures ventes des jeux pour PC vendus au Japon au moment de sa sortie, puis est présent plusieurs fois dans le top 50 national des ventes. Air s''est vendu à plus de 300 000 exemplaires sur plusieurs plateformes.', 'https://fr.wikipedia.org/wiki/Air_(univers_de_fiction)'),
  ('Q392778', '007: Espion pour cible (007: Agent Under Fire) est un jeu vidéo de tir à la première personne prenant place dans l''univers de James Bond. D''abord sorti sur PlayStation 2 en 2001, il est ensuite porté sur GameCube et Xbox en 2002.', 'https://fr.wikipedia.org/wiki/007_:_Espion_pour_cible'),
  ('Q1619582', 'Red Faction II est la suite de Red Faction, et se déroule cette fois-ci sur Terre, et non plus sur Mars. Le jeu suit l''histoire d''un groupe de Super-soldats dont fait partie le joueur, nommé Alias. Ces soldats ont été physiquement améliorés par une technologie secrète, créée sur Mars. Red Faction II a été développé par Volition, Inc. et édité par THQ en novembre 2002 pour PS2 puis en juin 2003 sur PC, GameCube et Xbox.

Le jeu incorpore des améliorations par rapport à l''opus précédent: possibilité d''utiliser deux armes à la fois, exagération de la puissance des armes de démolition et meilleur débit de trame. Cependant, des points négatifs sont également présents: les niveaux ne sont plus inter-connectés, il n''est plus possible de déplacer les corps et les armes ne sont plus regroupées – ce qui tend à rapprocher le jeu de l''arcade. De plus, le Geo-Mod est encore moins exploité dans les villes terriennes de Red Faction II que dans les sous-sols martiens du premier opus. Globalement, le jeu a été mal reçu par les critiques[réf. nécessaire].', 'https://fr.wikipedia.org/wiki/Red_Faction_II'),
  ('Q1627493', 'Metal Slug est un jeu de tir en vue à la troisième personne développé et édité par SNK Playmore et sorti en 2006 sur PlayStation 2 uniquement au Japon. Il est le premier jeu de la série Metal Slug en trois dimensions', 'https://fr.wikipedia.org/wiki/Metal_Slug_(jeu_vid%C3%A9o,_2006)'),
  ('Q1607833', 'Street Fighter EX 3 est un jeu vidéo de combat édité par Capcom et développé en collaboration avec Arika, sorti le 4 mars 2000 au Japon, puis le 26 octobre en Europe et le 2 mars 2001 aux États-Unis. Contrairement aux autres titres de la franchise, le titre sort exclusivement sur PlayStation 2, sur laquelle il sert de titre de lancement.

Street Fighter EX 3 est le seul et unique opus de la franchise Street Fighter à ne jamais être sorti sur bornes d''arcade.', 'https://fr.wikipedia.org/wiki/Street_Fighter_EX_3'),
  ('Q1608476', 'Yakuza est un jeu vidéo développé par Amusement Vision et édité par Sega, sorti en 2005 sur la console PlayStation 2.

Produit par Toshihiro Nagoshi, dirigé par Ryuta Ueda et scénarisé par l''écrivain Hase Seishū, Yakuza est jeu d''action-aventure qui prend pour cadre le monde de la mafia japonaise. Il est basé sur l''exploration d''un quartier populaire de Tokyo (inspiré du quartier Kabukichō) et sur des combats de rue. Réalisé avec un faible budget, le jeu est un succès critique et commercial, en particulier au Japon. Il a donné suite à cinq nouveaux épisodes, un préquel, cinq spin-offs et à une adaptation cinématographique, réalisée par Takashi Miike.', 'https://fr.wikipedia.org/wiki/Yakuza_(jeu_vid%C3%A9o)'),
  ('Q1605942', 'War of the Monsters est un jeu vidéo de combat en 3D pour la PlayStation 2 développé par Incognito Entertainment et édité par Sony Computer Entertainment. Le jeu est sorti le 14 janvier 2003 en Amérique du Nord, le 17 avril 2003 en Europe et le 25 mars 2004 au Japon', 'https://fr.wikipedia.org/wiki/War_of_the_Monsters'),
  ('Q863486', 'Britney''s Dance Beat ou parfois Britney Spears Dance Beat est un jeu de danse de THQ sorti sur PlayStation 2, Game Boy Advance et PC en 2002. Le joueur choisit un personnage puis une option. Si le joueur réussit l''audition, il fera une chorégraphie avec Britney Spears sur une de ses chansons, ou un duel avec un second joueur.', 'https://fr.wikipedia.org/wiki/Britney%27s_Dance_Beat'),
  ('Q865237', 'Brothers in Arms: Earned in Blood est la suite immédiate de Brothers in Arms: Road to Hill 30. Ce jeu utilise le moteur Unreal Engine 2.5.

Le jeu a été adapté sur téléphone mobile par Gameloft.', 'https://fr.wikipedia.org/wiki/Brothers_in_Arms:_Earned_in_Blood'),
  ('Q866149', 'Remember 11: The Age of Infinity est un jeu vidéo de type visual novel développé et édité par KID, sorti en 2004 sur Windows, PlayStation 2, PlayStation Portable, iOS et Android.', 'https://fr.wikipedia.org/wiki/Remember_11:_The_Age_of_Infinity'),
  ('Q4895987', 'Ford Racing 3 est un jeu vidéo de course édité par Empire Interactive et 2 K Games. Il s’agit du troisième jeu de la série Ford Racing, et sont sortis en Europe en octobre 2004, pour Microsoft Windows, PlayStation 2 et Xbox. Aux États-Unis, le jeu est sorti sur les mêmes plateformes l’année suivante, suivi de sorties plus tard cette année-là pour la Game Boy Advance et la Nintendo DS. Visual Impact Productions a développé les versions GBA et DS, tandis que Razorworks a développé les autres versions. Le jeu a reçu des critiques mitigées, qui comprenaient des critiques de sa bande originale.', 'https://fr.wikipedia.org/wiki/Ford_Racing_3'),
  ('Q1788165', 'Spy Hunter est un jeu vidéo de type combat motorisé développé par la société américaine Bally Midway et commercialisé en 1983 sur borne d''arcade. Il a été adapté sur divers supports familiaux.', 'https://fr.wikipedia.org/wiki/Spy_Hunter_(jeu_vid%C3%A9o,_1983)');

insert into import_summary (wikidata_id, summary, source) values
  ('Q1778959', 'Pro Evolution Soccer 4 (Winning Eleven 8, abrégé PES 4) est un jeu vidéo de football, sorti en 2004 sur PC, PlayStation 2 et Xbox.

Développé et édité par Konami, ce jeu fait partie de la série des "Pro Evolution Soccer" adaptée de "Winning Eleven 8" (version Japonaise du jeu) et de "World Soccer Winning Eleven 8" (version Américaine).', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_4'),
  ('Q1779348', 'La Légende de Spyro: Naissance d''un dragon est un jeu vidéo de plates-formes développé par Étranges Libellules et édité par Sierra Entertainment, sorti sur Xbox 360, PlayStation 3, Wii, PlayStation 2 et Nintendo DS en 2008. Il s''agit du troisième et dernier épisode de la trilogie The Legend of Spyro.

Contrairement aux deux précédents jeux qui ont été des échec, celui-ci a été un succès.', 'https://fr.wikipedia.org/wiki/La_L%C3%A9gende_de_Spyro_:_Naissance_d%27un_dragon'),
  ('Q1784103', 'Jak and Daxter: The Precursor Legacy est un jeu vidéo de plates-formes, développé par Naughty Dog et édité par Sony Computer Entertainment en 2001 sur PlayStation 2. C''est le premier épisode de la série Jak and Daxter.

En 2012, le jeu a été remastérisé en haute définition et porté dans une compilation disponible sur PlayStation 3 puis en 2013 sur PlayStation Vita: The Jak and Daxter Trilogy. Le jeu est ensuite porté sur Playstation 4, dans un premier temps seul, le 27 août 2017 mais également dans un pack comprenant tous les jeux de la série le 6 décembre 2017.', 'https://fr.wikipedia.org/wiki/Jak_and_Daxter:_The_Precursor_Legacy'),
  ('Q1783005', 'Bons Baisers de Russie (James Bond 007: From Russia with Love en version originale) est un jeu vidéo de tir en vue à la troisième personne et comprenant des séquences de course. Sorti en 2005, il est développé par Electronic Arts, édité par EA Redwood Shores et pour la version PSP en collaboration avec Rebellion Developments.

Mettant en vedette l''agent secret d''Ian Fleming, James Bond, le jeu est inspiré du roman de 1957 et sur le film de 1963 du même nom. Le jeu suit le scénario du livre et du film, avec toutefois l''ajout de nouvelles scènes pour ajouter de l''action. Dans le jeu, le personnage est par ailleurs équipé de gadgets issus de films suivants comme le jet pack d''Opération Tonnerre ou l''Aston Martin DB5 qui apparaît la première fois dans Goldfinger.', 'https://fr.wikipedia.org/wiki/Bons_Baisers_de_Russie_(jeu_vid%C3%A9o)'),
  ('Q1584849', 'Sly 2: Association de voleurs (titre original: Sly 2: Band of Thieves) est un jeu vidéo de plates-formes développé par Sucker Punch Productions et édité par Sony Computer Entertainment sur PlayStation 2. Il constitue le deuxième volet de la série Sly Cooper et fait suite à Sly Raccoon, publié en 2002. Il est sorti le 14 septembre 2004 en Amérique du Nord, le 29 octobre 2004 en Europe, le 24 février 2005 en Corée du Sud et le 16 juin 2005 au Japon.

Le joueur incarne le voleur Sly Cooper, un raton laveur anthropomorphe, mais aussi les autres membres de son gang, composé de Bentley, une tortue, et de Murray, un hippopotame. Les trois héros tentent de voler les morceaux de Clockwerk, un hibou mécanique multiséculaire, principal antagoniste du premier opus, détenus par les membres d''une organisation criminelle internationale, le gang de Klaww. Ponctuellement aidés par l''Inspecteur Carmelita Montoya Fox et le sergent Neyla, ils sillonnent ainsi Paris, l''Inde, Prague et le Grand Nord canadien, jusqu''à atteindre le ballon dirigeable d''Arpeggio, le chef du gang de Klaww, qui parvient à réassembler Clockwerk. Neyla, en réalité la protégée d''Arpeggio, trahit ce dernier et fusionne avec Clockwerk pour donner naissance à Clockeyla, l''antagoniste final du jeu.', 'https://fr.wikipedia.org/wiki/Sly_2_:_Association_de_voleurs'),
  ('Q1582779', 'Resident Evil: Dead Aim, connu au Japon sous le nom Gun Survivor 4: Biohazard - Heroes Never Die, est un jeu vidéo de tir au pistolet développé par Capcom Production Studio 3 et édité par Capcom en 2003 sur PlayStation 2. Le jeu fait partie de la série Resident Evil.

Il met en scène des agents secrets respectivement du gouvernement américain et du gouvernement chinois qui enquêtent sur la transformation en zombies de tous les passagers d''un navire de croisière appartenant à Umbrella où des choses pas très nettes comme des présentations de monstres ont été faites. La progression se fait en deux temps: la première phase se déroule sur le bateau où les deux agents, Bruce et Fangling cherchent à découvrir qui est à l''origine du drame puis dans une base secrète d''Umbrella où ils tentent d''empêcher Morpheus, responsable des événements, de lancer des missiles contenant le virus T sur l''Amérique et la Chine.', 'https://fr.wikipedia.org/wiki/Resident_Evil:_Dead_Aim'),
  ('Q16266983', 'Spy Hunter: Nowhere to Run (stylisé SpyHunter: Nowhere to Run) est un jeu vidéo de combat motorisé développé par Terminal Reality et édité par Midway Games, sorti en 2006 sur PlayStation 2 et Xbox.

Le jeu aurait dû être accompagné d''un film du même nom mais dont la production a été stoppée au stade du développement. L''acteur Dwayne Johnson donne ses traits au héros du jeu, Alex Decker, et aurait dû être le héros du film.', 'https://fr.wikipedia.org/wiki/Spy_Hunter:_Nowhere_to_Run'),
  ('Q16682759', 'Virtua Fighter 4 Evolution (ou Virtua Fighter 4 Evo) est un jeu de combat en 3D développé par Sega-AM2 et sorti en 2002 sur borne d''arcade et en 2003 sur PlayStation 2. Il fait partie de la série Virtua Fighter.', 'https://fr.wikipedia.org/wiki/Virtua_Fighter_4_Evolution'),
  ('Q16267601', 'WRC II Extreme est un jeu vidéo de course de rallye développé par Evolution Studios et édité par SCEE, sorti en 2002 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/WRC_II_Extreme'),
  ('Q16622867', 'WRC 4 est un jeu vidéo de course de rallye développé par Evolution Studios et édité par SCEE, sorti en 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/WRC_4'),
  ('Q16539021', 'Chessmaster est un jeu de simulation d''échecs développé et édité par Ubisoft en 2002 sur Game Boy Advance et PlayStation 2. Le jeu propose 16 niveaux de difficulté permettant d''affronter un très grand nombre d''adversaires différents adaptés à tous les styles de jeu. Le joueur peut bénéficier d''une aide et de conseils. Le mode 2 joueurs permet affronter un adversaire réel au moyen d''un câble.', 'https://fr.wikipedia.org/wiki/Chessmaster_(jeu_vid%C3%A9o,_2002)'),
  ('Q1750461', 'Shadow Man: 2econd Coming est un jeu vidéo d’action-aventure sorti uniquement sur PlayStation 2 en mars 2002. Il est la suite du jeu Shadow Man. Il est édité et développé par Acclaim.', 'https://fr.wikipedia.org/wiki/Shadow_Man:_2econd_Coming'),
  ('Q1725580', 'The Getaway: Black Monday est un jeu vidéo d''action GTA-like, développé par Team Soho et édité par Sony, sorti le 17 novembre 2004 en Europe sur PlayStation 2. C’est le second épisode de la série The Getaway.', 'https://fr.wikipedia.org/wiki/The_Getaway:_Black_Monday'),
  ('Q1711572', '''''Juiced est un jeu vidéo de course automobile sorti en 2005 sur PlayStation 2, Xbox et PC. Il a été édité par THQ et développé par Juice Games.', 'https://fr.wikipedia.org/wiki/Juiced'),
  ('Q1709153', '7 Sins est un jeu vidéo de simulation de vie développé par Monte Cristo Multimédia, sorti en mai 2005 sur PC et PlayStation 2. Il sort le 13 mai en France où il est déconseillé aux moins de 16 ans alors qu’il est interdit aux États-Unis en raison de son caractère érotique[réf. nécessaire]. Il traite des sept péchés capitaux: l''avarice, la colère, l''envie, la gourmandise, l''orgueil, la paresse et la luxure. Le jeu prend place dans la ville fictive d’Apple City où le joueur incarne un homme qui cherche à gagner de l’argent, et à gravir l’échelle sociale en séduisant des femmes. 7 Sins comporte, de plus, des mini-jeux.', 'https://fr.wikipedia.org/wiki/7_Sins'),
  ('Q1324541', 'Delta Force: Black Hawk Down est un jeu de tir à la première personne, un FPS développé par Novalogic sorti en 2004. Le jeu se déroule durant la période où les forces américaines étaient en Somalie Le jeu compte une quinzaine de missions principales, inspiré des interventions de la 10e division de montagne, du 75th Ranger Regiment et de la Delta Force lors de l’opération Restore Hope in Somalia et l''Opération Gothic Serpent. Il y a une 16e mission qui est une mission bonus.', 'https://fr.wikipedia.org/wiki/Delta_Force:_Black_Hawk_Down'),
  ('Q1326987', 'Transformers, le jeu (Transformers: The Game) est un jeu vidéo de tir à la troisième personne et course édité par Activision en 2007 sur une multitude de plates-formes. Savage Entertainment s''est chargé du développement sur PlayStation Portable, et Vicarious Visions a développé la version Nintendo DS. Cette dernière est sortie en deux jeux différents: l''un suit l''histoire du côté des gentils, Autobots, et l''autre du côté des méchants, Decepticons.

Le jeu est basé sur le film Transformers sorti la même année.', 'https://fr.wikipedia.org/wiki/Transformers,_le_jeu'),
  ('Q4353964', 'Salt Lake 2002 est un jeu vidéo de sport développé par Attention to Detail et édité par Eidos Interactive, sorti en 2002 sur Windows, PlayStation 2 et Game Boy Advance.

Il s''agit du jeu officiel des Jeux olympiques d''hiver de 2002.', 'https://fr.wikipedia.org/wiki/Salt_Lake_2002_(jeu_vid%C3%A9o)'),
  ('Q4354676', 'Freekstyle est un jeu vidéo de course de moto-cross édité par Electronic Arts, sorti en 2002 sur PlayStation 2, GameCube et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Freekstyle'),
  ('Q4355812', 'Winnie l''ourson: À la recherche des souvenirs oubliés (Winnie the Pooh''s Rumbly Tumbly Adventure) est un jeu vidéo d''action-aventure développé par Phoenix Studio et édité par Ubisoft, sorti en 2005 sur GameCube, PlayStation 2 et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Winnie_l%27ourson_:_%C3%80_la_recherche_des_souvenirs_oubli%C3%A9s'),
  ('Q1684851', 'NBA 2K11 est un jeu vidéo de basket-ball développé par Visual Concepts et édité par 2K Sports sorti en octobre 2010.

Il est disponible en France depuis le 8 octobre 2010 sur PlayStation 3, Xbox 360, PlayStation 2, Wii, PlayStation Portable et PC.

C''est le douzième épisode de la franchise 2K et est le principal concurrent de NBA Elite.

Avec la licence officielle de la NBA vous pouvez choisir parmi les 30 équipes de la ligue et évoluer avec les plus grands joueurs tels LeBron James ou Kobe Bryant.

Michael Jordan figure sur la couverture de cette édition. NBA 2K11 propose une série de 10 défis qui, une fois réussis, débloquent un nouveau mode « MJ: Une légende en action ».', 'https://fr.wikipedia.org/wiki/NBA_2K11'),
  ('Q1702746', 'Constantine est un jeu vidéo d''action-aventure développé par Bits Studios et édité par THQ, sorti en 2005 sur Windows, PlayStation 2 et Xbox.

Il est basé sur le film du même nom.', 'https://fr.wikipedia.org/wiki/Constantine_(jeu_vid%C3%A9o)'),
  ('Q1646889', 'Taito Legends est une compilation de jeu vidéo développé et édité par Empire Interactive sorti en 2005 sur PlayStation 2, Xbox et Windows uniquement en occident.

Une compilation similaire nommée Taito Memories est sortie uniquement au Japon. Une suite nommée Taito Legends 2 est sortie l''année suivante.', 'https://fr.wikipedia.org/wiki/Taito_Legends'),
  ('Q1661316', 'Indiana Jones et le Tombeau de l''empereur est un jeu vidéo d''aventure sorti en avril 2003 et qui a été développé par The Collective et édité par LucasArts.', 'https://fr.wikipedia.org/wiki/Indiana_Jones_et_le_Tombeau_de_l%27empereur'),
  ('Q1639864', 'Disgaea: Hour of Darkness est un jeu vidéo de type tactical RPG développé par Nippon Ichi Software puis édité par Atlus aux États-Unis et Koei en Europe, sorti sur PlayStation 2 en 2003. Le jeu est réédité en décembre 2007 sur PSP et est sous-titré Afternoon of Darkness. Puis en juin 2008 sur Nintendo DS, renommé Disgaea DS. Une version pour téléphones portables est aussi sortie au Japon fin 2006.

Une suite, Disgaea 2: Cursed Memories, est sortie en 2006 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Disgaea:_Hour_of_Darkness'),
  ('Q11673882', 'Maximo vs. Army of Zin est un jeu vidéo d''action-aventure développé par Capcom pour la PlayStation 2. Le jeu est basé sur l''univers de la série Ghosts ''n Goblins.

Le jeu est une suite de Maximo: Ghosts to Glory.', 'https://fr.wikipedia.org/wiki/Maximo_vs._Army_of_Zin'),
  ('Q898020', 'Tenchu: Fatal Shadows (天誅 紅) est un jeu vidéo d''infiltration développé par K2 et édité par Sega aux États-Unis et en Europe, et édité par From Software au Japon. Le jeu est sorti sur Playstation 2 le 22 juillet 2004 au Japon, le 15 février 2005 aux États-Unis et le 6 mai 2005 en Europe. Le jeu est ensuite adapté sur PlayStation Portable et sort au Japon le 28 janvier 2010 sous le titre Tenchu Kurenai Portable.', 'https://fr.wikipedia.org/wiki/Tenchu:_Fatal_Shadows'),
  ('Q901223', 'Puyo Puyo! 15th Anniversary est un jeu de la série Puyo Puyo développé par Sonic Team et publié par Sega pour la Nintendo DS, PlayStation 2, PlayStation Portable et Wii. C''est le premier jeu de Puyo Puyo à sortir sur la console Wii. C''est un jeu commémoratif du 15e anniversaire de la série.', 'https://fr.wikipedia.org/wiki/Puyo_Puyo!_15th_Anniversary'),
  ('Q868260', 'Colin McRae Rally 04 est un jeu vidéo de course de rallye développé et édité par Codemasters, sorti en 2003 sur Windows, PlayStation 2 et Xbox. Il fait partie de la série Colin McRae Rally.', 'https://fr.wikipedia.org/wiki/Colin_McRae_Rally_04'),
  ('Q866397', 'Need for Speed: Poursuite infernale 2 (ou Need for Speed: Hot Pursuit 2 en anglais) est un jeu vidéo de course sorti en 2002. Il est le premier Need for Speed du studio de développement EA Black Box et des consoles de jeux de sixième génération.', 'https://fr.wikipedia.org/wiki/Need_for_Speed_:_Poursuite_infernale_2'),
  ('Q869511', 'Crash Bandicoot: La Vengeance de Cortex (Crash Bandicoot: The Wrath of Cortex dans la version originale; Crash Bandicoot 4: Sakuretsu! Majin Power au Japon) est un jeu vidéo de plates-formes développé par Traveller''s Tales et édité par Universal Interactive Studios sur PlayStation 2 en 2001, Xbox et GameCube en 2002. Il s''agit du quatrième opus de la série Crash Bandicoot, qui fait suite à Crash Bandicoot 3: Warped, sorti en novembre 1998.

Le scénario met en scène Crash Bandicoot et sa sœur Coco, qui doivent lutter contre Crunch Bandicoot, un bandicoot génétiquement modifié et doté d''un bras bionique, spécialement conçu par le Docteur Neo Cortex pour détruire Crash. Afin de rendre Crunch plus puissant, celui-ci est associé aux Masques des Éléments, des masques antiques libérés par Uka Uka, l''allié de Cortex. Il s''agit de Rok-Ko, le masque de la Terre; Wa-Wa, le masque de l''Eau; Py-Ro, le masque du Feu et Lo-Lo, le masque de l''Air. Dans cet opus, Crash et Coco parcourent le monde pour récupérer des cristaux capables d''enfermer les Masques des Éléments et bénéficient de nouveaux véhicules, comme une Jeep, un planeur, un sous-marin et une « atlasphère » — une sorte de boule de hamster que Crash pousse pour avancer.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_:_La_Vengeance_de_Cortex'),
  ('Q869522', 'Crash Tag Team Racing est un jeu vidéo de course et de plates-formes de la série Crash Bandicoot, sorti en octobre 2005 sur GameCube, Xbox, PlayStation 2 et PSP.', 'https://fr.wikipedia.org/wiki/Crash_Tag_Team_Racing'),
  ('Q869532', 'Crash of the Titans est un jeu vidéo de plates-formes développé par Radical Entertainment et édité par Sierra Entertainment. Chronologiquement, il est le sixième épisode de la série Crash Bandicoot, mais le quatorzième en comptant les jeux non-canons. Le jeu est sorti en 2007 sur PlayStation 2, Xbox 360, Wii, PlayStation Portable. D’autres versions sont aussi éditées sur Nintendo DS et Game Boy Advance, et ont été développées par Amaze Entertainment. Le titre du jeu est une référence au film Clash of the Titans; la majorité des noms de niveaux comportent des références cinématographiques.', 'https://fr.wikipedia.org/wiki/Crash_of_the_Titans'),
  ('Q910889', 'Persona 3, initialement commercialisé en interne sous le nom Shin Megami Tensei: Persona 3 est un jeu vidéo de rôle développé et édité au Japon et aux États-Unis par Atlus (édité en Europe par Koei et en Allemagne par THQ). Il est sorti sur PlayStation 2 en France le 29 février 2008. Une extension, Persona 3 FES, est sortie au Japon le 19 avril 2007 et en France le 17 octobre 2008. Elle ajoute diverses fonctions à l''aventure, comme un nouveau personnage, un mode difficile, un nouveau chapitre à la durée de vie estimée à une trentaine d''heures et quelques ajouts divers à l''aventure originale. Il remporte un succès commercial considérable, notamment aux États-Unis, et est proclamé "meilleur jeu de l''année 2007", ainsi que "meilleur RPG de l''année 2008". Par la suite, il entre au palmarès des "meilleurs jeux de tous les temps". Le jeu lui-même n''a jamais été traduit de l''anglais, dans l''édition française, seuls la boîte et le manuel sont en français.', 'https://fr.wikipedia.org/wiki/Persona_3_(jeu_vid%C3%A9o)'),
  ('Q4654952', 'ATV Offroad Fury 4 est un jeu vidéo de course développé par Climax Racing et publié par Sony Computer Entertainment pour PlayStation 2. Il est sorti le 31 octobre 2006 en Amérique du Nord, le 27 mars 2008 en Australie et un jour plus tard en Europe. Il s''agit du dernier jeu ATV Offroad Fury avant d''être fusionné avec la série MX vs. ATV.', 'https://fr.wikipedia.org/wiki/ATV_Offroad_Fury_4'),
  ('Q4691423', 'Agassi Tennis Generation est un jeu vidéo de sport (tennis) développé par Aqua Pacific et édité par DreamCatcher Interactive, sorti à partir de 2002 sur Windows, PlayStation 2 et Game Boy Advance (plate-forme sur laquelle le jeu se nomme Agassi Tennis Generation 2002 en Europe).

Il met en scène le champion Andre Agassi.', 'https://fr.wikipedia.org/wiki/Agassi_Tennis_Generation'),
  ('Q4698162', 'Air Ranger: Rescue Helicopter est un jeu vidéo de simulation de vol en hélicoptère développé et édité par ASK, sorti en 2001 sur PlayStation 2.

Il a pour suite Air Ranger 2: Rescue Helicopter et Air Ranger 2 Plus: Rescue Helicopter.', 'https://fr.wikipedia.org/wiki/Air_Ranger:_Rescue_Helicopter'),
  ('Q4701173', 'Akira Psycho Ball est un jeu vidéo de flipper développé par KAZe et édité par Bandai, sorti en 2002 sur PlayStation 2.

Il est basé sur le manga Akira de Katsuhiro Ōtomo.', 'https://fr.wikipedia.org/wiki/Akira_Psycho_Ball'),
  ('Q4672994', 'Ace Lightning est une série télévisée d''animation hybride britanno-canadienne en 39 épisodes de 23 minutes et diffusée entre le 4 septembre 2002 et le 14 décembre 2004 sur la BBC.

En France, la série a été diffusée sur France 2 et Disney Channel.', 'https://fr.wikipedia.org/wiki/Ace_Lightning'),
  ('Q4736268', 'Alter Echo est un jeu vidéo d''action développé par Outrage Entertainment et édité par THQ, sorti le 19 août 2003 en Amérique du Nord et le 3 octobre 2003 en Europe sur consoles PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Alter_Echo'),
  ('Q4736304', 'Altered Beast est un jeu vidéo de type beat them all développé et édité par Sega, sorti en 2005 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Altered_Beast_(jeu_vid%C3%A9o,_2005)'),
  ('Q4654949', 'ATV Offroad Fury 2 est un jeu vidéo de course développé par Rainbow Studios et édité par Sony Computer Entertainment, sorti exclusivement pour la PlayStation 2, le 12 novembre 2002 en Amérique du Nord et le 3 octobre 2003 en Europe.

Il fait suite à ATV Offroad Fury (2001). Il est le premier opus de la série ATV Offroad Fury à prendre en charge le multijoueur en ligne, utilisant à la fois une connexion haut débit et une connexion par ligne commutée.

Le jeu connaît une suite nommée ATV Offroad Fury 3 en 2004.', 'https://fr.wikipedia.org/wiki/ATV_Offroad_Fury_2'),
  ('Q4682685', 'Adibou et les Voleurs d''énergie est un jeu vidéo de plates-formes ludo-éducatif développé par Coktel Vision et édité par VU Games, sorti en 2004 sur Windows et PlayStation 2.', 'https://fr.wikipedia.org/wiki/Adibou_et_les_Voleurs_d%27%C3%A9nergie'),
  ('Q4050192', 'Stolen est un jeu vidéo d''infiltration développé par Blue 52 et édité par Hip Games, sorti en 2005 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Stolen_(jeu_vid%C3%A9o)'),
  ('Q4049861', 'Spawn: Armageddon est un jeu vidéo de type hack ''n'' slash développé par Point of View, Inc. et édité par Namco, sorti en 2003 sur GameCube, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Spawn:_Armageddon'),
  ('Q4049259', 'Sega Superstars est un jeu vidéo développé par Sonic Team et édité par Sega pour la PlayStation 2. Il est sorti en Europe le 22 octobre 2004, en Amérique du Nord le 2 novembre 2004, et au Japon le 11 novembre 2004. Le jeu propose plusieurs mini-jeux basés sur différents titres de Sega qui sont contrôlés à l''aide de la caméra EyeToy.', 'https://fr.wikipedia.org/wiki/Sega_Superstars'),
  ('Q4928508', 'BlowOut est un jeu vidéo de type run and gun développé par Terminal Reality et édité par Majesco Entertainment, sorti en 2003 sur Windows, GameCube, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/BlowOut'),
  ('Q4940645', 'Bomberman Jetters est un jeu vidéo d''action développé par Capcom et édité par Hudson Soft, sorti en 2002 sur GameCube, PlayStation 2 et Game Boy Advance.

Il est basé sur l''anime du même nom.', 'https://fr.wikipedia.org/wiki/Bomberman_Jetters_(jeu_vid%C3%A9o)'),
  ('Q4940522', 'Bombastic (XI Go) est un jeu vidéo de puzzle développé par Shift et édité par Sony Computer Entertainment, sur PlayStation 2.

Il fait suite à Devil Dice.', 'https://fr.wikipedia.org/wiki/Bombastic'),
  ('Q4936428', 'Bode Miller Alpine Skiing est un jeu vidéo de sport (ski) développé par 49Games et sorti en 2006 sur Windows et PlayStation 2.

Il tient son nom du champion Bode Miller.', 'https://fr.wikipedia.org/wiki/Bode_Miller_Alpine_Skiing'),
  ('Q15043247', 'Yanya Caballista: City Skater est un jeu vidéo de skateboard développé par Cave et édité par Koei, sorti en 2001 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Yanya_Caballista:_City_Skater'),
  ('Q15043233', 'Gunfighter II: Revenge of Jesse James est un jeu vidéo de tir à l''arme légère développé par Rebellion Developments et édité par Ubi Soft pour la PlayStation 2. C''est la suite du jeu Gunfighter: The Legend of Jesse James sorti en 2001. L''intrigue du jeu se déroule dans le Far West américain. Le protagoniste du jeu est Jesse James, un hors-la-loi américain qui a vécu au 19e siècle.', 'https://fr.wikipedia.org/wiki/Gunfighter_II:_Revenge_of_Jesse_James'),
  ('Q15043243', 'Thunderhawk: Operation Phoenix (Thunderstrike: Operation Phoenix en Amérique du Nord) est un jeu vidéo de simulation de vol de combat développé par Core Design et édité par Eidos Interactive, sorti en 2001 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Thunderhawk:_Operation_Phoenix'),
  ('Q5169540', 'Coraline (Coraline: An Adventure Too Weird for Words) est un jeu vidéo d''action-aventure développé par Papaya Studio, sorti en 2009 sur Wii, PlayStation 2 et Nintendo DS.

Il est adapté du film du même nom.', 'https://fr.wikipedia.org/wiki/Coraline_(jeu_vid%C3%A9o)'),
  ('Q5142421', 'Cold Winter est un jeu vidéo de tir à la première personne développé par Swordfish Studios et édité par Vivendi Universal Games, sorti en 2005 sur PlayStation 2. Il a été scénarisé par Warren Ellis.', 'https://fr.wikipedia.org/wiki/Cold_Winter'),
  ('Q5140006', 'Code Age Commanders: Tsugu Mono Tsuga Reru Mono est un jeu vidéo de type action-RPG développé par Square Enix Product Development Division 2 et édité par Square Enix, sorti en 2005 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Code_Age_Commanders:_Tsugu_Mono_Tsuga_Reru_Mono'),
  ('Q5158104', 'Conan est un jeu vidéo de type action-aventure et hack ''n'' slash développé par Cauldron et édité par TDK Mediactive, sorti en 2004 sur Windows, GameCube, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Conan_(jeu_vid%C3%A9o,_2004)'),
  ('Q11607031', 'Zoku Segare Ijiri est un jeu vidéo de puzzle développé et édité par Enix, sorti en 2002 sur PlayStation 2.

Il fait suite à Segare Ijiri.', 'https://fr.wikipedia.org/wiki/Zoku_Segare_Ijiri'),
  ('Q1776333', 'Hokuto no Ken Fighting est un jeu vidéo de combat développé par Arc System Works et édité par Sega. Il est sorti en 2005 sur borne d''arcade.

Le jeu a été porté en 2007 sur PlayStation 2 sous le nom Hokuto no Ken: Shinpan no Sōsōsei Kengō Retsuden. Tandis que la version arcade a été distribuée aux États-Unis, la version PlayStation 2 n''est jamais sorti en dehors des frontières japonaises.

Le jeu est dérivé du manga Ken le Survivant.', 'https://fr.wikipedia.org/wiki/Hokuto_no_Ken_Fighting'),
  ('Q1772256', 'Conflict Zone (anciennement Peacemakers) est un jeu de stratégie en temps réel en trois dimensions sorti sur PC, Dreamcast et PlayStation 2, développé par MASA Group, et édité par Ubisoft en mai 2001.', 'https://fr.wikipedia.org/wiki/Conflict_Zone'),
  ('Q5116115', 'Chulip est un jeu vidéo de simulation de vie développé par Punchline et édité par Victor Interactive Software, sorti en 2002 sur PlayStation 2 et réédité en 2012 sur le PlayStation Network.', 'https://fr.wikipedia.org/wiki/Chulip'),
  ('Q5123146', 'City Crisis est un jeu vidéo de simulation de vol en hélicoptère développé par Syscom Entertainment Inc. et édité par Take-Two Interactive, sorti en 2001 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/City_Crisis'),
  ('Q5139904', 'Cocoto Platform Jumper est un jeu vidéo de plateforme développé par Neko Entertainment et sorti en 2004. Le jeu est sorti sur différentes plateformes dans les régions PAL, notamment la GameCube, la PlayStation 2, la Game Boy Advance et Microsoft Windows. Il est sorti pour WiiWare en Amérique du Nord le 27 avril 2009 et dans les régions PAL le 12 juin 2009.', 'https://fr.wikipedia.org/wiki/Cocoto_Platform_Jumper'),
  ('Q4993362', 'Fire Pro Wrestling Returns est un jeu vidéo de combat développé par Spike, sorti en 2005 sur PlayStation 2 et PlayStation Network. Il fait partie de la série Fire Pro Wrestling.

Il est cité dans Les 1001 jeux vidéo auxquels il faut avoir joué dans sa vie.', 'https://fr.wikipedia.org/wiki/Fire_Pro_Wrestling_Returns'),
  ('Q4958333', 'Brave: The Search for Spirit Dancer est un jeu vidéo d''action-aventure développé par VIS Entertainment et édité par Sony Computer Entertainment, sorti en 2005 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Brave:_The_Search_for_Spirit_Dancer'),
  ('Q5015333', 'Cabela''s Dangerous Hunts 2 est un jeu vidéo d''action développé par Sand Grain Studios et édité par Activision, sorti en 2005 sur Windows, GameCube, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Cabela%27s_Dangerous_Hunts_2'),
  ('Q5015318', 'Cabela''s Big Game Hunter 2005 Adventures est un jeu vidéo d''action développé par Magic Wand Productions et édité par Activision Value, sorti en 2004 sur Windows, GameCube, PlayStation 2, Xbox et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Cabela%27s_Big_Game_Hunter_2005_Adventures'),
  ('Q910467', 'Cybernator, connu au Japon sous le nom Assault Suits Valken, est un jeu vidéo de plates-formes en scrolling horizontal développé par NCS Corp et édité en 1993 par Konami sur Super Nintendo.

C''est indirectement une préquelle de Target Earth.', 'https://fr.wikipedia.org/wiki/Cybernator'),
  ('Q907226', 'Metal Gear Solid 2: Sons of Liberty (communément abrégé MGS2) est un jeu vidéo d''action-infiltration produit et réalisé par Hideo Kojima, développé et édité par Konami, et sorti en novembre 2001 sur PlayStation 2.

Sons of Liberty connaît un succès public et critique, avec plus de 7 millions d''exemplaires vendus à travers le monde. Une version étendue du jeu, Metal Gear Solid 2: Substance, est commercialisée en 2002 au Japon.', 'https://fr.wikipedia.org/wiki/Metal_Gear_Solid_2:_Sons_of_Liberty'),
  ('Q16246188', 'Dynasty Tactics 2 est un jeu vidéo de type wargame développé et édité par Koei, sorti en 2003 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Dynasty_Tactics_2'),
  ('Q16258981', 'NFL Street 2 est un jeu vidéo de football américain développé par EA Sports BIG et édité par Electronic Arts. Il a été initialement publié sur PlayStation 2, GameCube et Xbox le 22 décembre 2004. Il présente alors l''ailier rapproché des Giants de New York Jeremy Shockey et le rappeur Xzibit sur la couverture. Le jeu est compatible avec Madden NFL 06, car les joueurs peuvent y importer leurs joueurs Own The City. La compatibilité du jeu s''étend également à d''autres jeux EA comme Need for Speed: Underground 2, SSX 3, Madden NFL 2005, NCAA Football 2005, NFL Street, GoldenEye: Au service du mal, NBA Live 2005 et NBA Street Vol. 2, où si les joueurs ont ces jeux sur leurs cartes mémoire, ils peuvent gagner 25 000 points dans le jeu.', 'https://fr.wikipedia.org/wiki/NFL_Street_2'),
  ('Q16202286', 'NHL 2K7 est un jeu vidéo de hockey sur glace développé par Visual Concepts et édité par 2K Sports. Le jeu sort en 2006 sur Xbox, PlayStation 2, Xbox 360 et PlayStation 3.', 'https://fr.wikipedia.org/wiki/NHL_2K7'),
  ('Q15116822', 'Tom Clancy''s Ghost Recon est un jeu vidéo développé par Red Storm Entertainment, une filiale d''Ubisoft, puis édité par Ubisoft en 2001 pour Windows initialement. Il a ensuite été porté pour Mac, Xbox, PlayStation 2, GameCube, N-Gage et enfin sur Wii. Une version sur Game Boy Advance était prévue, mais le projet fut annulé. Le jeu a été dirigé par Tom Clancy, mais n''est basé sur aucun de ses livres.

Le 1er septembre 2007 et les jours qui ont suivi, la version PC du jeu a été gratuitement distribuée par Ubisoft (mais en incluant des publicités), via un téléchargement libre et gratuit, pour peu de posséder un compte Ubi.com basé aux États-Unis. Cependant, l''installation n''est plus possible à partir du 6 septembre 2007.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Ghost_Recon_(jeu_vid%C3%A9o)'),
  ('Q16211857', 'Blade 2: Bloodlust est un jeu vidéo d''action développé par Mucky Foot Productions et édité par Activision, sorti en 2002 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Blade_2:_Bloodlust'),
  ('Q16259173', 'Rygar: The Legendary Adventure est un jeu vidéo d''action-aventure développé et édité par Tecmo, sorti en 2002 sur PlayStation 2 et réédité en 2008 sur Wii.

Il fait suite à Rygar.', 'https://fr.wikipedia.org/wiki/Rygar:_The_Legendary_Adventure'),
  ('Q16040952', 'Rally Championship est un jeu de course développé par Warthog Games et publié par SCI Entertainment.

Il propose une course de simulation de rallye avec un jeu orienté arcade, six rallyes et 33 parcours dans différentes régions du globe, 25 voitures licenciées et également un mode 4 joueurs.', 'https://fr.wikipedia.org/wiki/Rally_Championship_(jeu_vid%C3%A9o,_2003)'),
  ('Q16149289', 'MLB 09: The Show est un jeu vidéo de sport (baseball) développé par SIE San Diego Studio et édité par Sony Computer Entertainment, sorti en 2009 sur PlayStation 2, PlayStation 3 et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/MLB_09:_The_Show'),
  ('Q4926943', 'Blitz: The League est un jeu vidéo de football américain développé et édité par Midway Games appartenant à le série NFL Blitz. Le jeu a été publié en octobre 2005 sur PlayStation 2 et Xbox après que la Ligue Nationale de Football (NFL) a signé une licence exclusive avec Electronic Arts. Lawrence Taylor, qui prêtait sa voix au jeu, en était la porte parole officiel. Une deuxième version de ce jeu était sorti sur la Xbox 360 en octobre 2006. En décembre 2006, une version portable intitulé Blitz: Overtime a été publié sur PlayStation Portable. Ces versions inclus la voix et l''apparence de l''ancien joueur Bill Romanowski. Le jeu était à l''origine destiné à être un titre de lancement pour la Wii, mais la version a été retardée et finalement annulée.', 'https://fr.wikipedia.org/wiki/Blitz:_The_League'),
  ('Q4920197', 'Black and Bruised est un jeu vidéo de combat (boxe anglaise) développé par Digital Fiction et édité par Majesco Entertainment, sorti en 2003 sur GameCube et PlayStation 2.', 'https://fr.wikipedia.org/wiki/Black_and_Bruised'),
  ('Q4927744', 'Blood Will Tell: Tezuka Osamu''s Dororo, sorti sous le titre Dororo au Japon, est un jeu vidéo de PlayStation 2 édité par Sega. Il est basé sur le manga Dororo créé par Osamu Tezuka.', 'https://fr.wikipedia.org/wiki/Blood_Will_Tell'),
  ('Q4906062', 'Big Mutha Truckers est un jeu vidéo de course sorti en France en 2003 sur PlayStation 2, Xbox, GameCube et Windows. Le jeu est également porté sur Nintendo DS et Game Boy Advance en 2006. Sa suite, sortie en France en 2005, se nomme BMT 2: Truck Me Harder.

Se déroulant dans l''État fictionnel de Hick State County, dans le Sud profond des États-Unis, le jeu consiste à accomplir des trajets entre des villes, livrer des marchandises, et prendre part à des courses au volant d''un semi-remorque. Big Mutha Truckers n''a connu qu''un faible succès critique et commercial à cause de son gameplay repetitif, des graphismes datés, et une piètre ambiance sonore. La chanson-thème du jeu est « Born to Be Wild » de Steppenwolf.', 'https://fr.wikipedia.org/wiki/Big_Mutha_Truckers'),
  ('Q4744050', 'Pop Idol (American Idol en Amérique du Nord et Deutschland sucht den SuperStar en Allemagne) est un jeu vidéo de rythme développé par Hothouse Creations et édité par Codemasters, sur Windows, PlayStation 2 et Game Boy Advance. La version Américaine utilise des images de la deuxième saison de l''émission, dans lequel Ruben Studdard a remporté la saison, tandis que la version Royaume-Uni utilise des images de la première saison, dans laquelle Will Young a remporté la saison, et la version Allemande utilise des images de la première saison, dans laquelle Alexander Klaws a remporté la saison.

Il est basé sur l''émission britannique Pop Idol (et son homologue américain American Idol), déclinée dans de nombreux pays (Nouvelle Star en France).', 'https://fr.wikipedia.org/wiki/Pop_Idol_(jeu_vid%C3%A9o)'),
  ('Q4782578', 'Aqua Aqua: Wetrix 2 est un jeu vidéo de puzzle développé par Zed Two et sorti en 2000 sur PlayStation 2.

Il fait suite à Wetrix.', 'https://fr.wikipedia.org/wiki/Aqua_Aqua:_Wetrix_2'),
  ('Q4787557', 'Arctic Thunder est un jeu de course de motoneige développé par Midway Games et sorti en tant que jeu d''arcade ainsi que sur Sony PlayStation 2 et les consoles Xbox, étant un titre de lancement pour ce dernier. Il fait partie de la série Midway Thunder, qui comprenait également Hydro Thunder, 4 Wheel Thunder, Offroad Thunder et Hydro Thunder Hurricane.

La version Xbox de ce jeu n''est pas compatible avec la Xbox 360. Dans la version jeu d''arcade, les jets soufflent des vents froids ou chauds, selon le réglage, dans le visage du joueur pendant qu''il joue.', 'https://fr.wikipedia.org/wiki/Arctic_Thunder_(jeu_vid%C3%A9o)'),
  ('Q4779275', 'Ape Escape: Pumped and Primed est un jeu vidéo de type party game développé par SCE Japan Studio et édité par Sony Computer Entertainment, sorti en 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Ape_Escape:_Pumped_and_Primed'),
  ('Q4785046', 'Arc the Lad: End of Darkness est un jeu vidéo de type action-RPG développé par Cattle Call et édité par Sony Computer Entertainment, sorti en 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Arc_the_Lad:_End_of_Darkness'),
  ('Q4777510', 'Fourmiz Extreme Racing (titre original: Antz Extreme Racing) est un jeu vidéo de course édité par Empire Interactive, sorti en 2002 sur PlayStation 2, Xbox, Windows et Game Boy Advance. Le jeu est basé sur le film d''animation Fourmiz sorti en 1998.', 'https://fr.wikipedia.org/wiki/Fourmiz_Extreme_Racing'),
  ('Q11350697', 'Romancing SaGa est un jeu vidéo de rôle de la série SaGa développé et édité par Square sur Super Famicom le 28 janvier 1992 uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Romancing_SaGa'),
  ('Q1974230', 'The Warriors est un jeu vidéo du type beat them all sorti en 2005 sur PlayStation 2 et Xbox puis sur PlayStation Portable en 2007. Basé sur le film de Walter Hill, Les Guerriers de la nuit, ce jeu vidéo a été développé par Rockstar Toronto et édité par Rockstar Games.', 'https://fr.wikipedia.org/wiki/The_Warriors_(jeu_vid%C3%A9o)'),
  ('Q1975690', 'Dance Dance Revolution SuperNova est un jeu vidéo de rythme sorti en 2006 aux arcades, et en 2007 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Dance_Dance_Revolution_SuperNova'),
  ('Q1966446', 'TMNT est un jeu vidéo d''action développé par Ubisoft Montréal et édité par Ubisoft, sorti en 2007 sur GameCube, Wii, Nintendo DS, Game Boy Advance, Windows, PlayStation 2, PlayStation Portable et Xbox 360. Il est adapté du long métrage d''animation TMNT: Les Tortues Ninja.', 'https://fr.wikipedia.org/wiki/TMNT_(jeu_vid%C3%A9o)'),
  ('Q1955682', 'Guitar Hero 5 est un jeu vidéo de rythme sur PlayStation 2, PlayStation 3, Wii et Xbox 360. Le jeu fait partie de la série Guitar Hero.

Le jeu comporte 85 chansons tirées de 83 artistes différents qui pourront être jouées à la guitare, à la basse, à la batterie ou au chant. Le jeu est sorti en France le 11 septembre 2009.', 'https://fr.wikipedia.org/wiki/Guitar_Hero_5'),
  ('Q1957004', 'X-Men Legends est un jeu vidéo d''action-rôle développé par Raven Software et édité par Activision sur GameCube, PlayStation 2, et Xbox en 2004.', 'https://fr.wikipedia.org/wiki/X-Men_Legends'),
  ('Q1790756', 'Shadow of Memories, connu sous l''appellation Shadow of Destiny en Amérique du Nord, est un jeu vidéo d''aventure développé et édité par Konami, sorti en 2001 sur la console PlayStation 2. Le jeu a été adapté sur Windows et Xbox en 2002. Il a été écrit et dirigé par la conceptrice Junko Kawano.', 'https://fr.wikipedia.org/wiki/Shadow_of_Memories'),
  ('Q1799879', 'Manhunt 2 est un jeu vidéo d''action développé par Rockstar London et édité par Rockstar Games en 2007 sur PlayStation 2, Wii et PlayStation Portable. Il succède à Manhunt.

Le développement du jeu débute en 2004 chez Rockstar Vienna. À l''origine, le jeu doit sortir le 10 juillet 2007 en Amérique du Nord et le 13 juillet en Europe, mais devant la vague d''interdictions frappant le jeu, Take-Two Interactive la société mère de Rockstar Games, annonce son report à une date non définie, puis à la suite des modifications demandées apportées au jeu qui lui octroient le feu vert de l''ESRB, annonce une sortie pour le 31 octobre 2007, le jour d''Halloween. En Europe, Il sort finalement le 31 octobre 2008, un an après sa sortie nord-américaine.', 'https://fr.wikipedia.org/wiki/Manhunt_2'),
  ('Q1814366', 'Psi-Ops: The Mindgate Conspiracy est un jeu vidéo de tir à la troisième personne développé et édité par Midway Games, sorti en 2004 sur PlayStation 2, Xbox et Windows.', 'https://fr.wikipedia.org/wiki/Psi-Ops:_The_Mindgate_Conspiracy'),
  ('Q1798154', 'Guitar Hero II est un jeu de rythme sorti en 2006 sur PlayStation 2 et en 2007 sur Xbox 360. Il fait partie de la série Guitar Hero et fait suite à Guitar Hero, sorti l''année précédente.

Plus évoluée graphiquement que le premier opus de la série, cette version est adaptée notamment aux téléviseurs 16/9e. Le mode duel a été largement amélioré avec 3 déclinaisons: « duel » (comme dans Guitar Hero), « duel pro » (les deux joueurs jouent la même partition), et « coop » (les joueurs jouent deux instruments différents - guitares principale, rythmique et/ou basse).

Le joueur incarne toujours un guitariste et doit parvenir à jouer des chansons de rock avec le moins de fausses notes possible. Il est possible de jouer avec une guitare dédiée au jeu, ou à la manette. Cette guitare est équipée d''un capteur gyroscopique. Lorsque le joueur lève le manche, adoptant ainsi une position typique d''un guitar hero, le mode star power s''active, doublant le multiplicateur de points. À la manette, ce mode s''active par une simple pression d''un bouton.', 'https://fr.wikipedia.org/wiki/Guitar_Hero_II'),
  ('Q1799178', 'Guitar Hero: Metallica est un jeu de rythme consacré au groupe Metallica et à quelques autres groupes invités. Cette édition de Guitar Hero est disponible en Europe depuis le 22 mai 2009 sur PlayStation 2, PlayStation 3, Wii et Xbox 360. Pour l''occasion les quatre membres du groupe: Hetfield, Ulrich, Hammett et Trujillo, ont effectué une capture de mouvement pour leurs avatars dans le jeu.

Il fait partie de la série Guitar Hero et basé sur Guitar Hero: World Tour, c''est-à-dire que le jeu est jouable en groupe complet, avec la batterie, la guitare, la basse et le chant. Neversoft a précisé que selon eux cet épisode est le plus difficile de la série.', 'https://fr.wikipedia.org/wiki/Guitar_Hero:_Metallica'),
  ('Q1982922', 'Rayman contre les lapins crétins (Rayman Raving Rabbids) est un jeu vidéo de type party game. Il s''agit d''un jeu dérivé de la franchise Rayman, développé par Ubisoft Montpellier et édité par Ubisoft, sorti fin 2006/début 2007. Michel Ancel souhaita le développer sur Wii afin de tirer profit de la Wiimote, pour l''adapter ensuite aux autres consoles.

Ce jeu a donné lieu à une suite: Rayman contre les lapins encore plus crétins.', 'https://fr.wikipedia.org/wiki/Rayman_contre_les_lapins_cr%C3%A9tins'),
  ('Q1982333', 'Call of Duty: Le Jour de gloire (nommé Call of Duty: Finest Hour en anglais) est un jeu de tir à la première personne de la série des Call of Duty sorti à partir de 2004 sur PlayStation 2, Gamecube et Xbox qui se déroule lors de la Seconde Guerre mondiale.', 'https://fr.wikipedia.org/wiki/Call_of_Duty_:_Le_Jour_de_gloire'),
  ('Q1982441', 'Mobile Suit Gundam: Federation vs. Zeon est un jeu vidéo de tir à la troisième personne développé par Capcom Production Studio 1 et édité par Bandai en 2001 sur système d''arcade Naomi GD-ROM, puis porté sur PlayStation 2.

Une version légèrement améliorée nommée Mobile Suit Gundam: Federation vs. Zeon DX est sortie sur Dreamcast uniquement au Japon en 2002.', 'https://fr.wikipedia.org/wiki/Mobile_Suit_Gundam:_Federation_vs._Zeon'),
  ('Q4806160', 'Spy Fiction est un jeu vidéo d''infiltration développé par Access Games, sorti en 2003 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Spy_Fiction'),
  ('Q1897909', 'F1 2002 est un jeu vidéo de course développé par Visual Sciences et édité par EA Sports, sorti en 2002 sur Windows, GameCube, PlayStation 2, Xbox et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/F1_2002_(jeu_vid%C3%A9o)'),
  ('Q1880723', 'Scooby-Doo! Le Livre des ténèbres (Scooby-Doo! Mystery Mayhem) est un jeu vidéo d''action-aventure sorti en 2004 sur Game Boy Advance, GameCube, PlayStation 2 et Xbox. Il a été développé par A2M et édité par THQ. Il est issu de l''univers de Scooby-Doo.', 'https://fr.wikipedia.org/wiki/Scooby-Doo!_Le_Livre_des_t%C3%A9n%C3%A8bres'),
  ('Q4876931', 'Beat Down: Fists of Vengeance est un jeu vidéo de type beat them all développé par Cavia et édité par Capcom, sorti en 2005 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Beat_Down:_Fists_of_Vengeance'),
  ('Q4839888', 'Backyard Wrestling 2: There Goes the Neighbourhood est le second opus de la série Backyard Wrestling sorti sur PlayStation 2 et Xbox. La bande originale inclut des musiques d''Andrew W.K., Kool Keith, Insane Clown Posse, Bad Brains, Body Count, Six and Violence (en), Mudvayne, Saliva, Fall Out Boy et Hoobastank. Il est développé par Paradox Development et publié par Eidos Interactive.

La publicité pour la télévision comprend les Insane Clown Posse, Vampiro, New Jack et Major Gunns (en). Malgré les promesses d''une expérience de jeu améliorée par rapport à son prédécesseur Backyard Wrestling: Don''t Try This at Home (en), en y incluant une utilisation plus poussée de l''environnement, un bouton de contres et des prises de soumission, le jeu est un échec critique lors de sa sortie en 2004. Ses chiffres de vente sont toutefois respectables, avec près de 300 000 exemplaires vendus en 2005.', 'https://fr.wikipedia.org/wiki/Backyard_Wrestling_2:_There_Goes_the_Neighborhood'),
  ('Q1899287', 'ShellShock: Nam ''67 est un jeu d''action sorti sur PC, PlayStation 2 et Xbox qui place le joueur en 1967 en plein guerre du Vietnam. Le joueur prend le contrôle des G.I dans une sombre guerre qui les oppose aux Vietcongs. Le jeu est développé par Guerrilla Games et est sorti le 3 septembre 2004.

Il fait suite à Shellshock et précède Shellshock 2: Blood Trails.', 'https://fr.wikipedia.org/wiki/Shellshock:_Nam_%2767'),
  ('Q4835251', 'BCV: Battle Construction Vehicles, souvent abrégé en BCV, connu au Japon sous le nom Kensetsu Jūki Kenka Battle: Buchigire Kongō !!, est un jeu de combat sorti sur PlayStation 2 le 1er juin 2000 au Japon. Il est localisé en Europe par Midas Interactive Entertainment, le 28 novembre 2003. Le jeu est réédité sur PlayStation 3 le 29 février 2012. Le jeu est développé par Artdink, avec Satoshi Iwai en tant que producteur.

Sorti exclusivement au Japon et en Europe, le jeu appartient à la première génération de titres PlayStation 2. BCV met le protagoniste aux commandes d''engins de chantier, transformés en machines de combat: bulldozers, camion-grue, chariots élévateurs, etc. L''objectif est de défendre l''entreprise familiale face à des antagoniste à travers seize niveaux.', 'https://fr.wikipedia.org/wiki/BCV:_Battle_Construction_Vehicles'),
  ('Q1980812', 'Le Monde de Narnia: Le Lion, la Sorcière blanche et l''Armoire magique est jeu vidéo d''action-aventure sorti en 2005 sur Game Boy Advance, GameCube, Nintendo DS, PC, PlayStation 2 et Xbox. Il a été développé par Traveller''s Tales et édité par Buena Vista Games. Les versions sur consoles portables ont été développées par Griptonite Games.

Le jeu est basé sur le film du même nom, lui-même adapté du roman éponyme.', 'https://fr.wikipedia.org/wiki/Le_Monde_de_Narnia_:_Le_Lion,_la_Sorci%C3%A8re_blanche_et_l%27Armoire_magique_(jeu_vid%C3%A9o)'),
  ('Q4831008', 'Bloody Roar 3 est un jeu vidéo de combat développé par Hudson Soft et Eighting, sorti en 2000 sur borne d''arcade avant de sortir en 2001 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Bloody_Roar_3'),
  ('Q1984059', 'Driven to Destruction (titre américain: Test Drive: Eve of Destruction) est un jeu vidéo de course développé par Monster Games et édité par Atari Inc., sorti en 2004 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Driven_to_Destruction'),
  ('Q4811493', 'Astro Boy est un jeu vidéo d''action développé par Sonic Team et édité par Sega, sorti en 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Astro_Boy_(jeu_vid%C3%A9o,_2004)'),
  ('Q1855957', 'Nights into Dreams, stylisé NiGHTS into dreams..., est un jeu vidéo développé par Sonic Team pour Sega et sorti en 1996 sur Saturn. Il offre au joueur la possibilité de s''immerger dans sept niveaux oniriques issus des rêves de Elliot Edwards ou de Claris Sinclair, deux enfants aux rêves communs par l''apparition d''un étrange personnage volant: Nights.

Le jeu est publié le 5 juillet 1996 au Japon, fin août 1996 aux États-Unis et le 5 septembre 1996 en Europe.', 'https://fr.wikipedia.org/wiki/Nights_into_Dreams'),
  ('Q1886410', 'Viewtiful Joe est un jeu vidéo de type beat them all développé par le studio Capcom Production Studio 4 pour l''éditeur japonais Capcom. Le développement du jeu a été dirigé par Hideki Kamiya et fut produit par Atsushi Inaba.

Le jeu a été édité sur GameCube en 2003. Et fut ensuite porté sur PlayStation 2 par Clover Studio en 2004.', 'https://fr.wikipedia.org/wiki/Viewtiful_Joe'),
  ('Q1861162', 'Top Spin est un jeu vidéo de tennis développé par le studio français PAM et sorti sur Xbox en 2003. Le jeu a été adapté sur Windows et PlayStation 2.', 'https://fr.wikipedia.org/wiki/Top_Spin'),
  ('Q715292', 'Prince of Persia: Les Sables du Temps (Prince of Persia: The Sands of Time en version originale) est un jeu vidéo développé et édité par Ubisoft. Mélange de jeu de plates-formes et d’action, il est sorti en 2003 sur PC, PlayStation 2, Xbox et GameCube, puis a été adapté sur Game Boy Advance et téléphone mobile. Il est le quatrième jeu de la franchise Prince of Persia.

Le jeu raconte l''histoire du Prince de Perse qui, trompé par le Vizir, libère les Sables du Temps dans le palais du Sultan, ami de son père. Ceux-ci corrompent les êtres vivants et les transforment en Monstres des sables sous le contrôle du Vizir. Avec l''aide de Farah, fille du Maharajah d''Inde réduite en esclavage par le roi de Perse Shahraman, le joueur doit faire traverser au Prince tous les pièges du palais aidé par ses talents d''acrobate et les pouvoirs de la Dague du temps, arme magique permettant de contrôler le temps.', 'https://fr.wikipedia.org/wiki/Prince_of_Persia_:_Les_Sables_du_Temps'),
  ('Q720311', 'Frogger''s Adventures: The Rescue est un jeu vidéo d''action-aventure développé par Konami Computer Entertainment Hawaii et édité par Konami, sorti en 2003 sur Windows, GameCube et PlayStation 2.', 'https://fr.wikipedia.org/wiki/Frogger%27s_Adventures:_The_Rescue'),
  ('Q719740', 'FIFA 09 est un jeu vidéo de football développé et édité par Electronic Arts en 2008. Le jeu est disponible sur PlayStation 2, PlayStation 3, Xbox 360, Wii, Windows, Nintendo DS et PlayStation Portable.

C''est le 15e épisode la série FIFA Football. Le jeu est sorti en France le 2 octobre 2008.

Pour ce qui est des ventes, FIFA prend pour la première fois le dessus sur son rival PES.', 'https://fr.wikipedia.org/wiki/FIFA_09'),
  ('Q1988293', 'Popotan est un visual novel de type eroge japonais développé par Petit Ferret, avec pour designer Akio Watanabe dessinant sous le pseudonyme de Poyoyon Rock. Il est d''abord commercialisé en tant que jeu pour PC le 13 décembre 2002 puis est republié sous forme de DVD-ROM et pour PlayStation 2 avec certaines scènes retirées. Le titre Popotan est un mot absurde destiné à refléter la proéminence des pissenlits, nommé tanpopo en japonais.

Petit Ferret produit un fan disc peu de temps avant la recommercialisation du DVD-ROM. Popotan est adapté en une série de romans (Popotan～ Himitsu no Jumon～ Kōhen) par Sassami Yachiruda, en une série de mangas par Yūjiro Izumi, en un anime de douze épisodes réalisé par Shinichiro Kimura et édité en Amérique du Nord par Geneon USA et plus tard par Sentai Filmworks, puis en une série radiophonique (Poporaji), et enfin en plusieurs ouvrages d''art et de référence.', 'https://fr.wikipedia.org/wiki/Popotan'),
  ('Q1988599', 'Pro Evolution Soccer 3 (Winning Eleven 7, abrégé PES 3) est un jeu vidéo de football, sorti en 2003 sur PlayStation 2 et PC.

Développé et édité par Konami, ce jeu fait partie de la série des "Pro Evolution Soccer".', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_3'),
  ('Q5182322', 'Crash ''n'' Burn est un jeu vidéo de combat motorisé et de course développé par Climax Racing et édité par Eidos Interactive, sorti en 2004 sur PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Crash_%27n%27_Burn_(jeu_vid%C3%A9o,_2004)'),
  ('Q5185711', 'Crimson Tears est un jeu vidéo de type beat them all en cel shading développé par Spike et DreamFactory, édité par Capcom, sorti en 2004 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Crimson_Tears'),
  ('Q5195246', 'Curse: The Eye of Isis est un jeu vidéo de type survival horror développé par Asylum Entertainment et édité par DreamCatcher Interactive, sorti en 2003 sur Windows, PlayStation 2 et Xbox.', 'https://fr.wikipedia.org/wiki/Curse:_The_Eye_of_Isis'),
  ('Q5197739', 'Cyber Troopers Virtual-On Marz est un jeu vidéo de combat développé par Hitmaker et édité par Sega, sorti en 2003 sur PlayStation 2 et PlayStation Network.', 'https://fr.wikipedia.org/wiki/Cyber_Troopers_Virtual-On_Marz'),
  ('Q1750961', 'DRIV3R ou Driver 3 est un jeu vidéo développé par Reflections Software et édité par Atari Inc.. Il sort sur PlayStation 2 le 25 juin 2004, sur Xbox le même jour, sur Windows le 18 mars 2005 et en septembre 2005 sur Game Boy Advance. La sortie sur GameCube a été annulée, quant à celle sur Windows, elle bénéficie de bonus; un making of et un niveau supplémentaire.

Ce jeu est le troisième épisode de la série, ayant débuté sur PlayStation avec Driver, suivi de Driver 2 et se poursuivant avec Driver Parallel Lines.', 'https://fr.wikipedia.org/wiki/DRIV3R'),
  ('Q1750568', 'FIFA 06 est un jeu vidéo de football développé et édité par Electronic Arts en 2005.

Le jeu est développé par EA Canada et édité par EA Sports. Il est disponible sur PlayStation 2, Xbox, Nintendo GameCube, Microsoft Windows, Game Boy Advance, Nintendo DS, PlayStation Portable ainsi que sur téléphones portables.

FIFA 06 est le treizième épisode de la série FIFA Football et le dixième en 3D. Il est aussi le premier titre de la série à ne pas sortir sur PlayStation.

Ronaldinho et Wayne Rooney figurent sur les jaquettes européenne, brésilienne et australienne du jeu tandis que Freddy Adu, Ronaldinho et Omar Bravo sont présents sur la boîte nord-américaine. Lukas Podolski est avec Ronaldinho dans la version allemande du jeu. Park Chu-Young apparaît quant à lui sur la version sud-coréenne.', 'https://fr.wikipedia.org/wiki/FIFA_06'),
  ('Q1753454', 'The Thing est un jeu vidéo de type survival horror. Il reprend la trame du film du même nom. Ce jeu est sorti en 2002 sur Xbox, PlayStation 2 et PC. Une édition remastérisée développée par Nightdive Studios est sortie fin 2024 sur Nintendo Switch, PlayStation 4, PlayStation 5, Windows, Xbox One et Xbox Series S/X.', 'https://fr.wikipedia.org/wiki/The_Thing_(jeu_vid%C3%A9o)'),
  ('Q725280', 'FIFA 07 est un jeu vidéo de football développé et édité par Electronic Arts en 2006. Il fait partie de la série FIFA Football.', 'https://fr.wikipedia.org/wiki/FIFA_07'),
  ('Q1984783', 'Bionicle (Bionicle: The Game) est un jeu vidéo d''action-aventure développé par Argonaut Sheffield et édité par Electronic Arts, sorti en 2003 sur Windows, Mac, GameCube, PlayStation 2, Xbox et Game Boy Advance.

Il est basé sur la gamme de jouets Lego du même nom et en partie sur le film d''animation Bionicle: Le Masque de Lumière.', 'https://fr.wikipedia.org/wiki/Bionicle_(jeu_vid%C3%A9o,_2003)'),
  ('Q1984869', 'Superman: Shadow of Apokolips est un jeu vidéo d''action-aventure sorti en 2002 sur PlayStation 2 et en 2003 sur GameCube. Le jeu a été développé par Infogrames et édité par Atari. Il est adapté de la série d''animation Superman, l''Ange de Metropolis. Aussi, Shadow est une suite chronologique de Superman: Countdown to Apokolips sorti en 2003.', 'https://fr.wikipedia.org/wiki/Superman:_Shadow_of_Apokolips'),
  ('Q1989054', 'Les Sims 2: Naufragés (en anglais: The Sims 2: Castaway) est un jeu vidéo de simulation de vie sorti en 2007, développé par EA Redwood Shores sur PlayStation 2 et Wii et par Full Fat sur Nintendo DS et édité par Electronic Arts. Il s''agit d''un spin-off du jeu Les Sims 2.', 'https://fr.wikipedia.org/wiki/Les_Sims_2_:_Naufrag%C3%A9s'),
  ('Q1992543', 'Ghosthunter est un jeu vidéo de tir à la troisième personne développé par SCE Cambridge Studio et édité par Sony Computer Entertainment, sorti en 2003 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Ghosthunter'),
  ('Q1987250', 'Pro Evolution Soccer 2013 (abrégé en PES 2013 et connu sous le nom de World Soccer: Winning Eleven 2013 en Asie), est un jeu vidéo de la série Pro Evolution Soccer développée et publiée par Konami. Le jeu est officiellement annoncé par Konami le 18 avril 2012.

La première démo est sortie officiellement le 25 juillet. Les équipes jouables sont l''Allemagne, l''Angleterre, l''Italie, le Portugal, le Fluminense FC, le Santos FC, le CR Flamengo et le SC Internacional.

La seconde démo est parue le 28 août sur Xbox 360, le 29 août sur PlayStation 3 et quelques jours après sur Windows. Onze équipes sont disponibles et le mode entrainement sera disponible.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_2013'),
  ('Q1990913', 'WWE SmackDown vs. Raw 2008 est un jeu vidéo de catch professionnel développé par Yuke''s et commercialisé sur consoles PS2, PS3, Xbox 360, Wii, PlayStation Portable et Nintendo DS par THQ en novembre 2007. Amaze Entertainment s''est occupé de la version Nintendo DS.

Le jeu est la neuvième édition de la longue série de jeux vidéo WWE SmackDown vs. Raw basée sur la promotion de catch professionnel World Wrestling Entertainment (WWE). Il est le premier jeu de la WWE à inclure la promotion et la division ECW. C''est également le seul jeu de la WWE disponible sur toutes consoles confondues de la septième génération.', 'https://fr.wikipedia.org/wiki/WWE_SmackDown_vs._Raw_2008'),
  ('Q1991104', 'Pro Evolution Soccer 5 (Winning Eleven 9, abrégé PES 5) est un jeu de simulation de football sorti sur les consoles PlayStation 2, PSP et Xbox ainsi que sur PC.

Il met en scène les plus grandes équipes européennes et mondiales. Les joueurs et les actions de jeu sont d''un réalisme tel qu''on se croirait dans un stade.

Considéré par beaucoup comme le meilleur opus pour la pureté de son gameplay, son équilibre, et son réalisme. Il fait l’unanimité sur de nombreux forums et articles spécialisés, reconnu comme “le plus équilibré et réaliste” de la série.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_5'),
  ('Q12972416', 'Victorious Boxers: Ippo''s Road to Glory est un jeu vidéo de combat (boxe) développé par New Corporation, sorti en 2000 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Victorious_Boxers:_Ippo%27s_Road_to_Glory'),
  ('Q12972820', 'Yu-Gi-Oh! Capsule Monster Coliseum est sorti sur Playstation 2 en 2004. Contrairement aux autres jeux vidéo Yu-Gi-Oh, il se concentrait sur le moins connu Yu-Gi-Oh! Capsule Monsters Collectible Figure Game présenté dans le manga. C''était avant la sortie du spin-off de l''anime Capsule Monsters.', 'https://fr.wikipedia.org/wiki/Yu-Gi-Oh!_Capsule_Monster_Coliseum'),
  ('Q14447827', 'Aggressive Inline est un jeu vidéo de roller en ligne (d''où le nom anglais d''inline) créé par Z-Axis. Il est sorti fin 2002 sur Game Boy Advance, GameCube, PlayStation 2 et Xbox.

Des skaters professionnels sont présents dans le jeu, comme Chris Edwards, Franky Morales ou Taïg Khris.', 'https://fr.wikipedia.org/wiki/Aggressive_Inline'),
  ('Q5610340', 'Grooverider: Slot Car Racing (connu en Amérique du Nord sous le titre Grooverider: Slot Car Thunder) est un jeu vidéo de course de slot racing développé par le studio anglais King of the Jungle, sorti en 2003 sur GameCube et Xbox en Amérique du Nord, puis en 2005 sur PlayStation 2 en Europe. Il propose 40 véhicules et 20 circuits répartis dans 5 environnements situés dans une maison virtuelle. Parmi les fonctionnalités de gameplay, on trouve le changement de voie pour éviter des obstacles ou pour dépasser, 3 niveaux de puissance pour les voitures (correspondant à trois modes de difficulté), et des power-ups disséminés sur les circuits.', 'https://fr.wikipedia.org/wiki/Grooverider:_Slot_Car_Racing'),
  ('Q5652731', 'Happy Feet est un jeu vidéo d''action-aventure et de rythme développé par Artificial Mind and Movement et édité par Midway Games, sorti en 2006 sur Windows, GameCube, Wii, PlayStation 2, Game Boy Advance et Nintendo DS.

Il s''agit de l''adaptation du film du même nom.', 'https://fr.wikipedia.org/wiki/Happy_Feet_(jeu_vid%C3%A9o)'),
