  ('Q90654110', 'ESPN NBA 2Night est un jeu vidéo de basket-ball développé et édité par Konami, sorti en 2000 sur Dreamcast et PlayStation 2.

Il a pour suite ESPN NBA 2Night 2002.', 'https://fr.wikipedia.org/wiki/ESPN_NBA_2Night'),
  ('Q85758186', 'ESPN NHL Hockey est un jeu vidéo de hockey sur glace développé par Kush Games et édité par Sega. Le jeu sort en 2003 sur Xbox et PlayStation 2.', 'https://fr.wikipedia.org/wiki/ESPN_NHL_Hockey'),
  ('Q85804292', 'Surfing H3O est un jeu vidéo de surf développé par Opus et sorti en 2000 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Surfing_H3O'),
